window.__D("text/maamarei-admur-hazaken/c012",{"p":[[2101000164,"מן ההעלם כו', ופי' יהללו י\"ה היינו גם לאורות דאו\"א שנק' י\"ה יהללו י\"ה יהללו מן ההעלם והוא מבחי' קוש\"י שנק' כתר בכלל וגם קוש\"י שבשם הוי' יהללו ממקורו הנעלם בעצמותו המאציל כו' וד\"ל.\n<b>והנה</b> כתיב עזי<sup data-n=\"957\">41</sup> וזמרת י\"ה ויה\"י לי לישועה כו' שהוא בחי' ההילול הנ\"ל בפסוד\"ז נמשך בחי' אורות מקיפים שנק' ישועות והוא בחי' ש\"ע נהורין שנמשך בהסתכלות דעליון בתחתון ע\"י בחי' הסתכלותו דתחתון בעליון כי ע\"י סידור השבחי' בפסוד\"ז בכללות נש\"י כלפי מעלה הוא בחי' לאסתכלא ביקרא דמלכא בשבחי' הגנוזים בו כנ\"ל, ועוצם בחי' התענוג המלובש בסיפור שבחים בהסתכלות זאת מעורר למעלה בחי' תענוג הפשוט המלובש בבחי' דאא\"ס שבכתר להיות בחי' גילוי ההעלם כמו בהילו נרו כו' וכנ\"ל בענין אין אשה אלא ליופי כו', וזהו ענין הקישוטין דכלה שמקבלת בפסוד\"ז דוקא כמ\"ש בפע\"ח ואז יוכל להיות בחי' יחודי' עליונים דאו\"א וזו\"ן בק\"ש ותפילה וכנ\"ל במשל דעין רואה ולב חומד וזה שגזרו אומר דלעולם יסדר שבחו של מקום תחילה ואז יוכל להיות יחוד עליון בתפילה באהוי\"ר כו', כי עין רואה לאסתכלא כו' הוא מקור החמדה שבלב באהוי\"ר כו' כמובן ממשל הנ\"ל וד\"ל.\n<b>וזהו</b> יונתי בחגוי הסלע בסתר המדריגה כו', פי' יונתי הוא בחי' מקור כללות כל נש\"י שהוא בחי' מל' דאצי' שנק' יונה עד\"מ היונה שמסתכלת בזכר כו' וכמ\"ש עיניך יונים כו' וגם כתי' עיני כל אליך כו' וכנ\"ל, וע\"ד פרט הוא כל ניצוץ פרטי המלובש בגוף גשמי כנ\"ל שיש בה בחי' לאסתכלא ביקרא דמלכא כנ\"ל נק' ג\"כ יונתי כו' וד\"ל. ומ\"ש יונתי בחגוי הסלע כו' הנה הוא בחי' ירידת המל' מהעלם וצמצום ההסתר הגדול בעולמות להיות ראש לשועלים כו' ובניצוץ האלקי היינו בחי' התלבשותה והתעלמותה בחומר הגוף כו', והטעם שנק' סלע הנה יובן בהקדים תחילה שרש ענין הסלע הגשמי דהנה אנו רואי' שהסלע הוא אבן קשה ביותר וזה הקושי בא מסיבת תוקף היבשות והעדר הלחלוחי' שהרי גידולו בעפר קשה ויבש דוקא כמ\"ש עד<sup data-n=\"958\">42</sup> שיגיע לסלע כו' כמו שנראה לעין שאין הסלעים נמצאים רק במקומות היבשות ביותר כמו במדבר ובהרים הגבוהים ששם תוקף החמימות מכלה ושורף כל הלחלוחי' שבארץ ומזה סיבת התהוות הסלעים קשים וע\"כ נק' הסלע בשם צור שממנו יוצאות האש כידוע כי יסוד האש בסלע וצור יש בתוקף גדול מטעם זה אך הנה בחי' החמימות והיבישות הזאת שבסלע וצור הוא בהעלם גדול מאד וע\"כ הוא קשה ביותר כמו הברזל שהוא קשה כי מצד כח יסוד האש שנתכווץ בו מאד כי כל קשיון בא מפני בחי' ההעלם והכווץ וכמ\"ש ארץ<sup data-n=\"959\">43</sup> אשר אבניה ברזל מצד חלקי יסוד האש<sup data-n=\"960\">44</sup> שנתקשו מאד וכל רפיון בא מפני בחי' התפשטות יסוד האש והלחלוחי' כו' וראי' לדבר ממים שנותני' על הברזל שבאש שעי\"ז מתקשה דוקא (וכן מים<sup data-n=\"961\">45</sup> קרים על נפש העיפה בחמימו' מתיקו כנ\"ל).",[["957","41","<b>עזי וזמרת י\"ה</b>: בשלח טו, ב."],["958","42","<b>עד שיגיע לסלע</b>: ראה פסחים י, א. בכורות כה, ב. ובכ\"מ."],["959","43","<b>ארץ אשר אבניה ברזל</b>: דברים ח, ט."],["960","44","<b>האש</b>: בכת\"י ב וכת\"י ג: המים."],["961","45","<b>מים קרים על נפש העיפה</b>: משלי כה, כה."]]],[2101000165,"<b>והנה</b> אנו רואי' שיש ג\"כ בסלע וצור מחלקי יסוד המים שהרי יוציא מים מן הצור וסלע דוקא כמ\"ש משה המן<sup data-n=\"962\">46</sup> הסלע הזה נוציא לכם מים וכתיב הכה<sup data-n=\"963\">47</sup> צור ויזובו מים כו' והכית<sup data-n=\"964\">48</sup> בצור כו' דמשמע שיש בדרך הטבע להוציא מים מצור החלמיש אעפ\"י שהוא קשה ביותר מתגבורת יסוד האש, אך הענין הוא בסלע וצור יש ב' דברים הא' גופו של הסלע שהוא אבן פשוט ששרש עצמותו מחלקי יסוד המים כמ\"ש אבנים<sup data-n=\"965\">49</sup> שחקו מים כו', ומה שהאבן קשה הוא רק כווץ חלקי יסוד המים ביותר משא\"כ המתכו' והברזל שהוא מכווץ יסוד האש כו' וכמ\"ש בסוף הע\"ח דאר\"מ שבעפר הדומם מתחלקים למיניהם דמתכת לאבנים כו' אך קצת יש באבן מחלקי החום מאחר שגם הוא מסיבת היבשות אך הוא כיווץ כל חלקי הלחלוחי' כשמתקשה מסבת החום כו' משא\"כ בסלע וצור שהחום יגבור מכח חום השמש שמכה בו כו', ונמצא שיש בסלע וצור מחלקי יסוד המים רק שהוא בהעלם גדול מפני שנתקשה חלקי המים מאד והב' חלקי האש שנתקשה בו כנ\"ל (והגם<sup data-n=\"966\">50</sup> דבקיעת סלע להוציא מים היא תגבורת חלקי המים על חלקי האש כו' אמנם יוכל להיות ריבוי שטף מים והפשרות הקושי' דסלע כו').\n<b>והנה</b> עוד דבר א' מורכב במציאות הסלע והצור והוא השמן כמ\"ש ושמן<sup data-n=\"967\">51</sup> מחלמיש צור כו' וכידוע בס' הטבע ג\"כ טבע השמן הנה הוא מורכב מיסוד האש ויסוד המים כו' הנה עצם מהות השמן הוא רק לחלוחי' שמנה ולחלוחי' הוא רק מחלקי המים והשמנוני' הוא בחי' כח הנעלם שמתפשט במים כמו ארץ שמנה שמגדלת תבואה בריבוי התפשטו' אעפ\"י שכל גידול וצמיחה הוא רק מחלקי המים אבל כל שהלחלוחית שמינה תתפשט בריבוי יותר וגם בכח וחיות יותר כמ\"ש ויתן<sup data-n=\"968\">52</sup> לך כו' משמני ארץ שהתבואה מלאה שבולת שמינות ויפות ובהעדר השמנונית יהי' דקות ורעות כידוע אמנם יש בשמן גם מחלקי האש שהרי השמן ידלק באש ונמשך אחר האור וגוון האור לפ\"ע צלילת השמן כנודע ובהכרח שיש בו בהעלם מחלק האש שנמצאי' בסלע וצור ג' דברים מורכבים מים ואש ושמן וכולם הם בבחי' הקושי' וההעלם שנק' כווץ כי יסוד האש מתקשה בו בהעלם כנ\"ל וגם יסוד המים מתקשה ומתכווץ בו כנ\"ל וגם חלק השמן המורכב בו הוא בהעלם וקושי' שהרי מבחי' חלקי האש והמים שבו שנתקשה בו מהם יוציאו השמן וז\"ש ושמן מחלמיש צור וד\"ל.\n<b>והנמשל</b> מכ\"ז יובן למעלה בבחי' סלע העליון שהוא בחי' מל' דאצי' כמ\"ש אבן<sup data-n=\"969\">53</sup> מאסו הבונים כו' א' ב\"ן ולפעמי' נק' סלע כשמסתתרת בבריאה בבחי'",[["962","46","<b>המן הסלע הזה נוציא לכם מים</b>: במדבר כ, י."],["963","47","<b>הכה צור ויזובו מים</b>: תהלים עח, כ."],["964","48","<b>והכית בצור</b>: שמות יז, ו."],["965","49","<b>אבנים שחקו מים</b>: איוב יד, יט."],["966","50","<b>והגם דבקיעת</b>: בכת\"י ב וכת\"י ג: והנס דבקיעת."],["967","51","<b>ושמן מחלמיש צור</b>: דברים לב, יג."],["968","52","<b>ויתן לך כו' משמני ארץ</b>: בראשית כז, כח."],["969","53","<b>אבן מאסו הבונים</b>: תהלים קיח, כב. וראה שער היחוד והאמונה פ\"ז. תו\"א משפטים עח, ב. לקו\"ת ראה כז, יג."]]],[2101000166,"העלם והסתר ביותר כמו עד\"מ סלע גשמי שמתעלם ומתקשה בו ג' דברים אש ומים ושמן כנ\"ל, וידוע דאש ומים למעלה הן בחי' חו\"ג ושמן הוא בחי' החכ' וכולם בבחי' ההעלם וההסתר דהיינו שהאורו' הן בבחי' עיבור וההעלם שנק' בחי' מילו\"י ומילו\"י דמילו\"י והוא בחי' שם אהי' דיודי\"ן בגי' סל\"ע כמ\"ש בע\"ח שהוא שרש בחי' ההעלם וההסתר הזה אשר בחי' אורות שבתוהו שהן בבחי' ההעלם וההסתר ובירידתן למטה נק' סלע או אבן לפי שענין המילו\"י הוא ענין ההסתר כמבואר במ\"א וכמ\"ש<sup data-n=\"970\">54</sup> בר\"מ בפי' איתן מושביך ושים בסלע קינך שהוא בחי' אור הכתר כשהוא בהעלם בבחי' מקיף ולפעמים נק' צור או סלע שהן ה\"ג דבצד\"ק וה\"ח ובחי' ח\"ס הכלולה מחו\"ג ג\"כ בהעלם כו', וז\"ש אין<sup data-n=\"971\">55</sup> צור כאלהינו ואמר בזוהר אית צור ואית צור כו' שהוא בחי' אהי' דיודי\"ן שבכתר ושבבינה ומל' כו' וד\"ל וכמו\"כ בחי' תושבע\"פ<sup data-n=\"972\">56</sup> מל' קרינן לה צור וסלע והוא מ\"ש משה המן הסלע הזה כו' שהוא בחי' מים דאורייתא שיצא לגילוי מבחי' העלם דחכ' שבצור העליון וכתי' וכפטיש<sup data-n=\"973\">57</sup> יפוצץ סלע שהן ה\"ג דבצ\"ק כו' שיש בחי' ה\"ח וה' גבורות המוציאין העלם החכ' דאוריי' לידי גילוי וכמו שיש ענין הפלפול בקושיו' ותירוצים בהוויו' דאביי ורבא<sup data-n=\"974\">58</sup> כי ההלכות נתעלמו ונתקשו בחכ' הנעלמה כו' וע\"י הפלפול יוצאי' לידי גילוי מן ההעלם וזהו ענין הפלפול להקשות קושי' להעלים ולהסתיר ואח\"כ יצא לאור האמיתי כידוע כמו המי' שנתכווצו בצור ונתקשו מאד כנ\"ל יוצאי' ע\"י ההכא' בפטיש שהוא בחי' ה\"ג שהוא בחי' הפלפול בקושי' כו' וז\"ש הכה צור ויזובו מים כו' ולפעמי' יוצאי' בבחי' גבו' כאש כמ\"ש מימינו<sup data-n=\"975\">59</sup> אש דת למו וכמ\"ש בגמ' זקוקין<sup data-n=\"976\">60</sup> דנורא מפומא דרבי' כו' וכמ\"ש הלא<sup data-n=\"977\">61</sup> דברי כאש כו', ולזה רמזו רז\"ל<sup data-n=\"978\">62</sup> באמרו נר<sup data-n=\"979\">63</sup> ישראל כלול מחו\"ג ועמוד הימיני מבחי' ה\"ח שבח\"ס בבחי' קו הימין חח\"נ ופטיש החזק מבחי' גבורו' שבח\"ס ולפעמים נק' מעין<sup data-n=\"980\">64</sup> המתגבר כו' ולכך אז\"ל במחשכים<sup data-n=\"981\">65</sup> הושיבני חושך דתוהו זה תלמוד בבלי והוא מ\"ש איתן מושביך כו' כמ\"ש בר\"מ ע\"ש וד\"ל, ושרש ההסתר הזה מבחי' אורות דתוהו שהן אורות תקיפין וקשין כסלע והן בחי' העלם כו', והנה עד\"ז יובן ג\"כ למטה בניצוץ הפרטי בגופו של אדם ששרש נה\"ב מבחי' ההעלם דתוהו ובשבירה ירדו הכלים ונשברו ונתגשם השפע עד שנתהוו' נה\"ב והוא בחי' הסתר והעלם גמור לאור ניצוץ האלקי ונק' סלע החופף ומסתיר ממש על האור הגנוז בתוך הסדקי' שבה והוא אור הניצוץ שגנוז ומוסתר בחגוי הסלע כו' וכך למעלה בבחי' נשמה כללי' בחי' מל' דאצי' מסתתרת בבי\"ע שנק' חגוי הסלע (וכמ\"ש",[["970","54","<b>וכמ\"ש בר\"מ בפי' איתן מושביך</b>: ראה זח\"ב קי, א."],["971","55","<b>אין צור כאלקינו ואמר בזוהר אית צור ואית צור</b>: שמואל א ב, ב. זח\"ג מד, א."],["972","56","<b>תושבע\"פ מל' קרינן לה</b>: ת\"ז בהקדמה ד\"ה פתח אליהו."],["973","57","<b>וכפטיש יפוצץ סלע</b>: ירמי' כג, כט."],["974","58","<b>בהוויות דאביי ורבא</b>: סוכה כח, ב."],["975","59","<b>מימינו אש דת למו</b>: דברים לג, ב."],["976","60","<b>זקוקין דנורא מפומא דרבי'</b>: צ\"ל: מפומי' דרב. ראה חולין קלז, ב."],["977","61","<b>הלא כה דברי כאש</b>: ירמי' כג, כט."],["978","62","<b>רז\"ל באמרו</b>: בכת\"י ב וכת\"י ג: ולזה רמזו באמרם."],["979","63","<b>נר ישראל</b>: ברכות כח, א. ובכ\"מ."],["980","64","<b>מעין המתגבר</b>: אבות פ\"ב מ\"ח. ועוד."],["981","65","<b>במחשכים הושיבני. . זה תלמוד בבלי</b>: איכה ג, ו. סנהדרין כד, א."]]],[2101000167,"במ\"א בפי' מושיבי<sup data-n=\"982\">66</sup> עקרת הבית וארז\"ל כחולדה<sup data-n=\"983\">67</sup> זו שדרה בעיקרי הבתים דהיינו כמו שמסתתרת בחגוי הסלע כו') אך כמו סיבת ההסתר דיונה גשמי' בחגוי הסלע לשמירה מן החום או הגשם והשלג כך למעלה מסתתרת המל' בבחי' ההסתר דסלע העליון לשמירה מעוצם תגבורת הגבו' כמ\"ש שזפתני<sup data-n=\"984\">68</sup> השמש או תגבורת הח' כמ\"ש לא<sup data-n=\"985\">69</sup> תירא לביתה משלג כו' וע\"כ מסתתרת בחגוי הסלע דוקא וד\"ל.\n<b>וזהו</b> יונתי בחגוי הסלע בסתר המדריגה פי' בסתר הוא בחי' הירידה בהסתר והעלם למטה כנ\"ל, והנה לפי\"ז סותר מ\"ש בשם מדריגה כי המדריג' עשוי' לעלות ממטה למעלה דוקא ואיך אמר ב' הפכי' בענין א' בסתר המדריגה, אך הענין הוא דשניהם אמת ויובן בהקדים ענין א' הידוע בפי' והחיות<sup data-n=\"986\">70</sup> נושאות את הכסא כו' אשר יפלא מאד איך יאמר שיהי' בכח החיות שהן נבראי' בע\"ג להעלות לבחי' כסא של אדה\"ע כמ\"ש עה\"כ<sup data-n=\"987\">71</sup> דמות כמראה אדם כו' (ואעפ\"י שארון<sup data-n=\"988\">72</sup> נושאיו נשא כו' אעפי\"כ גם זה אמת שהחיות נושאות את הכסא כו') אך הענין כי שרש המלאכים דבריאה ויצי' הוא מבחי' אורות דתהו מבחי' ז' מלכין קדמאין שהאורות הללו גבוהים מבחי' אורות דתיקון וכמ\"ש ואלה<sup data-n=\"989\">73</sup> המלכים כו' לפני מלוך מלך לבנ\"י שהוא בחי' התיקון כידוע וע\"כ הן בחי' חיות ובהמות שקדמו לבחי' אדם כידוע ונק' פני ארי' פני שור כו' ושרש התהוותן מבחי' כלים דתהו שנשברו וירדו למטה בבריאה אך האורות לא ירדו אלא נסתלקו ועלו למעלה כמ\"ש בע\"ח וע\"כ כשמתבררי' ועולים במקור חוצבם בבחי' הכלים דתהו יעוררו לבחי' מקורם הראשון בחי' אורות דתהו להאיר בהן ועי\"ז יש בכחם להעלות גם לבחי' אדם שעה\"כ להעלותו למעלה מבחי' אדם והוא בחי' הסתר שנא' שם כי<sup data-n=\"990\">74</sup> לא אדם הוא כו' דהיינו לבחי' התהו שקדם לבחי' התיקון דאדם וזהו ענין והחיות נושאות את הכסא כו' וד\"ל.\n<b>ובזה</b> יובן ג\"כ ענין בסתר המדריגה כי הנה כתי' סולם<sup data-n=\"991\">75</sup> מוצב ארצה וראשו מגיע השמימה<sup data-n=\"992\">76</sup> פי' מוצב ארצה הוא בחי' נוגה דבי\"ע ששרשם בשבה\"כ<sup data-n=\"993\">77</sup> כידוע שאין למטה הימנו וראשו השמימה<sup data-n=\"994\">78</sup> לאחר שמתבררים רפ\"ח ניצוצות מבחי' נוגה ועולין לשרשם בבחי' אורות דתוהו שלמעלה מבחי' אורות דתיקון ונק' שמימה כו' להיותם בחי' עיגולים מקיפים כו', וזהו הנק' בשם מדריגה כמו הסולם שע\"י יעלה התחתון עד למעלה מעלה ברום המעלות להיות שהתחתיותה מוצב ארצה וראשו",[["982","66","<b>מושיבי עקרת הבית</b>: תהלים קיג, ט."],["983","67","<b>כחולדה זו שדרה בעקרי הבתים</b>: פסחים קיח, ב. וראה לקו\"ת צו יא, ג. סה\"מ תקס\"ה ע' תלה. ובכ\"מ."],["984","68","<b>שזפתני השמש</b>: שה\"ש א, ו."],["985","69","<b>לא תירא לביתה משלג</b>: משלי לא, כא."],["986","70","<b>והחיות נושאות את הכסא</b>: ראה בחיי תרומה כה, יו\"ד בשם פדר\"א. וראה פדר\"א ספ\"ד. שמו\"ר ספכ\"ג."],["987","71","<b>עה\"כ דמות כמראה אדם</b>: יחזקאל א, כו."],["988","72","<b>שארון נושאיו נשא</b>: ראה סוטה לח, ב. במדב\"ר פ\"ד, כא. זח\"ב רמב, א."],["989","73","<b>ואלה המלכים</b>: בראשית לו, לא."],["990","74","<b>כי לא אדם הוא</b>: שמואל-א טו, כט."],["991","75","<b>סולם מוצב ארצה</b>: בראשית כח, יב."],["992","76","<b>פי'. . וראשו השמימה</b>: בכת\"י א וכת\"י ג אין קטע זה. וכנראה הוא דילוג המעתיק."],["993","77","<b>בשבה\"כ</b>: תיבה זו אינה ברורה בהכת\"י."],["994","78","<b>השמימה</b>: בכת\"י ב וכת\"י ג אין תיבה זו."]]],[2101000168,"מגיע כו', וזהו ג\"כ ענין מדריגות שאמר כאן ע\"י בחי' נפש הבהמית להיות ששרשה השמימה מבחי' התוהו כנ\"ל, כי שרשה מפני שור שבמרכבה כידוע וה\"ז מוצב ארצה בנוגה וראשו העליון מגיע השמימה בבחי' שמים דתוהו, וע\"כ ע\"י דווקא תעלה הנפש אלקית ששרשה מבחי' אדם דתיקון כידוע למעלה מבחי' אדם כנ\"ל בענין החיות נושאות כו' ולכך נק' בשם מדריגה, אך מ\"ש בסתר המדריגה בבחי' ירידה למטה בהסתר והעלם כנ\"ל הענין הוא לפי שכל ענין הנ\"ל בחיות נושאות כו' היינו דווקא לאחר שנתברר בחי' נוגה ועולה לשרשו שקודם השבירה כו' אבל קודם שנתברר הרי הוא למטה בבחי' צמצום והסתר גמור ומעורב טו\"ר רק שנק' סתר המדריגה לפי שיש בה העלם והסתר בחי' העלאה למעלה כשתתברר ונמצא שניהם אמת וד\"ל.\n<b>הראיני</b><sup data-n=\"995\">79</sup> את מראיך כו' הנה מבואר שהמראה הוא בחי' המצות כו' ולהבין זה הנה ילה\"ק את הענין הידוע שנראה כסותר זא\"ז דלפעמים משמע בגמ' דמעלת התו' גבוה ונעלה ממעלת המצות כמו שגזרו הדין בהמשנה<sup data-n=\"996\">80</sup> דאלו דברים כו' ות\"ת כנגד כולם ואמרו עוד שנמנו<sup data-n=\"997\">81</sup> וגמרו דתלמוד גדול מן המעשה כו' ומי<sup data-n=\"998\">82</sup> שתורתו אומנתו פטור מן הק\"ש כו' ולפעמים משמע בגמ' להיפוך דמעלת המצות גבוהות ממעלת התורה כמ\"ש מבטלין<sup data-n=\"999\">83</sup> ת\"ת להלוית המת כו' וקאמ' בגמ' ולית<sup data-n=\"1000\">84</sup> לי' לרשב\"י הלומד שלא ע\"מ לעשות כו' ובכמה דוכתי אמרו לא המדרש עיקר אלא<sup data-n=\"1001\">85</sup> המעשה כו' וגם בפסוקי' יש כתובי' שמורים על מעלת התורה יותר כמו נר<sup data-n=\"1002\">86</sup> מצוה ותורה אור ויש פסוקים שמורי' על מעלת המצות יותר כמו ארור<sup data-n=\"1003\">87</sup> האיש אשר לא יקים את דברי הברית לעשות אותם דוקא כו' וכן ושמרתם<sup data-n=\"1004\">88</sup> ועשיתם כו' וכהנה רבות וכו', אך הענין הוא דשניהם אמת משום דלא ראי זה כראי זה ויש מעלה בתורה משא\"כ במצות ויש מעלה במצות מה שאינו בתורה כו' כי הנה אנו רואי' בתו' הנגלית לנו שיש מעלה מש\"א במצות והוא מה שהתו' היא חכ' ושכל וטעם למעשה המצות ונק' טעמי המצות והפשוט מורה שהטעם של איזה דין והלכה היא בחי' אור וחיות אליו משא\"כ הדין והלכה שבלא טעם אין לו חיות ואור כלל כמו חוקי המלך וגזירותיו שבלא טעם כלל אין להם חיות חזק אמנם מצד אחר יש מעלה במצות שהן גילוי הרצון בלא טעם שהוא מורה על היותו למעלה מן השגה והטעם לגמרי כי הנה הרצון העצמי הוא למעלה מן החכ' והטעם לגמרי דהיינו שאין כח באור החכ' להשיגו ולהכילו כלל כמאמ' שתוק<sup data-n=\"1005\">89</sup> כך עבמ\"ח כלומר אין טעם לרצון",[["995","79","<b>הראיני את מראיך</b>: להבא להלן — ראה גם ד\"ה הראיני את מראיך בסה\"מ תרס\"ב ע' רנה ואילך."],["996","80","<b>בהמשנה דאלו דברים</b>: פאה פ\"א מ\"א."],["997","81","<b>שנמנו וגמרו דתלמוד גדול</b>: קדושין מ, ב."],["998","82","<b>ומי שתורתו אומנתו פטור מן הק\"ש</b>: שבת יא, א."],["999","83","<b>מבטלין ת\"ת להלוית המת</b>: מגילה כט, א. ובכ\"מ."],["1000","84","<b>ולית לי' לרשב\"י הלומד שלא ע\"מ לעשות</b>: ירושלמי ברכות פ\"א ה\"ב."],["1001","85","<b>לא המדרש עיקר אלא המעשה</b>: אבות פ\"ד מי\"ז."],["1002","86","<b>נר מצוה ותורה אור</b>: משלי ו, כג."],["1003","87","<b>ארור האיש אשר לא יקים</b>: דברים כז, כו."],["1004","88","<b>ושמרתם ועשיתם</b>: ויקרא יט, לז. ועוד."],["1005","89","<b>שתוק כך עלה במחשבה</b>: מנחות כט, ב."]]],[2101000169,"כי הרצון הוא למעלה מהיות מוגבל בגדר השכל וידוע שיש ב' מיני רצון וב' מיני חכ' א' רצון המלובש בטעם נגלה ושרשו בטעם נסתר הנק' טעם כמוס לרצון ונק' ח\"ס והב' רצוה\"פ הבלתי מתלבש גם בטעם כמוס כלל אך גם בחכ' יש ב' מדריגות הא' בחי' ח\"ס שרש הטעם לרצון כנ\"ל והב' חכ' עצמי' הכלולה בעצמיות ממש ונק' חכה\"ק או חכמה דא\"ס כו' ושרש התורה מחכה\"ק בעצמות ושרש המצות מרצוה\"פ העצמי שלמעלה מהתלבשות בח\"ס<sup data-n=\"1006\">90</sup> הנ\"ל וא\"כ לכאורה א\"א להכריע בין עצם החכ' לעצם הרצון מאחר ששניהם בחי' עצמיות והארתם למטה אפס קציהו מהם בתו\"מ הרצון הנגלה בלי טעם בגזירה וחוק הוא ההארה בעלמא מעצם הרצה\"פ הכלול בעצמות והחכ' הבא להיות טעם לרצון אפי' טעם כמוס הנק' ח\"ס כנ\"ל הוא ג\"כ אפס קציהו מעצם החכה\"ק וכלולה בעצמות וכידוע בפי' ותמלא<sup data-n=\"1007\">91</sup> כד\"ה ותע\"ל כ\"ד ספרי דאורייתא ששרשם בח\"ס הנ\"ל הוא רק הכד מן הים הגדול לגבי עצם החכ' דא\"ס כו' ואמנם מבחי' גילוי הארתם למטה י\"ל בשרשם בעצמות מעלות כאו\"א על זולתו אשר לא ראי זה כראי זה ויש מעלה בא' מה שאין בזולתו כנ\"ל, והנה אנו רואים שטעם הכמוס והנגלה מן הכמוס לרצון לא יכיל כחו לגילוי הרצון שבלא טעם וכנראה לעין שהגזירה בלא טעם חזקה הרבה משבא בטעם אך אנו רואים להיפוך שע\"י הטעם יש חיות הרבה לרצון ובלעדו אין לו אור וחיות כ\"כ אבל אי\"ז נוגע לענין התוקף והחוזק דאעפ\"י שאין לו חיות מצד העדר הטעם אבל לא יבוטל לעולם מצד עצמו כי חזק הוא מאד וי\"ל בזה מהיכן יש תוקף וחוזק כ\"כ לרצון בלא טעם ושכל אם מצד שרשו בעצם הרצון כנ\"ל הרי יש גם לחכמה וטעם שרש בעצם החכ' כנ\"ל.\n<b>אך</b> הנה שרש הדברים הללו יובן בהקדים ענין א' והוא מ\"ש דדי<sup data-n=\"1008\">92</sup> לחכימא ברמיזא שהרמז יוכל לגלות גם שכל נעלם ועמוק ביותר שצריך להסביר אותו באותיות הדיבור כמה שעות והחכם יבין אותו ע\"י רמז ברגע קטנה דהיינו רק בתנועות הרמז כמ\"ש מחוי<sup data-n=\"1009\">93</sup> לי' במחוג כו' שהי' דרכם לגלות חכמות עמוקות ברמז בתנועות כידוע והנה עצם הרמז היא עשי' גשמי' כתנועה ביד אנה ואנה או קירוץ בעיניו אך הוא באופן המובן ממנו איזה טעם ושכל עמוק וזה פלא לכאורה איך תנועה גשמיות יעשה בחי' התגלות השכל הנעלם ביותר שלא יוכל להתגלות ע\"י אותיות הדיבור כלל אך הענין הוא דיש בשכל וחכ' ב' מדריגות הא' בחי' מהו\"ע של השכל הנק' פנימי' ועצם תמציתו שא\"א להסבירו למקבל כמ\"ש דלא קאי' אינש אדעתי'",[["1006","90","<b>בח\"ס</b>: בכת\"י ב: בחכ'."],["1007","91","<b>ותמלא כד\"ה ותעל כ\"ד ספרי דאורייתא</b>: בראשית כד, טז. וראה ת\"ז תכ\"א (מו, ב). אוה\"ת בראשית מח, א."],["1008","92","<b>דדי לחכימא ברמיזא</b>: מדרש משלי כב. זח\"ג רכט, ב. רפ, ב. ת\"ז תי\"ח (לו, א). תס\"ט (קז, ב. קטז, א). ועוד."],["1009","93","<b>מחוי לי' במחוג</b>: ראה חגיגה ה, ב. ובכ\"מ."]]],[2101000170,"דרבי' כו' והב' בחי' גילוי אורו בהבנה והסבר למקבל שנק' חיצוני' ולא מהו\"ע כמו שהוא בעצם כו', וזהו ההפרש בין הרמז להדיבור שברמז יוכל להתפס כל עצמו' השכל ומהותו שלמעלה מבחי' התגלותו בהסבר דברים כו' ובדיבור לא בא רק בחי' התגלות אורו להבין בהשגה בלבד שהוא בחי חיצוני' וע\"כ לא קאי' אינש אדעתי' דרבי' כו', ולפי\"ז הקושי' יותר חזקה איך בתנועה גשמי' דרמז נתפס כל עיקר מהות השכל ובאותיות הדיבור לא יתגלה רק חיצוניותו כו'.\n<b>אמנם</b> ילה\"ק לזה ענין אחר והוא שיש ב' מדריגות בענין ירידת ההשפעה מלמעלה למטה הא' בבחי' או\"כ שנק' חומר וצורה כמו אור הראי' הרוחני' שמאירה בכלי חומר העין הגשמי או רוחני' השכל בכלי המוח הגשמי' וכיוצא שאעפ\"י שבוודאי אין<sup data-n=\"1010\">94</sup> ערך לגשם חומר העין וחומר המוח לרוחני' הראי' והשכל מ\"מ בהכרח לומר שיש ערך ויחוס ביניהם מעין ודוגמא והוא מה שהחומר מעין הצורה דהיינו מה שהוא מסוגל לקבל הצורה ברוחני' כמו חומר העין שהוא עצם ספירי מוכן לקבל רוחני' הראי' וכן חומר המוח מוכן לקבל צורת השכל וכה\"ג כל האיברים המקבלים מכחות הנפש אמנם ודאי א\"א לומר שמהות הראי' עצמה היא נתפסת בחומר העין שא\"כ לא היתה ראי' והבטה גשמיות וכן בשכל במוח אין מהות השכל עצמו נתפס בו רק בחי' גילוי אורם בלבד הוא שנתגלה ומאיר להיות כי נמצא להם חומר מוכן לקבל גילוי אורם וזהו הכלל ההכרחי בכל בחי' או\"כ שנק' חומר וצורה כי להיות נמצא חומר מוכן לקבל העצמות בבחי' גילוי ממש זה א\"א כנ\"ל אך ורק בבחי' תפיסא והלבשה יוכל להיות שיתלבש כל העצמיות כמו שהוא ע\"ד שיתלבש אדם בלבוש נפרד שלא יתכן לומר בו חומר מוכן לקבל צורה כי אינו גם מעין ודוגמא כלל ואעפי\"כ כולו כמו שהוא בעצם נתפס בו כו', וכיוצא<sup data-n=\"1011\">95</sup> יש מעלה בבחי' או\"כ במה שבא בגילוי ממש ובחי' המשכה של העצמיות אינו בא בגילוי רק הוא שוכן בהעלם בבחי' תפיסא והלבשה בלבד אמנם יש מעלה בהמשכה העצמיות שכל העצמיות נמשך משא\"כ בבחי' או\"כ שאינו רק בחי' גילוי העצמיות בלבד כנ\"ל וד\"ל.\n<b>וככה</b> ממש יובן בהפרש בין הרמז לדיבור דהנה בחי' אותיות הדיבור שרשם מאותיות הרוחני' שבנפש שנחקקי' בנפש ע\"י הארת עצם החכ' שבנפש כמו שנמצאים האותיות במבטא גשמי' בה' מוצאות ע\"י בחי' החכ' המאיר בגילוי בכלי המוח כידוע דאבא<sup data-n=\"1012\">96</sup> יסד ברתא וע\"כ נק' אדם בחי' מדבר שהוא מצד נפש השכלית שנק' נפש המשכלת ואז דוקא נק' רוח<sup data-n=\"1013\">97</sup> ממללא כמ\"ש במ\"א ולפי\"ז יש ערך ויחוס מעין ודוגמא עכ\"פ לאותיות הדיבור אל אור החכ' כמו חומר לצורה כראי' בעין וכה\"ג וע\"כ אנו רואי' שאור השכל יאיר באותיות הדיבוד בבחי' גילוי ממש לפי שהאותיות בחי' כלים מסוגלים לקבל צורת השכל להיותם מעין ודוגמא לשכל כמו חומר העין לגבי צורת הראי' הרוחני' כנ\"ל וזהו המעלה שיש לדיבור על הרמז במה שמאיר בדיבור בבחי' גילוי ממש כנ\"ל בבחי' או\"כ אבל בחי' הרמז הנה וודאי א\"א לומר כלל וכלל שהרמז במעשה ותנועה גשמיות הוא בחי' חומר מעין דוגמא לקבל צורת השכל מאחר שהתנועה גשמיות אינו מעין ודוגמא של השכל כלל וכלל לא",[["1010","94","<b>אין</b>: בכת\"י א וכת\"י ב אין תיבה זו."],["1011","95","<b>וכיוצא</b>: בכת\"י ב וכת\"י ג: ונמצא."],["1012","96","<b>דאבא יסד ברתא</b>: זח\"ג רמח, א. רנו, ב. רנח, א. ת\"ז תכ\"א (סא, ב)."],["1013","97","<b>רוח ממללא</b>: ראה תרגום אונקלוס בראשית ב, ז."]]],[2101000171,"מיני' כו', אלא הרמז הוא בחי' הוראת וסימן בלבד על השכל להראות אותו בנטי' גשמיות של היד ועין וכה\"ג והגם שאנו רואי' שלפי אופן הנטיי' הרוחני' שבשכל כך יהי' הנטיי' הגשמיי' שביד ועין וכה\"ג מ\"מ אינם כמו חומר לצורה אלא שבנטייה שלהם מלובש בהעלם גדול בנטיי' השכל (וכמו אצבע הכותב השכל שבוודאי אינו חומר לקבל צורת השכל ואעפי\"כ יכתוב האצבע בתנועה גשמי' רק כפי ציור אור השכל המושג במוחו וא\"כ בהכרח לומר שיש בהעלם השגת השכל באצבע כו' וכך יובן בהוראות אצבע ורמז לכוין ולהורות ע\"כ עצם מהות השכל כנ\"ל שהוא מלובש ברמז זה בהעלם גדול כו'), והנה בזאת יתרון מעלת הרמז על הדיבור במה שכל עצמות השכל ומהותו כמו שהוא ממש נתפס ומתלבש ברמז שהרי עמקות השכל ומהותו שא\"א להביאו כלל בדיבור יבינו ויעמוד עליו ע\"י הרמז כנ\"ל, והיינו מפני שהאותיות אינם רק כמו חומר לצורה ע\"כ אינם מכילים רק לבחי' גילוי אור חיצוני' השכל בלבד וכנ\"ל אבל הרמז להיות מלביש בבחי' לבוש להתפס בו השכל הרי יוכל כולו כמו שהוא בעצם להתפס כנ\"ל, ונמצא מובן מכ\"ז דהיא הנותנת דמשום שהדיבור הוא מגלה השכל בגילוי ע\"כ אינו<sup data-n=\"1014\">98</sup> מאיר שם רק בחי' החיצוניות אבל ברמז לפי שהוא הוראה וסימן חיצוני כמו בבחי' לבוש נפרד ע\"כ נתפס בו כל הפנימי' והעצמיות<sup data-n=\"1015\">99</sup> רק שהוא בהעלם ולא בגילוי ויש מעלה בזה מה שאין בזה כנ\"ל וד\"ל.\n<b>והנה</b> יש עוד הפרש בין הרמז לדיבור מלבד הפרש הנ\"ל בבחי' הגילוי וההעלם ובבחי' החיצוני' והפנימי' כו' והוא אשר אנו רואי' שהשכל בא באותיות הדיבור בחלקי חלקי' ולא כולו בבת א' שהרי כל אות מגביל רק חלק א' מן השכל וכל תיבה כוללת רק לפי מספר האותיות בלבד משא\"כ ברמז שאין הכוונה הנרמזת מן הרמז באה בהתחלקות לחלקי' כלל אלא כל השכל נרמז בו בסקירה כללי' אשר יצטרך לפרט אותו בפרטי' בדיבור בכמה וכמה תיבות כידוע שזהו עיקר הרמז שכל שכל וחכ' שיצטרך לפרט בדיבור בכמה צירופי תיבות יובן כולו ברמז כולם כא' כי התפיסא שתופס השכל ברמז הוא תפיסא כללי' אבל התפיסא וההשגה שמשיג ותופס השכל ע\"י הדבור הוא תפיסא והשגה פרטי' מתחלקת לחלקי' רבים בכל חלק יש מעט השגה ואמנם כללות השגה מכללות השכל יצטרך לעמוד עליו אחר כל תשלום הדיבור כשגמר כל הדברים אז יחברם יחד ומה שיעלה מכללות חיבור כל האותיות שבדיבור הוא השגה כללי' שבכללות כל השכל כא' (והוא המושג ברמז אך הנה יוכל להיות שגם אם יאריך בדיבור הרבה ולא יעמוד על אמיתת המכוון כמו ע\"י הרמז לפי שגם שיתחבר כל פרטי האריכות שבדיבור עדיין לא יבוא לתמצית המכוון הכללי שמובן ע\"י הרמז והמופת לזה אשר ישונה אופני צירופי הדיבור בשכל א' בכמה אופנים שונים עד אשר שזה משיג בהיפוך מזה אעפ\"י שהשכל א' (כמו מחלוקת ב\"ש וב\"ה שזה אוסר וזה מתיר ששניהם שמעו שכל א' אלא שנשתנה לזה לאיסור ולזה להיתר) וגם יש ראי' מאשר לא קאי' אינש",[["1014","98","<b>אינו. . נפרד ע\"כ</b>: בכת\"י א אין קטע זה וכנראה הוא דילוג המעתיק."],["1015","99","<b>והעצמיות</b>: בכת\"י ב: והחצוניות."]]],[2101000172,"אדעתי' דרבי' כו' אעפ\"י ששמע השכל באריכות בכמה אופנים שונים לפי שא\"א שיכיל הדיבור כל פנימי' השכל כמו שהוא בעצם (וראי' מאשר אין<sup data-n=\"1016\">100</sup> הסנהדרין יושבין בע\"ש אעפ\"י שיכתבו באריכות משום אובנתא דלבא כו' כמ\"ש במ\"א) והוא עצמו הטעם שמתחלק בדיבור ואינו נתפס כולו כא' לפי שאינו מאיר רק הבנת והשגת השכל ולא מהותו העצמי כי מהותו העצמי אינו נתפס בדיבור וע\"כ נשתנה באופנים<sup data-n=\"1017\">101</sup> שונים גם להיות מובן ומושג בב' אופנים אבל ע\"י הרמז נתפס מהות השכל שהרי לפי מהותו העצמי דייקא כך יהי' אופן תנועת הרמז ממש ומזה הטעם עצמו יוכל לעמוד על אמיתת המכוון שבשכל אשר לא יעמוד עליו גם שיאריך בדיבור שעה ושתים כו' ושרש הכל הוא מפני שבדיבור לא נתפס השכל בבחי' תפיסא והלבשה בהעלם אלא דווקא מאיר בגילוי וכל בחי' גילוי בא הוא באותיות מגבילות בבחי' חומר וצורה כנ\"ל וע\"כ מסתעף מזה ב' דברים א' שלא נתפס מהותו העצמי של השכל רק חיצוני' והב' שמתחלק לחלקים ולא כולו כא' אבל הרמז לפי שהוא רק בחי' הוראה וסימן בבחי' העלם לבוש להתפס בו אור השכל בבחי' תפיסא והלבשה בהעלם גדול ע\"כ ממילא יבואו ב' דברים הללו שנתפס מהותו וכללות כולו כא' בלי התחלקות וד\"ל.\n<b>והנמשל</b><sup data-n=\"1018\">102</sup> מכ\"ז יובן ג\"כ שרש ענין ההפרש אשר בין תורה למצות כו', דהנה התורה נק' אור כי<sup data-n=\"1019\">103</sup> נר מצוה ותורה אור כידוע דבחי'<sup data-n=\"1020\">104</sup> החכמה נק' ג\"כ אור כו' וכל בחי' אור הוא הבא ומאיר בבחי' גילוי דווקא כמו אור המאיר לזולתו וה\"ז כמו בחי' גילוי אור השכל באותיות הדיבור שמאיר בבחי' חומר וצורה הנק' אור וכלי כנ\"ל באריכות שא\"א שיומשך בבחי' הפנימי' והעצמות רק בחי' החיצוני' כו' וגם בהכרח שיבא בהתחלקות לחלקים ולא כולו בבת א' כנ\"ל הטעם באורך וכך הוא בבחי' אור דתורה דאע\"ג דאורייתא<sup data-n=\"1021\">105</sup> מח\"ע נפקת שהוא בחי' ח\"ס ושרשה הראשון בבחי' חה\"ק הכלולה בעצמות ממש כנ\"ל מ\"מ א\"א שיומשך מבחי' הפנימיות החכמה שכלולה בעצמיו' כמו שהיא אלא רק הארה חיצוני' מאחר שנק' אור המאיר בכלי שהן אותיות התורה וכל<sup data-n=\"1022\">106</sup> טנת\"א שבתורה הן רק כלים להכיל אור החכמה הקדומה כו' וע\"כ בא בהתחלקות אותיות כלים מכ\"ש כו' (ובזה עצמו יש ב' מדריגות סתום וגלי' שהוא טעם הכמוס הנק' ח\"ס וטעם הגלוי בבחי' אור אבא כו' אבל כ\"ז אינו רק חיצוני' כמו השגת והבנת השכל באותיות כו' דלא קאים אינש אדעתי' כו' ובכלי העין לראי' וכה\"ג אך יש מעלה במה שמאיר בגילוי ולא בהעלם כו' כנ\"ל) וזהו שארז\"ל דנובלות<sup data-n=\"1023\">107</sup> חכמה ש\"מ תורה כי לא כל הפנימי' נמשך רק",[["1016","100","<b>אין הסנהדרין יושבין בע\"ש</b>: סנהדרין לה, א."],["1017","101","<b>אופנים</b>: בכת\"י ב וכת\"י ג: הפכים."],["1018","102","<b>והנמשל</b>: מכאן ואילך חסר בכת\"י א ונדפס עפ\"י שאר הכת\"י."],["1019","103","<b>כי נר מצוה ותורה אור</b>: משלי ו, כג."],["1020","104","<b>דבחי' חכמה נק' ג\"כ אור</b>: ראה הערת כ\"ק אדמו\"ר זי\"ע בסה\"מ תש\"ג ע' 164. לקו\"ת בהעלותך לד, ג."],["1021","105","<b>דאורייתא מח\"ע נפקת</b>: זח\"ב פה, א. קכא, א."],["1022","106","<b>וכל</b>: בכת\"י ב: וגם."],["1023","107","<b>דנובלות חכמה ש\"מ תורה</b>: ב\"ר פי\"ז, ה."]]],[2101000173,"בחי' חיצוני' ונובלות חש\"מ כו' אבל שורש המצות הוא בבחי' לבוש והעלם היינו כמו עד\"מ הרמז שמתלבש בו בהעלם ולא בגילוי אבל כל הפנימי' והעצמיות כמו שהוא ממש נמשך והוא בחי' עצם הרצון הפשוט כמו שהוא נמשך ונתלבש במעשה המצות אע\"פ שהן עשיי' גשמי' כמו הרמז שהוא תנועה גשמיות ומורה על הפנימי' כמו שהוא ע\"כ המצות נק' מראה כנ\"ל להיות שמראין ומרמזין על פנימי' הרצון כמו שהוא בעצם ממש להיותו מתלבש בבחי' ההעלם ולא בבחי' גילוי אור באור דתורה ומטעם הנ\"ל באריכות וד\"ל.\n<b>ובזה</b> יובן מ\"ש<sup data-n=\"1024\">108</sup> בע\"ח בשורש המצות שהן תרי\"ג ארחין דגלגלתא כו' ושרשם הוא בחי' י\"ג חיוורתא כו' שהוא בחי' הלבנונית שבין שער לשער והוא מק\"פ מן השערות כו' כידוע אבל שורש התורה הוא הנק' בחי' נימין ושערות (כמ\"ש<sup data-n=\"1025\">109</sup> בע\"ח דאור אבא יונק ממזל ונוצר כו' שהוא בחי' שער כידוע דהמזלות דא\"א הם בחי' שערות היוצאים מבחי' מותרי מוחין דא\"א (וע\"כ נק' התורה בשם נובלות חש\"מ כנ\"ל). וביאור הדברים הנה מובן ע\"פ כל הנ\"ל בהפרש אשר בין התלבשות השכל באותיות להתלבשות השכל ברמז, שבאותיות אע\"פ שמאיר בגילוי אבל אין הפנימיות נמשך שם מטעם הנ\"ל והיינו בחי' השערות שמשם נמשך שרש החכמה שבתורה דאצי' מאור אבא (וכמארז\"ל הכל<sup data-n=\"1026\">110</sup> תלוי במזל פי' במזל דא\"א אפי' ס\"ת שבהיכל שהוא בחי' אותיות דתשב\"כ ששרשם מאור אבא ונגנזים בהיכל אמא) וכמו עד\"מ השערה הגשמי' שהחיות בה מצומצם מאוד להיות בוקעת ויוצאת רק מבחי' חיצוני' המוחין דהיינו מבחי' הכלי וחומר של הצורה כו'<sup data-n=\"1027\">111</sup>) לפי<sup data-n=\"1028\">112</sup> שבחי' הפנימי' של המוחין כמו שהן בעצם דהיינו בחי' עצמות דכח המשכיל שבהעלם שלמעלה מהתלבשות צורה בחומר המוחין ולמעלה הוא הנק' בחי' פנימיות ח\"ס או בחי' חכמת הקדומה לא יוכל לבוא לידי גילוי כנ\"ל במשל התלבשות השכל באותיות באריכות וגם מה שמאיר בצמצום הנה הוא בבחי' התחלקות בריבוי חלקים מצומצמים<sup data-n=\"1029\">113</sup> מאוד שהרי השערות המחולקים מצומצמים כאו\"א בפ\"ע דווקא כידוע שכל שער יש לה גומא בפ\"ע כמ\"ש בשערה כו' בין<sup data-n=\"1030\">114</sup> שערה לשערה לא נתחלף כו' והן כל דינין והלכות שבתורה שנק' כל הלכה נימא ושערה מיוחדת ודינין והלכות שבתורה שבע\"פ נק' נימין דמטרוניתא כמ\"ש<sup data-n=\"1031\">115</sup> במ\"א ובחי' השערות עם בחי' האותיות א' הוא כידוע וד\"ל אבל בחי' המצות שרשם בבחי' הלבנונית שפנוי מן השערות כנ\"ל להיות שהתלבשות רצון העליון",[["1024","108","<b>מ\"ש בע\"ח בשורש המצות שהן תרי\"ג ארחין דגלגלתא</b>: ראה ג\"כ זח\"ג קכט, א ובביאור האריז\"ל שם. מ\"ח מס' א\"א ספ\"ד. לקו\"ת ראה כא, ד."],["1025","109","<b>כמ\"ש בע\"ח דאור אבא יונק ממזל הח'</b>: שער א\"א ספ\"ט. שער או\"א ספ\"ח. שער הזווגים ספ\"ב. שער הולדת או\"א וזו\"ן פ\"ו. שער העבורים פ\"ב. שער הנסירה ספ\"ג."],["1026","110","<b>הכל תלוי במזל</b>: זח\"ג קלד, א."],["1027","111","<b>אמא). . כו')</b>: כ\"ה בהכת\"י."],["1028","112","<b>וכמו. . לפי</b>: קטע זה ליתא בכת\"י ב."],["1029","113","<b>שהרי. . מצומצמים</b>: בכת\"י ב: שהן רבוי השערות המתחלקות ומצומצמות."],["1030","114","<b>בין שערה לשערה לא נתחלף כו'</b>: ראה ב\"ב טז, א. וראה זח\"ג קכט, א. קלא, ב."],["1031","115","<b>כמ\"ש במ\"א</b>: בכת\"י ב: כמ\"ש בזוהר ור\"מ."]]],[2101000174,"במעשה המצות הוא כדמיון התלבשות השכל ברמז שפנימיותו כמו שהוא מלובש שם וכולו כא' בלי התחלקות כנ\"ל וכך בבחי' המצות בשרשם למעלה שהוא בכתר עליון דא\"א שנק' גולגלתא שלמעלה מבחי' שערות דח\"ס שנק' מזלות כו' הנה הוא בחי' התלבשות עצמיות הרצון הפשוט כמו שהוא ממש שבעצמות אא\"ס ממש ולא בחי' גילוי אורו בלבד ע\"כ הוא במקה\"פ מן השערות דווקא כי בחי' השערות מורה על בחי' הגבלת כלים לגילוי אור כמו האותיות כנ\"ל ואמנם בבחי' המצות מתלבש העצמות כמו שהוא שלא יכילם בחי' כלים כנ\"ל ע\"כ אינו אלא בבחי' הלבנונית הפנויים משערות אבל שורה בבחי' ההעלם כמו דמיון הרמז וע\"כ נק' המצות בשם מראה מפני שמראין על בחי' העצמות שבכתר העליון כמו שהוא ממש והיינו מפני שהמצות הן חק וגזירה בלי טעם ושכל כנ\"ל ע\"כ יכול גם העצמות לשכון שם כמו שהוא משא\"כ אם מתלבשים בשכל וטעם שנק' אור אז לא הי' יכול להתלבש בהם בחי' העצמות מטעם הנ\"ל במשל (ומה שהמצות מתחלקים לתרי\"ג היינו כשנמשכים למטה ע\"י התלבשותם בח\"ס וכמ\"ש<sup data-n=\"1032\">116</sup> באד\"ר דאתפלגו לתרי\"ג ארחין בז\"א דוקא כמ\"ש כל<sup data-n=\"1033\">117</sup> ארחות הוי\"ה אבל טרם התלבשותם גם בח\"ס שאין טעם כמוס לרצון ג\"כ הם רק י\"ג חיוורתי וגם הם כלולים כא' כו' וד\"ל), ונמצא מובן מזה ג\"כ דאע\"פ שבעצם החכמה והרצון הכלולים בעצמות ממש לכאורה אין להכריע ביניהם כו' אבל בבחי' גילוי שלהם למטה הנה גילוי עצם הרצון בבחי' הלבנונית למעלה מבחי' גילוי האור דעצם דחכמה בשערות מטעם שכל העצמות נמשך<sup data-n=\"1034\">118</sup> כו' אבל מצד בחי' התגלותם בזה יש מעלה באור גילוי דחכמה על גילוי הרצון כו' וזהו שלא ראי זה כראי זה וע\"כ לפעמים אמרו דהתלמוד גדול ולפעמים משמע דמעשה גדול כנ\"ל וד\"ל.\n<b>וזהו</b> הראיני את מראיך השמיעיני את קולך כי קולך ערב כו' מראיך הוא<sup data-n=\"1035\">119</sup> בחי' מראה המצות שמראין ומרמזין על בחי' העצמות כנ\"ל אבל התורה ששרשה בבחי' קול, כי הנה עד\"מ הקול הגשמי שיוצא מהבל הלב הנה הוא מורכב מיסוד האש ומיסוד המים ומיסוד הרוח המחברם יחד וכוללם יחד כנראה בחוש שאם יחסר כח מזוג היסוד הא' מכח היסוד הב' לא יהי' הקול ממוזג יפה ולא יהי' זך וצלול כי אם יגבר מדת היסוד האש על יסוד המים שבהבל הלב נחר גרונו בקול גס ואם יגבר יסוד המים יהי' להיפוך והרוח שבהבל הלב הוא בחי' הממוצע הכוללם במזיגה ממוצעת כו' ונק' רוח ממללא בקול ודיבור כו' כך שרש התורה הוסדה בג' מדות חסד ודין והממוצע בחי' ת\"ת המכריע וכוללם יחד כי אין לך דין והלכה שלא יהי' בה התכללות מג' אלה כך וכך יוכשר ויטהר שהוא בחי' חסד וכך וכך לא יטהר ולא יוכשר שהוא בחי' דין והממוצע בין דין לגמרי לחסד לגמרי כו' וזהו הטעם ששורש התורה בבחי' ת\"ת כידוע כי מ\"ט פנים טמא מטמאים לגמרי ומ\"ט פנים טהור מטהרין לגמרי והממוצע הוא להבדיל בין טמא",[["1032","116","<b>וכמ\"ש באד\"ר דאתפלגו לתרי\"ג ארחין</b>: ראה זח\"ג קכט, א. ובהנסמן לעיל ע' קמ."],["1033","117","<b>כל ארחות ה'</b>: תהלים כה, י."],["1034","118","<b>נמשך</b>: בכת\"י ב: העצמות מלובש בו כנ\"ל."],["1035","119","<b>הוא</b>: בכת\"י ב: הוא עיקר חכ' שבתורה."]]],[2101000175,"לטהור באופן כך יטמא ובאופן כך יטהר כו' ועד\"ז בג' מיני מדות הללו באדם הנה מדת החסד לגמרי לא טוב (כי אנו רואים שהמרחם על הרשעים אכזריות כי יחריבו עולם ע\"כ הוא להיפוך שהדין על הרשעים נק' חסד) ומדה\"ד לגמרי יענוש גם לצדיקים אלא הממוצע המחלק כמדה ומזיגה ממוצעת הנק' משפט שכלול מחו\"ג כידוע (וזהו שאמר הכהנים<sup data-n=\"1036\">120</sup> הלוים כשמזכיר בחי' כהן שהוא בחי' החסד מזכיר אותם בשם לוים ג\"כ שהוא בחי' דין לפי שעם החסד צ\"ל דין ועם הדין צ\"ל חסד והוא בחי' הת\"ת כוללם יחד), וזהו כי קולך ערב כי העריבות הוא הכלול במרירות ושמחה שהן חו\"ג והיינו מפני ששורש התורה מבחי' ת\"ת כנ\"ל והוא בבחי' קול שמורכב מחו\"ג והיינו בחי' קול דתורה שנמשך מבחי' גילוי אור דחכמה שהוא בחי' פנימיות יותר מבחי' המראה שאין אלא חיצונית אבל בחי' עצמיות התענוג הפשוט מלובש במראה דמצות משא\"כ בקול דתורה הגם שמאיר גם בו בחי' עונג העליון כמ\"ש כי קולך ערב מעריבות עונג עליון דבחי' ע\"י אבל הוא רק בבחי' אור דרך בחי' שערה כנ\"ל וכן הוא בחי' הקול שהוא בחי' המשכה מצומצמת כו' וד\"ל.\n<b>אך</b> הנה אנו רואים שיש מעלה אחרת בתורה משא\"כ במצות והוא אשר המצות תלוין בזמן דוקא שהרי אם ישב אדם בסוכה בי\"ד בתשרי לא יצא י\"ח כלל ואם יתקע בשופר בכ\"ט באלול לא יצא ואין זה מצוה כלל וכה\"ג בכל המצות התלוים בזמן ואף במצוה שאין תלוי בזמן כצדקה וכה\"ג מ\"מ אינו אלא לשעתין בלבד ולא שיחייב לעשותן יום ולילה אבל מצות ת\"ת הרי נאמר והגית<sup data-n=\"1037\">121</sup> בו כו' ואינה תלוי' בזמן כלל וגם בדינין והלכות שלומד הרי אין המצוה בת\"ת שילמוד הלכות סוכה בזמן החג דווקא כה\"ג הלכות שופר בר\"ה אלא גם שלומד הלכות שופר וסוכה בזמן אחר אפי' בפסח יצא ידי מצות ת\"ת וממשיך בחי' המשכה עליונה שנמשך במצות ת\"ת כמו שלומד הלכות סוכה בזמנו בלי הפרש כלל (ומה שאמרו כל<sup data-n=\"1038\">122</sup> העוסק בתורת עולה כאילו הקריב כו' היינו דווקא בקרבנות כו') ולכאורה אין זה מובן למה מצוה ללמוד הלכות סוכה בלא זמנה דא\"צ למעשה עדיין כו' אך שרש הענין הוא מטעם הפרש הנ\"ל בין תורה למצות שהתורה באה בבחי' אור בגילוי כו' ע\"כ האור מאיר בתמידיות בלי שינוי בין זמן לזמן כלל וע\"כ כשלומד הלכות סוכה שלא בזמנה ג\"כ יפעול להמשיך בחי' אור החכמה המלובש בה והמשכה זו יכול להיות לעולם ולכך במצות ת\"ת יום ולילה כו' משא\"כ בחי' המצות ששרשם בבחי' מראה ורמז שמורה על בחי' עצם הרצון כנ\"ל אין זה רק כאשר העלם העצמות מתלבש במעשה זו דווקא והוא כמו שופר בר\"ה דווקא וסוכה בט\"ו בתשרי דווקא וכן המצות לשעתן בלבד כו' כנ\"ל וד\"ל (וזהו שאמר הראיני את מראיך במעשה המצות לפרקים מיוחדים ואמנם השמיעני את קולך בתמידות כו').",[["1036","120","<b>הכהנים הלוים</b>: דברים יז, ט. ועוד."],["1037","121","<b>והגית בו</b>: יהושע א, ח. ובהבא להלן ראה ג\"כ אוה\"ת דרושים לשבועות ע' קנט ואילך."],["1038","122","<b>כל העוסק בתורת עולה</b>: מנחות קי, א."]]],[2101000176,"<b>כי</b> קולך ערב ומראך נאוה, הנה שרש ענין מראך נאוה ענין א' הוא עם מ\"ש קולך ערב כי הנה בחי' עריבות הקול הוא בחי' התכללות מחו\"ג כנ\"ל באריכות וכך הוא בבחי' המצות כי הנה גם במצות יש בחי' התכללות מחג\"ת שהרי כמה מצות יש מהם מבחי' המשכות עליונים מלמעלה למטה דווקא כמצות סוכה ותפילין וציצית ולולב ואתרוג וכה\"ג ויש כמה מצות שהן בחי' העלאות מלמטלמ\"ע דוקא כמצות הקרבנות וכה\"ג ויש מצות שכלולים משתיהן חו\"ג העלאה והמשכה כמו מצות שופר שנאמר עלה<sup data-n=\"1039\">123</sup> אלקים בתרועה כו' וקול השופר הרי ממשיך בחי' גילוי אא\"ס<sup data-n=\"1040\">124</sup> כידוע ועד\"ז יש כמה מצות בצדקה שנק' זריעה כו' והוא בחי' חסד כו', וזהו פי' מראך נאוה כי בחי' היופי אינו אלא בעירוב גוונים הפכים במזג הממוצע מכולם יחד דווקא ואם אינו אלא גוון א' אינו יפה וגם כשכל גוון לבדו אין היופי גם בכאו\"א כשהוא לבדו אלא כשמתכללים יחד דווקא וכך הוא בעירוב הקולות שנק' קול ערב כשהוא ממוזג מב' קולות הפכיים מרירות ושמחה יחד כו', וזה שהקדים לומר כי קולך ערב על קול דתורה אור ששרשו בחה\"ק שמאיר האור מלמעלה למטה בבחי' גילוי ההעלם וע\"כ נמשל לקול שהוא ג\"כ בחי' התגלות ההעלם מהבל הלב כנ\"ל ואח\"כ אמר ומראך נאוה על בחי' מראה המצות ששם שורה בחי' עצמות הרצון הקדום בבחי' ההעלם ולא בבחי' גילוי ולפי שהוא ג\"כ בבחי' התכללות חג\"ת ע\"כ אמר ומראך נאוה בבחי' היופי העליון שאינו אלא בבחי' התכללות חו\"ג דווקא משום שמורים על בחי' העצמות שנק' שלימותא דכולא שכולל חו\"ג<sup data-n=\"1041\">125</sup> (ולזה אמר אלה<sup data-n=\"1042\">126</sup> המצות אשר יעשה אותם האדם דלעילא וחי בהם אדם<sup data-n=\"1043\">127</sup> אדמה לעליון וזהו שאמרו שופרא<sup data-n=\"1044\">128</sup> דיעקב שהוא ז\"א מעין שופרי' דא\"ק כו' וד\"ל).",[["1039","123","<b>עלה אלקיס בתרועה</b>: תהלים מז, ו."],["1040","124","<b>אא\"ס</b>: בכת\"י ב: אור ע\"י."],["1041","125","<b>חו\"ג</b>: בכת\"י ב: שכולל הכל כו'."],["1042","126","<b>אלה המצות אשר יעשה אותם האדם</b>: ראה ויקרא יח, ה."],["1043","127","<b>אדם אדמה לעליון</b>: ס' עשרה מאמרות מאמר אם כל חי ח\"ב פל\"ג. ובכ\"מ."],["1044","128","<b>שופרא דיעקב</b>: ראה ב\"מ פד, א. זח\"ב קמא, ב. ת\"ז תס\"ט (קי, א). ובכ\"מ."]]],[2101000177,"<h3>והתהלכתי בתוככם</h3>\n<b></b><b>בעזר\"ה שבת פ' בהר מינסק</b>\n<b>והתהלכתי</b><sup data-n=\"1045\">1</sup> בתוככם וכו' עד ואולך אתכם קוממיות. הנה לכאורה י\"ל דכאן אומר והתהלכתי<sup data-n=\"1046\">2</sup> בתוככם וכל הליכה למעלה הוא מלמעלה למטה כמו הליכות<sup data-n=\"1047\">3</sup> אלי כו' הליכות<sup data-n=\"1048\">4</sup> עולם לו שהקב\"ה הוא למעלה מעלה עד אין קץ כו' ובחי' ההליכה שלו הוא שיורד ומאיר אורו למטה מטה בבחי' התגלות מן ההעלם שהרי הקב\"ה<sup data-n=\"1049\">5</sup> נק' סתימו דכל סתימין כו' כידוע וז\"ש והתהלכתי מלמעלה למטה בתוך בנ\"י כו'. והרי במ\"א הוא אומר אחרי הוי' תלכו שכנ\"י ילכו אחרי ה' שזהו מלמטה למעלה דוקא ועד\"מ שני בנ\"א עליון ותחתון שרוצים להתחבר ולהתייחד שהעליון יורד אל התחתון מלמעלה למטה או התחתון עולה אל העליון מלמטה למעלה כו'. וככה יובן ביחוד עליון דקוב\"ה וכנ\"י יש שני אופנים הא' שהקב\"ה יורד למטה ומתגלה בתוך כנ\"י והב' שכנ\"י יעלו למעלה, וזהו שב' הכתובי' הללו סתרי אהדדי לכאורה, דכאן אומר והתהלכתי מלמעלה למטה ובמ\"א או' אחרי<sup data-n=\"1050\">6</sup> ה' תלכו מלמטה למעלה כו'. והנה יש עוד להבין במ\"ש אחרי ה' תלכו דהיינו אחר ה' ההולך לפניהם וכנ\"י ילכו אחריו דוקא ובאברהם נאמר התהלך<sup data-n=\"1051\">7</sup> לפני, שילך לפני ה'. והענין הוא כידוע שיש למעלה בחי' פנים ואחור הנק' פנימית וחיצוניו' הנק' אחוריי', ומ\"ש באברהם התהלך לפני היינו שיהא הילוכו בקודש העליון בבחי' הפנימי' דאא\"ס שבשם הוי', וז\"ש התהלך לפני כו', ואיך אמר אחרי ה' כו' בבחי' אחוריי' וחיצוניות דשם הוי' כו'. אך הענין הוא בדרך קצרה דמ\"ש באברהם התהלך לפני כו' הוא בחי' ההליכה מלמעלה למטה דוקא ע\"ד בחי' ההילוך העליון מלמעלה למטה כמ\"ש והתהלכתי בתוככם כו' כנ\"ל, וע\"כ אמר לפני בבחי' הפנימי', אבל הילוך דכנ\"י מלמטה למעלה כנ\"ל הוא בבחי' האחוריי' דשם הוי' וז\"ש אחרי ה' תלכו כו'.\n<b>אמנם</b> להבין ביאור כ\"ז הנה יש להקדים תחלה ענין מ\"ש בפ' ק\"ש והיו<sup data-n=\"1052\">8</sup> הדברים האלה אשר אנכי מצוך היום, וארז\"ל היום בכל<sup data-n=\"1053\">9</sup> יום ויום יהיו בעיניך כחדשים. ולכאורה זה פלאי איך יוכל להיות בכל יום כחדשים ממש מאחר שהתורה ניתנה בבחי' זמן וזה יותר מג' אלפים שנה שניתנה התורה, ואיך גם עכשיו בכל יום",[["1045","1","<b>והתהלכתי</b>: נדפס בשינויים בס' מאמרי אדה\"ז הנחות הר\"פ ע' קנז. ובארוכה בס' מאמרי אדהאמ\"צ ויקרא ח\"ב ע' תשפה. אמרי בינה שער הק\"ש פפ\"ד-פ\"ט. בשינויים ובתוספת הגהות באוה\"ת בחוקותי כרך ב' ע' תרמ, תרנד, תרעח. כרך ד' ע' א'קעו. ס' מאמרי הצ\"צ הנחות תרט\"ו ע' צט (ובהמ\"מ שם). סה\"מ תרכ\"ט ע' קצד. וראה אוה\"ת ואתחנן ע' שכ. סה\"מ תרנ\"ח ע' קעה ואילך. ד\"ה והתהלכתי תשי\"א. תשל\"ג. תשל\"ח. ד\"ה הנה מה טוב תשכ\"ט."],["1046","2","<b>והתהלכתי בתוככם</b>: ויקרא כו, יב."],["1047","3","<b>הליכות אלי</b>: תהלים סח, כה."],["1048","4","<b>הליכות עולם לו</b>: חבקוק ג, ו."],["1049","5","<b>הקב\"ה נק' סתימו דכל סתימין</b>: ראה ת\"ז בהקדמה ד\"ה פתח אליהו. ובכ\"מ."],["1050","6","<b>אחרי ה' תלכו</b>: ראה דברים יג, ה. וראה ג\"כ לקו\"ת ראה יט, ב. אוה\"ת שם ע' תרפח."],["1051","7","<b>התהלך לפני</b>: בראשית יז, א."],["1052","8","<b>והיו הדברים האלה</b>: דברים ו, ו."],["1053","9","<b>בכל יום ויום יהיו בעיניך כחדשים</b>: ספרי ופירש\"י דברים שם."]]],[2101000178,"יהיו כחדשים כאלו היום ניתנה וכו'. והנה להבין זה יש להקדים את ענין הידוע שיש ב' מדריגות באא\"ס ב\"ה, הא' בחי' סוכ\"ע, והב' בחי' ממכ\"ע כידוע. וביאור ענין ממכ\"ע הוא רק בחי' התגלות אור א\"ס ב\"ה שמתגלה מן העלם עצמותו כדי להיות מקור להתהוות ד' עולמות אבי\"ע (ובע\"ח הוא הנק' בחי' הקו הנמשך אחר הצמצום כו') וכמ\"ש ואתה<sup data-n=\"1054\">10</sup> מחי' את כולם פי' אתה א\"ת וה' מוצאו' הפה שהן כללות כ\"ב אותיו' שקבועין בפה ודיבור העליון כמ\"ש<sup data-n=\"1055\">11</sup> בס\"י וקבען בפה (ולמעלה יותר הוא בחי' התגלו' אא\"ס בבחי' קו\"ח והוא וי\"ו דואתה כו') וכמ\"ש בדבר<sup data-n=\"1056\">12</sup> ה' שמים נעשו. ואותו גילוי האור והחיות הוא מלובש בתוך כ\"ע ובא בסדר והדרגה מעילה לעילה בכל עולם ועולם לפי ערכו מריש כל דרגין עד סוף כל דרגין, וזהו הנק' ממכ\"ע פי' ממלא בבחי' גילוי התלבשות ממש בתוך כל עולם להחיותו מאין ליש תמיד וכמ\"ש ואתה מחי' כו', ונק' ג\"כ בשם כח הפועל בנפעל דרך כלל כידוע. וענין סדר ההדרגות אשר בבחי' ממלא הנ\"ל ידוע שיש ג' עולמות כמ\"ש לכבודי<sup data-n=\"1057\">13</sup> בראתיו יצרתיו אף עשיתיו ונק' בי\"ע, ונשמות ומלאכים דבריאה וכמו ג\"ע עליון ורקיעים שבעולם הבריאה הן למעלה הרבה מנשמות ומלאכים דיצי', ונשמות ומלאכים דיצי' גבוהים הרבה מנשמות ומלאכים דעשי' כו'. והמשל בזה ידוע ע\"ד התלבשות החיות של נפש האדם באברי הגוף השכל במוחין שבראש וכל אברי הראש כמו הראי' בעין והשמיעה באזן כו' וכה\"ג, שהן בחי' גילוי אור וחיות הרבה יותר מחיות שאר האברי' כיד ורגל ושאר הגוף (כי ראי' ושמיעה ריח ודיבור תלויי' בשכל וחכ' שבמוח והמוח הוא בחי' חב\"ד, והלב הוא בחי' חג\"ת ודם הנפש שהוא כח התנועה וההרגש בחי' נה\"י, והן נק' נר\"נ המלובשים במוחא ולבא וכבדא כידוע. והיינו משל לג' מדריגות דבי\"ע, חב\"ד בבריאה דאימא<sup data-n=\"1058\">14</sup> מקננא בכורסי' כו', וחג\"ת ביצי' כו', או עד\"מ מחשבה דו\"מ שהוא ג\"כ דמיון לג' מדריגות דבי\"ע כידוע). וכך בכל אבר ואבר מתגלה חיות הנפש במדה קצובה לפי מזגו דוקא, ואין א' דומה לחבירו במעלה ומקום כו'. וכן יובן למעלה כמארז\"ל מה הנשמה<sup data-n=\"1059\">15</sup> ממלא כל הגוף כך הקב\"ה ממלא את כל העולם כו', שהרי הוא ית' נק' אל אל<sup data-n=\"1060\">16</sup>קי הרוחות לכל בשר כו', שמתלבש להחיות לכל נברא לפי ערכו כמו התלבשות הנפש באברי הגוף כנ\"ל, וממילא מובן שיש חילוקי מדריגות מעלה ומטה, דהיינו כמו בג\"ע העליון יש גילוי אור אלקי יותר במעלה מהכל, והוא עד\"מ גילוי אור השכל במוח וכה\"ג והן כמו השגות שכליי' של הנשמות בג\"ע כו'. וכן יש מלאכים שנק' עיני ה' כו' כמ\"ש עיני<sup data-n=\"1061\">17</sup> ה' משוטטות ונק'<sup data-n=\"1062\">18</sup> מארי",[["1054","10","<b>ואתה מחי' את כולם</b>: נחמי' ט, ו."],["1055","11","<b>כמ\"ש בס\"י וקבען בפה</b>: פ\"ב מ\"א."],["1056","12","<b>בדבר ה' שמים נעשו</b>: תהלים לג, ו."],["1057","13","<b>לכבודי בראתיו יצרתיו אף עשיתיו</b>: ישעי' מג, ז."],["1058","14","<b>דאימא מקננא בכורסייא</b>: ת\"ז תי' ו' (כג, א). ע\"ח שער דרושי אבי\"ע (שמ\"ב) פי\"ג. סדר אבי\"ע (שמ\"ז) פ\"ג. תניא פל\"ט. וראה הערת כ\"ק אדמו\"ר זי\"ע בסה\"מ תש\"ח ע' 81."],["1059","15","<b>מה הנשמה ממלא כל הגוף</b>: ראה מדרש תהלים קד. ברכות י, א."],["1060","16","<b>אל אלקי הרוחות לכל בשר</b>: במדבר טז, כב."],["1061","17","<b>עיני ה' משוטטות</b>: דה\"ב טז, ט. וראה תו\"א וירא יד, ד ואילך. לקו\"ת דרושים לשמ\"ע צא, ד. אוה\"ת עקב ע' תקצז."],["1062","18","<b>ונק' מארי דעיינין כו' מארי דאשגחותא</b>: ראה ת\"ז תי' ע (קלא, א). ובהנסמן לעיל לתו\"א וירא ואוה\"ת עקב."]]],[2101000179,"דעיינין כו' מארי דאשגחותא כו' (ובמ\"א<sup data-n=\"1063\">19</sup> כתיב משוטטי' בבחי' דכר והוא בבחי' ז\"א דאצי' ומשוטטות בבחי' נוק' דז\"א שהוא בחי' המל' שנק' בחי' ממכ\"ע הנ\"ל כידוע). ועד\"ז הולך האור ומשתלשל ממדרגה למדריגה בג' עולמות בי\"ע עד סוף כל המדריגות שנתצמצם שם אור האלקי בתכלית וכמ\"ש הארץ<sup data-n=\"1064\">20</sup> הדום רגלי כו', והוא שרש הע' שרים דעשי' כו'. וכ\"ז בחי' ממכ\"ע, אבל בחי' סוכ\"ע הוא בחי' עצמות העלם אא\"ס ב\"ה שאינו בא לבחי' גילוי אור וחיות להחיות ד' עולמות אבי\"ע כלל. ומפני שאין זה האור העצמי בא בהתלבשו' חיות בעולמות דאבי\"ע כלל ע\"כ ממילא מובן שהוא הנק' בחי' סובב, כלומר בחי' או\"מ כללי שמקיף לכל העולמות שנמשכו מבחי' גילוי אא\"ס ב\"ה שנק' ממלא בכלל כנ\"ל. וההקפה הזאת היא באה בהשוואה א' לכל העולמות מריש כל דרגין עד סוף כל דרגין הנ\"ל, כי הוא למעלה מבחי' השתלשלות לגמרי, ע\"כ ממילא אין לפניו בחי' מעלה ומטה כלל (וכמ\"ש בע\"ח דעיקר גילוי הארת הקו מהעלם העצמות אינו אלא להיות בחי' מעלה ומטה כמו אצי' למעלה ועשי' למטה בכלל, אבל לפני מל' דא\"ס שלפני הקו המקיף לכל הקו בשוה מראשו לסופו שוה ומשוה קטן וגדול ממש וכמו אצי' ועשי' שוין, דהיינו רוחניות וגשמיות בכלל כידוע כי אין שם בחי' מעלה ומטה כלל כו' וד\"ל). וזהו הנק' בחי' סוכ\"ע דסובב ומקיף לכל עלמין מלמעלה בבחי' ההעלם ואינו בא בהם ובתוכם בבחי' גילוי כלל ע\"כ מאיר על כולם בהשוואה א'. וז\"ש<sup data-n=\"1065\">21</sup> דקמי' עצמותו כחשיכה כאורה כו' (וכמשל העיגול הסובב וקו נמשך באמצעותו מראשו לסופו דמצד הקו יש מעלה ומטה אבל מצד העיגול הרי הוא מעגל למטה כמו למעלה ממש כו' וד\"ל). וז\"ש דקמי' כולא כלא חשיבי, דהיינו דכמו שהוא בשמים ממעל אין עוד כך בארץ מתחת כו' בלתי חילוק מדריגות מעלה ומטה כלל כי נמצא למטה כמו למעלה ממש וכמ\"ש גם<sup data-n=\"1066\">22</sup> חושך לא יחשיך כו' מאחר שעליון ותחתון שוה וכולא קמי' כלא עליון כתחתון כו' מטעם הנ\"ל וד\"ל.\n<b>והנה</b><sup data-n=\"1067\">23</sup> זהו כל עיקר תכלית הכוונה במצות מעשיות שיהא בחי' גילוי אור המקיף הנק' סוכ\"ע להיות מאיר בבי\"ע להיות בבחי' גילוי ההעלם דוקא, ולא כמו שהוא מאיר עכשיו רק בבחי' ההעלם בלבד (דגם שהארת סובב הכללי הנ\"ל נק' בשם אור מקיף וכל אור פירושו ענין הארה ממש אבל הארתו היא בהעלם (וכמ\"ש במ\"א ביאור זה עד\"מ מזלייהו<sup data-n=\"1068\">24</sup> חזי בחברי דניאל שחרדו חרדה גדולה ולא ראו מאומה כו'). דהנה ע\"י המצות נמשך להיות בחי' סובב בבחי' ממלא הנ\"ל ממש וכמ\"ש והי'<sup data-n=\"1069\">25</sup> הוי' לי לאלקי', הוי' בחי' סובב יבא לי בגילוי גמור כמו בחי' אלקים להיות ממש בחי' ממלא כהפב\"נ כנ\"ל). וזהו שרש ענין<sup data-n=\"1070\">26</sup> יחוד קוב\"ה ושכינתי' שאו'",[["1063","19","<b>ובמ\"א כתיב משוטטי'</b>: זכרי' ד, י."],["1064","20","<b>הארץ הדום רגלי</b>: ישעי' סו, א."],["1065","21","<b>וז\"ש דקמי' כולא כלא חשיבי</b>: ראה זח\"א יא, ב."],["1066","22","<b>גם חשך לא יחשיך</b>: תהלים קלט, יב."],["1067","23","<b>והנה זהו כל עיקר תכלית הכוונה במצות מעשיות</b>: ראה אגה\"ק ס\"ג ובליקוט פירושים ומ\"מ שם."],["1068","24","<b>מזלייהו חזי בחברי דניאל</b>: מגילה ג, א. וראה תניא פכ\"ג. לקו\"ת במדבר טז, א. ובכ\"מ."],["1069","25","<b>והי' הוי' לי לאלקים</b>: בראשית כ, כא."],["1070","26","<b>ענין יחוד קוב\"ה ושכינתי' שאו' על כל מצוה</b>: ראה הערת כ\"ק אדמו\"ר זי\"ע במפתחות והערות הנדפס בסו\"ס לקו\"ת ע' יח, ובסה\"מ תש\"ב ע' 27."]]],[2101000180,"על כל מצוה כי קוב\"ה הוא בחי' העלם עצמות אא\"ס שלפני התגלותו בעולמות כי<sup data-n=\"1071\">27</sup> קדוש פירושו מובדל כו' כידוע, ושכינתי' הוא בחי' גילוי האור כנ\"ל. אך שיהא בחי' קוב\"ה מתגלה שזהו גילוי אור הנעלם דוקא היינו יחוד עליון זה דקוב\"ה ושכינתי' כו'. וזהו עיקר כוונת הברכות שעל המצות באמרו בא\"י אמ\"ה אשר קדשנו במצותיו, פי' ברוך הוי' הוא בחי' גילוי סובב הכללי הנ\"ל להיות ממש בבחי' ממלא שהוא בחי' מלך העולם כמ\"ש מלכותך<sup data-n=\"1072\">28</sup> כו' והיינו ע\"י המצות דוקא, וז\"ש אשר קדשנו במצותיו כי קדשנו לשון קדוש ומובדל שהוא בחי' סובב הנ\"ל, והיינו ע\"י המצות דוקא. כי הנה שרש המצות הוא בחי' פנימי' רצה\"ע ב\"ה, והוא הנק' בלשון המקובלים בחי' פנימי' כתר עליון דשם שורש פנימי' אא\"ס ב\"ה (כמ\"ש<sup data-n=\"1073\">29</sup> בתיקונים אא\"ס מלגאו כתרא עילאה מלבר כו' כי<sup data-n=\"1074\">30</sup> פנימיות הכתר אינו נמנה בע\"ס להיותו מבחי' אחרונה דאא\"ס שלפני הצמצום כו' וחיצוניות הכתר הוא שרש הנאצלים כידוע). כי המצות שרשן בבחי' רצה\"ע הפנימי דהיינו בחי' הרצה\"פ הנק' רצה\"ע שלמעלה מן השכל והטעם, כי אית רצון ואית<sup data-n=\"1075\">34</sup> רצון כו', רצון התחתון המתלבש בשכל וטעם למה ירצה כך, אבל רצה\"ע הוא אשר לא יוכל להתגלות בשכל וטעם כלל (גם לא בבחי' טעם כמוס הנק' ח\"ס כו') וכמ\"ש שתוק<sup data-n=\"1076\">32</sup> כך עלה במח' לפני, פי' שתוק שאין כאן רק שתיקה כי א\"א לגלות בדיבור כלל איזה טעם לרצון זה אלא רצון זה כך עלה במח' למעלה מן הטעם לגמרי כי הוא רק בחי' רצו\"פ בלתי טעם כלל (גם לא יש טעם כמוס לרצון כלל) אלא כך רצונו בלבד כאדם שאומר כך רצוני בלי טעם כלל וכלל וע\"כ אמר שתוק (גם בשכל הנעלם יש לשתוק, ומ\"ש סייג<sup data-n=\"1077\">33</sup> לחכ' שתיקה הכוונה גם על בחי' שכל וטעם הנעלם הנק' ח\"ס שהוא הטעם הכמוס לרצון כמ\"ש במ\"א גם שם יש בחי' שתיקה ששרשה למעלה מח\"ס וע\"כ הוא סייג לח\"ס כו' וד\"ל). והוא שרש המצות שהן בבחי' פנימי' הכתר, כי כתר<sup data-n=\"1078\">34</sup> גי' תר\"ך עמודי אור שהן תרי\"ג מצות דאוריי' וז' דרבנן כידוע (כי<sup data-n=\"1079\">*34</sup> שרשן הוא בתרי\"ג ארחין דגלגלתא דא\"א שלמעלה מבחי' ח\"ס דא\"א כו'). וזהו אשר קדשנו במצותיו שע\"י המצות להיות שרשם מפנימי' הכתר ששם גילוי אא\"ס שלפני ההשתלשלות ע\"כ אנו ממשיכים על ידם דוקא מבחי' סובב הכללי הנ\"ל לידי גילוי ממש כנ\"ל וד\"ל.",[["1071","27","<b>כי קדוש פירושו מובדל</b>: ראה פירש\"י ורמב\"ן ויקרא יט, ב. תניא פמ\"ו."],["1072","28","<b>מלכותך כו'</b>: תהלים קמה, יג."],["1073","29","<b>כמ\"ש בתיקונים אוא\"ס מלגאו כתרא עילאה מלבר</b>: ת\"ז סוף תי' כב."],["1074","30","<b>כי פנימית הכתר אינו נמנה</b>: ראה הערת כ\"ק אדמו\"ר זי\"ע בסה\"מ תש\"ח ע' 242."],["1075","34","<b>אית רצון ואית רצון</b>: ראה תו\"א ויקהל פז, ד. דרמ\"צ פח, א. לעיל בהביאור על מים רבים. ובכ\"מ."],["1076","32","<b>שתוק כך עלה במח' לפני</b>: ראה מנחות כט, ב, זח\"ג כז, ב."],["1077","33","<b>סייג לחכ' שתיקה</b>: אבות פ\"ג מי\"ג."],["1078","34","<b>כתר גי' תר\"ך עמודי אור שהן תרי\"ג. . דרבנן</b>: פרדס ש\"ח פ\"ג. אגה\"ק סכ\"ט. וראה הערת כ\"ק אדמו\"ר זי\"ע בסה\"מ תש\"ח ע' 165."],["1079","*34","<b>כי שרשן הוא בתרי\"ג ארחין דגלגלתא דא\"א</b>: ראה זח\"ג קכט, א ובביאור האריז\"ל שם. מ\"ח מס' א\"א ספ\"ד. לקו\"ת ראה כא, ד."]]],[2101000181,"<b>וזהו</b> ג\"כ משארז\"ל על מ\"ש אנכי<sup data-n=\"1080\">35</sup> מצוך היום היום לעשותן ולמחר לקבל שכרם כו' וכמשארז\"ל דיפה<sup data-n=\"1081\">36</sup> שעה א' בתשובה ומע\"ט בעוה\"ז מכל חיי עוה\"ב כו'. דהנה חיי העוה\"ב או ג\"ע מה שהנשמות נהנין מזיו השכינה הוא רק בבחי' ממכ\"ע הנ\"ל הבא בבחי' צמצום הארה בעלמא מעצמות אור א\"ס ב\"ה כנ\"ל ואף גם זאת אין אדם שיגיע לקבל שכר כזה אלא ע\"י עליות כמה מדריגות זו למעלה מזו ודוקא אחר הפשטת הגשמיות מלבד טהרת<sup data-n=\"1082\">37</sup> הטומאה מן העוונות גם מתאוות היתר שלזה באה הנפש ביסורי גהנום תחלה קודם עלותה לג\"ע וגם לאחר יסורי גהנום שתטהר מן הטומאה הגשמיות הנה כשצריכה לעלות לג\"ע צריכה תחלה לטבול<sup data-n=\"1083\">38</sup> בנהר דינור להפשיט אותה מן ההגשמה (וכמ\"ש במ\"א שגם המלאכים הנשלחים לזה העולם החומרי באיזה שליחות נסים וכה\"ג מפני שעברו בעוה\"ז החומרי צריכי' טבילה בנהר דינור בעלותם למעלה כו') וכמ\"כ בעליות הנשמות ממדריגה למדריגה כמ\"ש ילכו<sup data-n=\"1084\">39</sup> מחיל אל חיל כו' כמו מג\"ע התחתון לג\"ע העליון וכיוצא צריכה טבילה בנהר דינור כו'. וכ\"ז בעליות הנשמות בג\"ע, ומכ\"ש בחיי עוה\"ב כו'. אבל יפה שעה א' בתשובה ומע\"ט בעוה\"ז מכל חיי העוה\"ב, מפני שע\"י תשובה ומע\"ט בעוה\"ז גם רשע גמור המתועב ונטמא בכל רע גמור כשעושה תשובה או עושה מצוה הרי בזאת הוא ממשיך על נפשו מהארת סוכ\"ע שלמעלה מבחי' כל חיי עוה\"ב שאינו רק גילוי הארה בעלמא כנ\"ל, ואין הטומאה והרע מחשיך לגילוי אור זה כלל מאחר שהוא מבחי' סובב כ\"ע דקמי' כחשיכה<sup data-n=\"1085\">40</sup> כאורה כו' וגם חושך לא יחשיך כו' ושם נאמר אם צדקת מה תתן לו ואם<sup data-n=\"1086\">41</sup> רבה פשעיך מה תעשה לו כו', וכנ\"ל שע\"י המצות נמשך מבחי' סובב הכללי שמקיף לכל העולמות בשוה כו'. ולזה הטעם ארז\"ל דכל<sup data-n=\"1087\">42</sup> ישראל יש להם חלק לעוה\"ב אפי' רשעי' גמורים משום דגם<sup data-n=\"1088\">43</sup> פושעי ישראל מלאים מצות כרימון כידוע, וע\"י המצות נמשך מבחי' סוכ\"ע שהוא מקור כל חיי העוה\"ב כנ\"ל וד\"ל. וזהו שארז\"ל היום לעשותם ולמחר לקבל שכרם, פי' היום לעשותן בבחי' המעשה של המצות בעוה\"ז שהוא למעלה מקיבול שכרן לחיי עוה\"ב (וכמ\"ש ועמך<sup data-n=\"1089\">44</sup> כולם צדיקים, ע\"י המצות כנ\"ל, ע\"כ ירשו ארץ שהוא חיי עוה\"ב כו'). ולזה דקדק ואמר היום דוקא ולא למחר וד\"ל.",[["1080","35","<b>אנכי מצוך היום היום לעשותן</b>: דברים ז, יא. עירובין כב, א."],["1081","36","<b>דיפה שעה אחת. . מכל חיי עוה\"ב</b>: אבות פ\"ד מי\"ז. וראה תו\"א ויחי מו, ג. לקו\"ת ראה יט, ד. אוה\"ת דרושים לפ' זכור ע' א'תשסט ואילך. ובכ\"מ."],["1082","37","<b>טהרת הטומאה מן העוונות. . קודם עלותה לג\"ע</b>: ראה תניא פ\"ז ופ\"ח ובליקוט פירושים ומ\"מ שם. וראה בהנסמן להלן."],["1083","38","<b>לטבול בנהר דינור</b>: ראה זח\"א רא, א. זח\"ב ריא, ב. רמז, ד, ובכ\"מ. וראה תו\"א מקץ לא, א. ובכ\"מ."],["1084","39","<b>ילכו מחיל אל חיל</b>: תהלים פד, ח. וראה ברכות סד, א."],["1085","40","<b>כחשיכה כאורה כו'</b>: תהלים קלט, יב."],["1086","41","<b>אם צדקת מה תתן לו. . מה תעשה לו</b>: ראה איוב לה, ו-ז."],["1087","42","<b>דכל ישראל יש להם חלק לעוה\"ב</b>: סנהדרין צ, א."],["1088","43","<b>דגם פושעי ישראל מלאים מצות כרימון</b>: עירובין יט, א. ובכ\"מ."],["1089","44","<b>ועמך כולם צדיקים</b>: ישעי' ס, כא."]]],[2101000182,"<b>ובכ\"ז</b> יובן ג\"כ מה<sup data-n=\"1090\">45</sup> שמקשה בגמרא תרי קראי אהדדי דכתיב ואספת דגנך כו' וכתיב ועמדו זרים ורעו צאנכם כו' ומשני לא קשי' כאן בזמן<sup data-n=\"1091\">46</sup> שישראל עושין רצונו של מקום (אז נאמר ועמדו זרים כו') וכאן כשאין ישראל עושין רש\"מ (אז נאמר ואספת דגנך כו'). והנה לכאורה זה תמוה דהאיך יאמר דקרא דואספת דגנך מדבר כשאין ישראל עושין רש\"מ הלא בפ' שני' והי' א\"ש כו' מדבר דוקא כשישראל עושין רש\"מ כמ\"ש והי' א\"ש תשמעו אל מצותי כו' לאהבה את ה' ולעבדו בכל לבבכם כו' ונתתי מטר כו' ואספת דגנך כו'. אך הנה באמת אין פי' עושין רצונו או אין עושין כפשוטו אלא הכונה בפי' עושין לשון המשכה מלמעלה שימשיכו מלמעלה למטה לעשות רצונו ש\"מ כו', וע\"ד שאמר ברוך<sup data-n=\"1092\">47</sup> המקום שהכונה שיומשך ויתברך ממקור המקום בבחי' מקום שהוא ו\"ק מעלה ומטה כו', כך פי' עושין רצונו של מקום להמשיך ולעשות בחי' רצה\"ע למקום ואז יהי' נק' רצונו של מקום כו'.\n<b>וביאור</b> הדבר הנה ידוע דעצמו' אא\"ס ב\"ה הוא בבחי' אחה\"פ מושלל מכל ספי' ומדה וכמ\"ש אנת<sup data-n=\"1093\">48</sup> חד ולא בחושבן כו' עד ולאו מכל אינון מדות כלל, וא\"כ מושלל גם מבחי' רצון כמו שמושלל מבחי' חכ' וכמ\"ש חכים ולא בחכ' ידיעא וכמה שביאר בכלל ולאו מכל אינון מדות כלל כו'. אך ע\"י בחי' הצמצו' נמשך בבחי' קו כו' ואז נק' חכים ומבין כו' רק לאחזאה כו'. וע\"כ אנו מבקשי' יה\"ר מלפניך כו' שצריך להמשיך אור א\"ס ע\"י צמצום עד שיומשך בחי' רצה\"ע שנק' כתר עליון כידוע, וז\"ש יהי\"ר מבעל הרצון כו', והיינו ע\"י הארת סובב בממלא ממשיכים ממקורא דכולא להיות התגלו' רצה\"ע. וזהו ג\"כ פי' עושין רצונו של מקום, פי' ממשיכים מבחי' סובב לבחי' ממלא להיות רצה\"ע מאיר במקום שהוא בחי' ו\"ק מעלה ומטה כו' ואז נק' רצונו של מקום, והיינו ג\"כ פי' ברוך המקום כו' וד\"ל. אך לכאורה האיך ביכולת כנ\"י להמשיך המשכה עליונה כזו לעשות רצון למקום העליון כו'. הנה הוא ע\"י אהבת בכל מאדך שנז' בפ' ראשונה דק\"ש ואז נאמר ועמדו זרים כו' שהוא מדבר כשישראל עושין רש\"מ כו'. אבל בפ' שניה דוהי' א\"ש כו' שלא נאמר בה בכל מאדך ע\"כ אמר שמדבר כשאין ישראל עושין רש\"מ, ולזה אמר שם ואספת דגנך כו', ואעפ\"י שמקיימין המצות כו'.\n<b>וביאור</b> טעם הדברים הנה כתיב ואהבת בכל מאדך, היא בלי גבול למטה וכמ\"כ מעורר למעלה בחי' מאד העליון שהוא בחי' עצמות אא\"ס ב\"ה הנק' סובב הכללי כנ\"ל, ומבואר למעלה דקמי' כחשיכה כאורה ע\"כ נאמר אז ועמדו זרים ורעו צאנכם כו' (שלא יצטרכו בעצמם לברר בירורים דרפ\"ח כו' כי גם חושך לא יחשיך כו' מפני התגלות סוכ\"ע למטה כמו למעלה וכמו לעתיד אחר הבירור כו'). אבל בפ'",[["1090","45","<b>מה שמקשה בגמרא. . דכתיב ואספת דגנך וכתיב ועמדו זרים</b>: ראה ברכות לה, ב. דברים יא, יד. ישעי' סא, ה."],["1091","46","<b>בזמן שישראל עושין רצונו של מקום</b>: בהבא להלן ראה ג\"כ לקו\"ת שלח מב, ג ואילך. אמרי בינה שער הק\"ש פפ\"ו. אוה\"ת נ\"ך כרך ב' ע' תתנג. לקו\"ש חי\"ב ע' 98 ואילך (ובהנסמן שם)."],["1092","47","<b>ברוך המקום</b>: נוסח ההגדה."],["1093","48","<b>אנת חד ולא בחושבן</b>: ת\"ז ד\"ה פתח אליהו."]]],[2101000183,"שניה שלא נאמר בה בכל מאדכם בלי גבול הגם שיקיימו את המצות שנק' רצה\"ע ג\"כ כנ\"ל, אבל לא יש ביכולתם לעורר ממקורא דכולא הנק' בעל הרצון שהוא בחי' עצמות אא\"ס שלפני הקו כו' כנ\"ל שנק' מאד ממש כו' שלמעלה מבחי' הרצון כו', וע\"כ נאמר שם ואספת דגנך שצריכים לברר בירורי' לאהפכ' חשוכא לנהורא כו' שאין החושך מאיר כו' משום דקמי' דוקא כחשיכה כאורה אבל לא בבחי' השתלשלות דסובב בממלא גם ע\"י המצות, ולכך נק' אין עושין רצונו של מקום גם שעושין המצות אם לא אחר תשלום הבירורים (שע\"י המצות בסור מרע דשס\"ה ל\"ת ועשה טוב ברמ\"ח מ\"ע כו' הוא בחי' הבירורי' לאהפכא חשוכא לנהורא כו' וז\"ש ואספת דגנך כו' ולאחר תשלום הבירורי' שע\"י המצות אז דוקא נק' עושין רש\"מ וד\"ל). וראי' לזה שהרי בפ' שניה נאמר מיד אחר ואספת דגנך כו' השמרו לכם פן יפתה לבבכם וסרתם כו' שיש בחירה למאוס בטוב ולבחור ברע כו', הרי לא נשלמו הבירורים דלאהפכא חשוכא כו' עדיין, וא\"כ מזה ראי' דמדבר כשאין ישראל עושין רש\"מ גם שמקיימים המצות מטעם הנ\"ל וד\"ל.\n<b>ובכ\"ז</b> יובן עוד מה שבפ' ראשונה דק\"ש אמר ושננתם לבניך כו' ואח\"כ וקשרתם כו' שמצות ת\"ת קודם למצות תפילין ובפ' שניה אמר תחלה וקשרתם כו' ואח\"כ ולמדתם את בניכם כו' תפילין קודם לתורה. דהנת ארז\"ל הוקשה<sup data-n=\"1094\">49</sup> כל התורה לתפילין כו' שכל המצות מעשיות נכללו במצות תפילין כו'. והנה בפ' ראשונה נאמר בכל מאדך שהיא בלי גבול כנ\"ל ועי\"ז נמשך אוא\"ס מלמעלה למטה ג\"כ בהארה בלתי מוגבלת בקו כו' וכנ\"ל וזהו הנק' בחי' ההליכה מלמעלה למטה בבחי' הפנימי' דאא\"ס ב\"ה שהרי מתגלה למטה מבחי' הפנימי' דאא\"ס מלמעלה למטה והוא מ\"ש בפ' ראשונה בתחלה ושננתם לבניך כו' מצות ת\"ת קודם משום דאוריי'<sup data-n=\"1095\">50</sup> מח\"ע נפקת וראשי' בחי' הגילוי<sup data-n=\"1096\">51</sup> וההילוך מעצמו' אא\"ס ב\"ה מלמעלה למטה הוא בחכ' שבתורה דוקא וכמ\"ש ה'<sup data-n=\"1097\">52</sup> קנני ראשי' דרכו כו' ואהי'<sup data-n=\"1098\">53</sup> אצלו אמון כו' כידוע, והוא בחי' התגלו' פנימי' מאור א\"ס ב\"ה וכמו שנאמר לאברהם התהלך לפני<sup data-n=\"1099\">54</sup> כו' כנ\"ל. ואח\"כ כל המצות מעשיות שכלולים במצות תפילין, שהרי בבחי' הילוך ההדרגה מלמעלה למטה הרי המח' שבחכ' קודם לדיבור ומכ\"ש למעשה שהיא סוף הכל, וכך בבחי' החכ' שבתורה הרי הוא בחי' ראשי' הגילוי מאא\"ס ב\"ה ואח\"כ נמשך למדות ומח' כו' עד בחי' המעשה שהוא לבסוף בהילוך זה שהולך האור מלמעלה למטה. וז\"ש וקשרתם אחר ושננתם דוקא כי כל המצות מעשיו' שהוקשו כולם לתפילין הוא לבסוף בסדר זה ההולך מלמעלה למטה כו' וד\"ל.\n<b>אבל</b> בפ' שניה בחי' ההילוך הוא מלמטה למעלה דוקא ע\"כ נהפוך הוא דתפילין קדם לתורה. דהנה בפ' שניה כתיב פן יפתה לבבכם וסרתם ועבדתם אלקים",[["1094","49","<b>הוקשה כל התורה לתפילין</b>: קדושין לה, א."],["1095","50","<b>דאוריי' מח\"ע נפקת</b>: זח\"ב פה, א. קכא, א."],["1096","51","<b>וראשית בחי' הגילוי. . הוא בחכמה</b>: ראה ע\"ח שער דרושי אבי\"ע פ\"א. שעהיחוה\"א פ\"ח-ט. תו\"א ושערי אורה רד\"ה יביאו לבוש מלכות."],["1097","52","<b>ה' קנני ראשית דרכו</b>: משלי ח, ב."],["1098","53","<b>ואהי' אצלו אמון</b>: משלי ח, ל."],["1099","54","<b>לפני</b>: כ\"ה בהכת\"י, ואוצ\"ל לפר'."]]],[2101000184,"אחרים כו' ואח\"כ כשיחזרו בתשובה ושמתם את דברי אלה על לבבכם כו', הרי מדבר בבחי' התשובה שהוא בחי' הבירור וההעלאה מלמטה למעלה לאהפכא חשוכא לנהורא כו' בסו\"מ וע\"ט (כנ\"ל שזהו ג\"כ ענין המצות עכשיו בזמן הבירור כו') וזהו הנק' בחי' ההילוך מלמטה למעלה דוקא. ועד\"מ הנ\"ל בשני בנ\"א עליון ותחתון שיש ב' מיני הילוך הא' שהעליון יורד והולך למטה אל התחתון להתחבר ולהתייחד עמו, והב' הילוך התחתון לגבי העליון להתייחד כו'. וכך גם כאן זהו ההפרש בין פ' הראשונה לפני שניה שבפ' הא' ע\"י בכל מאדך ההילוך הוא מלמעלה למטה כנ\"ל שהוא כמו ירידת העליון לתחתון ובפ' הב' שלא נאמר בכל מאדך כנ\"ל הטעם ואדרבא נאמר פן יפתה כו' וחוזרים בתשובה ושמתם את דברי אלה כו' הוא כמו בחי' הילוך התחתון לגבי העליון שהוא בחי' הבירורי' מלמטה למעלה דוקא, והרי בסדר העולה מלמטה למעלה הנה אז בחי' המעשה קודם לבחי' הדיבור והמח' שבח\"ס (כמו עד\"מ הבונה בנין שרצונו ושכלו מלובשים במדות שבלב ומדות מתלבשים במח' והמח' בדיבור והדיבור במעשה, הרי הפנימי יותר הוא הרצון והשכל והחיצוני יותר הוא המעשה, ותחלה מאיר הפנימי והולך ויורד בהתלבשות עד שבא אל המעשה החיצוניו'. וזהו דוקא בעת הבנין אבל לאחר שפועל מעשה הבנין הרי פועל המעשה קודמת לבא ולעלות לפני המח' ולפני הרצון ושכל כו'. וכך יובן הנמשל דסוף מעשה בהעלאת הבירורים הרי עולה בתחלה לפני המח' כו' וד\"ל). וזהו שהזכיר בפ' שניה מצות תפילין וקשרתם קודם ולמדתם דתורה כו', כי בחי' הבירורי' דעשי' קודם בחי' הבירור דיצי' שהוא בחי' הבירור דתורה כי תחלה מתברר עשי' ואח\"כ יצי' ואח\"כ בריאה כו', ובחי' הבירור דיצי' ובריאה היינו מצות ת\"ת בדיבור ודברת בם כידוע<sup data-n=\"1100\">55</sup> שהמשנה ביצי' להבדיל בדיבור לומר זה כשר וטהור כו' שיוכל להתעלות וליכלל באחד כו' וזה פסול וטמא כו' ולא יעלה למעלה וטמא טמא יקרא להתרחק כו', והוא בחי' המדות שביצי' כידוע. והתלמוד בבריאה בבחי' טעמי' וסברות של פלפול קושיות ותירוצים כו', הוא בחי' בירור דבריאה שהוא בחכ' שלמעלה מן המדות כידוע שע\"י קושיו' הוא בחי' ההסתר דקליפה להסתיר אור ההלכה האמיתית, וזהו<sup data-n=\"1101\">56</sup> שהי' האריז\"ל<sup data-n=\"1102\">57</sup> מזיע כשמקשה קושי' כדי לשבר הקליפות כמ\"ש בכתבי האריז\"ל), וכשמתרץ הקושי' ה\"ז בחי' בירור להסתר דקליפה דחכ' דבריאה ונק' ליבון הלכתא שאין לה הסתר וחושך עוד כו'. ובזמן<sup data-n=\"1103\">58</sup> עיקבות משיחא עיקר הבירור הוא בבחי' העשי' כידוע בענין ועמדו<sup data-n=\"1104\">59</sup> רגליו כו' דמטי<sup data-n=\"1105\">60</sup> רגלין ברגלין (בחי' נה\"י דז\"א בנה\"י דנוק' שהוא בחי' בירור דעשי'. אך זהו",[["1100","55","<b>כידוע שהמשנה ביצירה. . והתלמוד בבריאה</b>: שער המצוות וטעהמ\"צ פ' ואתחנן. פע\"ח שער הנהגת הלמוד. וראה ת\"ז בהקדמה (יד, א). תניא פ\"מ בהגה\"ה אחרונה. אגה\"ק סכ\"ו. תו\"א ר\"פ שמות. ובכ\"מ."],["1101","56","<b>וזהו שהי' האריז\"ל מזיע כשמקשה קושי'</b>: ראה כתהאריז\"ל הנסמן לעיל."],["1102","57","<b>האריז\"ל)</b>: כ\"ה בהכת\"י. וחסר התחלת המוסגר."],["1103","58","<b>ובזמן עיקבות משיחא. . בבחי' העשי'</b>: ראה אגה\"ק ס\"ט."],["1104","59","<b>ועמדו רגליו</b>: זכרי' יד, ד. וראה זח\"ב רנח, א (ומק\"מ שם). אוה\"ת נ\"ך ע' תקכא. סה\"מ מלוקט ח\"א ע' קה."],["1105","60","<b>דמטי רגלין ברגלין</b>: ראה זח\"ב שם."]]],[2101000185,"דוקא מלמעלה למטה כאשר שם מ\"ה דז\"א מברר לב\"ן דנוק' תחלה מברר לחב\"ד דנוק' דבריאה כו', ובירור נה\"י דעשי' דנוק' הוא לבסוף ונק'<sup data-n=\"1106\">61</sup> עקבות משיחא כמ\"ש אשר<sup data-n=\"1107\">62</sup> חרפו עקבות משיחך כמו בגלות האחרון הזה כו'. אבל בפ' שניה שאו' וקשרתם תחלה שבירור דעקביי' דעשי' קודם לעלות מדבר בבחי' הבירור וההעלאה דנוק' בחי' ב\"ן שהמעשה קודם לדיבור ומח' כו' כנ\"ל וד\"ל). וע\"כ עיקר המצות כולן עכשיו הוא מצות הצדקה וכמ\"ש בצדקה<sup data-n=\"1108\">63</sup> תיכונני (וגם בענין העלאת בירור דעשי' שקודם לכולן הוא בחי' הצדקה שהוא הנק' עיקר בהילוך מלמטה למעלה והוא הקודם לכולן כנ\"ל וד\"ל. ובזה יובן מ\"ש בגמרא דר\"א<sup data-n=\"1109\">64</sup> יהיב פרוטה לעני והדר מצלי משום דכתיב אני בצדק אחזה פניך פי' אחזה פניך הוא בחי' חב\"ד דנוק' דבריאה שעולה בש\"ע באצי' באתדבקות רוחא ברוחא חב\"ד בחב\"ד דז\"א כו' ואין זה אלא ע\"י דיהיב פרוטה לעני תחלה בבחי' בירור דמעשה הצדקה תחלה כי הוא בירור הקודם מטעם הנ\"ל וז\"ש בצדקה תיכונני בצדקה דוקא כו' וד\"ל.\n<b>וזהו</b> אחרי הוי' תלכו כו' בבחי' אחוריי' וחיצוניו' דהוי', אבל באברהם נאמר התהלך לפני דוקא. ואין שני כתובים הללו סותרים זא\"ז כנ\"ל דבחי' ההילוך מלמעלה למטה כמ\"ש בפ' הא' אשר אנוכי מצוך כו' ושננתם ואח\"כ וקשרתם כו' כנ\"ל הוא מ\"ש ג\"כ באברהם התהלך לפני פי' לפני לפני שם הוי' להיותו נמשך מבחי' פנימי' דאא\"ס ב\"ה שלפני הצמצום כנ\"ל מלמעלה למטה דוקא, וזהו לפני להיות בחי' הארה פנימי' גם בשם הוי' עי\"ז כו' מבחי' אנוכי סובב הכללי כנ\"ל. כי הנה ארז\"ל האבות<sup data-n=\"1110\">65</sup> הן המרכבה כו' שהי' אברהם ע\"ה צד\"ג במס\"נ תמיד ולא הי' צריך לילך מלמטה למעלה להפוך רע לטוב וחושך לאור הנק' בחי' בירורי' דנוגה כנ\"ל אלא הי' רק הליכתו בקדש העליון מלמעלה למטה בבחי' פנים (וע\"ד שאמר והיית<sup data-n=\"1111\">66</sup> אך למעלה ולא למטה כו') וכמ\"ש התהלך לפני כו' כנ\"ל. וזהו שארז\"ל שקיים<sup data-n=\"1112\">67</sup> אאע\"ה כל התורה כולה אפי' ערובי תבשילין כו', ולכאורה י\"ל בזה דודאי קיים כל התורה עד שנעשה בן צ\"ט שנה וא\"כ למה איחר לקיים מצות מילה לבסוף כל המצות. אך הענין הוא דכל מה שקיים כל התורה הי' רק למעלה בבחי' הרוחניות כמו ע\"י אהבת בכל מאדך שנמשך מבחי' מאד העליון דעצמות אא\"ס ב\"ה בחכ' שבתורה כנ\"ל בענין פ' הא' דק\"ש (כי איך קיים אברהם כל מצות התלויות בארץ וביצי\"מ וכה\"ג מצות קרבנות או מצות יבום וגרושין וכה\"ג כו' אלא ר\"ל בשרש המצות ברוחניות ברצה\"ע כו'), ומצות מילה בלבד הייתה בגשמיות בבחי' העשי' שהוא לבסוף בסדר ההילוך שהולך ובא מלמעלה למטה כנ\"ל וד\"ל (ומ\"ש",[["1106","61","<b>ונק' עקבות משיחא</b>: ראה סה\"מ תש\"ח ע' 100 ובהנסמן שם. ד\"ה אל תצר לכ\"ק אדהאמ\"צ ע' 71 ובמ\"מ שם."],["1107","62","<b>אשר חרפו עקבות משיחך</b>: תהלים פט, נב."],["1108","63","<b>בצדקה תיכונני</b>: ישעי' נד, יד. וראה אגה\"ק הנסמן לעיל. ובכ\"מ."],["1109","64","<b>דר\"א יהיב פרוטה לעני והדר מצלי</b>: ב\"ב י, א."],["1110","65","<b>האבות הן המרכבה</b>: ב\"ר פמ\"ז, ו. זח\"א רי, ב. זח\"ג קפב, א."],["1111","66","<b>והיית אך למעלה</b>: ראה דברים כח, יג."],["1112","67","<b>שקיים אאע\"ה כל התורה כולה</b>: קידושין פב, א. ובכ\"מ. ובהבא להלן ראה ג\"כ תו\"א לך לך יג, ב ואילך. לוח היום יום ע' קב."]]],[2101000186,"התהלך לפני בבחי' רצוא ושוב כידוע בפי' התהלך היינו שגם בחי' ההילוך שמלמעלה למטה א\"א כ\"א ע\"י בחי' רצוא מקודם כמא' רץ<sup data-n=\"1113\">68</sup> לבך שוב כו' רק שהירידה עיקר וההעלאה טפל והוא הנק' עלי' לצורך ירידה, משא\"כ בהילוך דמלמטה למעלה הוא בהיפך שההעלאה עיקר והירידה טפל ונק' ירידה צורך עלי' כו' וכמ\"ש במ\"א, ובזה מתורץ מה שגם בפ' הא' יש ג\"כ העלאה במס\"נ ובפ' הב' יש בחי' המשכה ג\"כ כו' וד\"ל). אבל מ\"ש במצות מעשיות שניתנו לישראל אחרי ה' תלכו מדבר בבחי' ההילוך שעולין מלמטה למעלה דוקא כמו בפ' הב' דק\"ש שמזכיר וקשרתם ואח\"כ ולמדתם כו' והוקשו כל המצות לתפילין<sup data-n=\"1114\">69</sup>, לפי שבסדר ההילוך מלמטה למעלה בחי' המעשה קודם כנ\"ל ובחי' הבירור דעשי' נק' בחי' חיצוני' ואחוריי' כו', וז\"ש אחרי ה' כו'. והיינו מה שרמזו רז\"ל ע\"פ וראית את אחורי כו' מלמד שהראה הקב\"ה למשה קשר של תפילין כו', דהנה משה ע\"ה ביקש הראיני את כבודך<sup data-n=\"1115\">70</sup> כו' ואין<sup data-n=\"1116\">71</sup> כבוד אלא תורה (כי כבוד הן ל\"ב נ\"ח כידוע) דהיינו שרש ענין תורה דמח\"ע נפקת שנק' כבוד העליון, והשיב לו וראית את אחורי כו'. כי שרש חכ' שבתורה הוא לברר בירורים לאהפכא חשוכא לנהורא כו' להבדיל בין טמא לטהור כו' (וע\"כ אמר במדרש ג'<sup data-n=\"1117\">72</sup> נובלות הן נובלות חכמה של מעלה תורה כי היא בחי' אחוריי' דחכ' שלמעלה שירדה לברר בירורי' כי<sup data-n=\"1118\">73</sup> בחכ' אתברירו דוקא כידוע). וז\"ש וראית את אחורי אבל פני לא יראו, פי' בחי' פנימי' החכ' שעצמות אא\"ס ב\"ה מתגלה בה בבחי' ההילוך מלמעלה למטה לא יראו למטה עד אחר תשלום כל הבירורים כמו לעתיד כו'. וזהו שארז\"ל שהראה לו קשר של תפילין שבאחוריו, כי הוקשו כל התורה לתפילין בבחי' בירורי' דעשי' דוקא שהוא בחי' ההילוך מלמטה למעלה וכמ\"ש אחרי ה' תלכו במצות מעשיות דוקא כנ\"ל, וע\"כ הראה לו קשר של תפילין דוקא (ומה שהראה לו קשר של תפילין מאחוריו ולא התפילין שבראשו לנגד פניו להיות בחי' המוחין העליונים הפנימי' מקבלים מבחי' המקיפי' שעל התפילין שבראש דז\"א וכמ\"ש<sup data-n=\"1119\">74</sup> וראו כל עמי הארץ כי שם הוי' נקרא עליך וזהו<sup data-n=\"1120\">75</sup> שהקב\"ה מניח תפילין כו' כמ\"ש במ\"א ומפני שבחי' פני לא יראו עכשיו אלא לעתיד אחר הבירור ע\"כ לא הראה לו רק בחי' קשר של תפילין שמאחורי הראש שהוא בחי' מל' דתבונה שמאחוריי' דחו\"ב כו' כמ\"ש במ\"א בענין קשר של תפילין של ראש וענין הרצועות כו') (אך לכאורה יש לתמוה דלפ\"ז הי' מעלת",[["1113","68","<b>רץ לבך שוב</b>: ס\"י פ\"א. ת\"ז בהקדמה (ז, א)."],["1114","69","<b>וראית את אחורי כו' מלמד שהראה. . תפילין</b>: שמות לג, כג. ברכות ז, א. זח\"ב רל, א. ובכ\"מ."],["1115","70","<b>הראני את כבודך</b>: שמות לג, יח."],["1116","71","<b>ואין כבוד אלא תורה</b>: אבות פ\"ו מ\"ג. ובכ\"מ."],["1117","72","<b>ג' נובלות הן</b>: ב\"ר יז, ה."],["1118","73","<b>כי בחכמה אתברירו דוקא כידוע</b>: ראה זח\"ב רנד, ב. ע\"ח שי\"ח פ\"ה ועוד. מבו\"ש ש\"ה ח\"א פ\"ב. אגה\"ק סכ\"ח. וראה הערת כ\"ק אדמו\"ר זי\"ע בסה\"מ תש\"ח ע' 206."],["1119","74","<b>וכמ\"ש וראו כל עמי הארץ</b>: דברים כח, י. ובהבא להלן ראה בארוכה בסידור שער התפילין. דרמ\"צ מצות תפילין. אוה\"ת ואתחנן ע' שטו ואילך. ובכ\"מ."],["1120","75","<b>וזהו שהקב\"ה מניח תפילין</b>: ברכות ו, א. ובכ\"מ."]]],[2101000187,"אברהם אע\"ה גדולה ממעלת משה ע\"ה דבאברהם נאמר התהלך לפני ובמשה נאמר ופני לא יראו וכנ\"ל, והלא ידוע במ\"ש וארא<sup data-n=\"1121\">76</sup> אל אברהם באל שדי ושמי הוי' לא נדעתי להם שהאבות לא הי' מרכבה רק לבחי' מל' ושרש משה ע\"ה בבחי' ז\"א ונק' איש האלקים כו' וז\"ש ושמי הוי' לא נודעתי להם כו'. אך הענין הוא כמ\"ש במ\"א (ע\"פ לך לך מארצך כו') במה שקיים א\"א ע\"ה כל המצות היינו למעלה באצי' ולא למטה כנ\"ל ומה שישראל מקיימים בגשמיות עי\"ז יהי' לעתיד גילוי המקיפי' למטה דוקא, ומ\"ש בתורה נובלות חש\"מ לשבח קאמר ועז\"א ושמי הוי' לא כו' וד\"ל. ובזה יתורץ גם מ\"ש באברהם התהלך לפני כו' לפי שאין זה רק באצי' ולא למטה משא\"כ במשה גם שעכשיו לא יראו פני לעתיד יראו גם למטה. ובזה יתרון מעלת ההילוך שמלמטה כו' וד\"ל). והנה גם התפלה הוא בבחי' ההילוך שמלמטה למעלה שהרי התפלה נק' סולם מוצב ארצה כו' וע\"כ ר\"א יהיב לעני והדר מצלי כו' להיות התפלה בבחי' ההעלאה מלמטה למעלה וכנ\"ל וד\"ל.\n<b>וזהו</b> והתהלכתי בתוככם כו'. דהנה כל הפרשה הזאת מדבר לעתיד דוקא דהיינו לאחר שיקיימו ישראל כל התורה כולה בכל זמן הגלות. וז\"ש אם בחוקותי תלכו כו' אז לעתיד בימוהמ\"ש והתהלכתי בתוככם כו'. כי הנה ע\"י קיום המצות עכשיו יהי' לעתיד בחי' התגלות סובב הכללי הנ\"ל, וזהו והתהלכתי כו'. אך י\"ל דעכשיו בקיום המצות אמר אחרי ה' תלכו מלמטה למעלה כנ\"ל ואיך עי\"ז יהי' לעתיד בחי' ההילוך מלמעלה למטה כו'. וגם י\"ל מ\"ש והתהלכתי שכולל ב' מיני הילוך מלמעלה למטה ומלמטה למעלה כידוע בפי' מתהלך כו' ואיך יוכל להיות ב' מיני הילוך הללו כא' שלכאורה הן ב' הפכי', שהרי היורד והעולה המה ב' הפכים כו', וגם מ\"ש בתוככם שב' מיני הילוך הללו הכל יהי' בתוככם כו'. אמנם הנה כ\"ז יובן בהקדי' ענין ההפרש אשר בין ב' מיני הילוך הללו דלכאורה אין ביניהם הפרש כלל דכל עיקר הענין הוא רק בחי' היחוד והחיבור דעליון ותחתון משפיע ומקבל כנ\"ל במשל ב' בנ\"א עליון ותחתון כו' ומהו ההפרש בין שיהיו יחודם למעלה בעלות התחתון לגבי העליון או שיהי' יחודם למטה בירידת העליון לתחתון כו'.\n<b>אך</b> הענין הוא שיש ודאי חילוקים הרבה ביניהן. דהנה עד\"מ המלך ועמו שהמלך בהיכלו כולו אומר כבוד כבוד מלוכה ועמו עומדי' בחוץ שצריך המלך לירד מהיכלו הפנימי ולצאת לעמו לחוץ שזהו ירידה והשפלה להתלבש בלבושי העם אבל העם שצריכים לעלות וליכנס להיכל המלך עלי' גדולה להם וצריכי' להסיר מלבושיהם ולהתלבש במלבושי כבוד לפי רוממות המלך כו'. וכמ\"כ יש הפרש פשוט בין הילוך שמלמעלה למטה שהוא בחי' גילוי סובב בממלא שזהו כמו ירידת המלך אל עמו שהתגלות זאת מתלבשת בבחי' הלבושים ואותה המדריגה שבעולמות שבבחי' ממלא כו' משא\"כ בחי' ההילוך שמלמטה למעלה שהוא בחי' עלי' ממלא בסובב כו' שהוא כמו עליי' העם אל המלך כו' שצריכים העולמות להזדכך לגמרי",[["1121","76","<b>וארא אל אברהם</b>: שמות ו, ג. וראה אוה\"ת בחוקותי כרך ב' ע' תרעג."]]],[2101000188,"מגשמיותם כמו<sup data-n=\"1122\">77</sup> שעלה אליהו וחנוך למרום שנזדככו חומר גופם ונתהפכו למהות רוחני כרוחות המלאכים העליונים ממש כידוע, ועד\"ז הוא בחי' העלאת ממלא לסובב בדרך כלל. אך בחי' ירידת האור דסובב בממלא כו' ה\"ז בא בעולמות כמו שהן ממש מבלי הזדככות כלל וכידוע שלעתיד יתגלה מבחי' סוכ\"ע הנ\"ל גם בחומר גופני ממש בלי הזדככות כלל כמ\"ש וראו<sup data-n=\"1123\">78</sup> כל בשר כו' וזהו מטעם שהמקבל כשעולה אל המשפיע צריך להתפשט מהגבלתו ולהיות במהות המשפיע אבל המשפיע יוכל לירד ולהלביש א\"ע במדריגת המקבל כו' וד\"ל. והנה לכאורה יש יתרון מעלה בעליית בחי' ממלא לסובב מבחי' ירידת אור סובב בממלא מטעם בחי' הזדככות העולמות כנ\"ל. אך הנה באמת נהפוך הוא שבחי' ירידת אור דסובב בממלא גדול מעלתו הרבה מבחי' עליי' ממלא לסובב כו'. והענין הוא כי הנה זה ידוע הכלל בכל מקום שכל שהאור בא ממקור ושרש גבוה ביותר יותר יוכל לבא למטה מטה בהתלבשות גשמיו' ביותר וכל שאין האור בא ממקור ושרש גבוה כ\"כ לא יוכל לירד להתלבש בהשתלשלו' למטה מטה כ\"כ כו'. וגם כאן הנה מאחר שבחי' אור דסובב יורד למטה מטה כ\"כ עד שמתלבש גם בגוף גשמי בלי הזדככות כלל מזה הוראה על שרש הארה זו שהוא באה מבחי' סובב מבחי' מקור ושרש גבוה ביותר אשר ע\"כ יורד למטה מטה כ\"כ כו' כי לעוצם הגילוי הגדול בשרשו מאד נעלה יוכל לבא בחי' גילוי אור זה גם במדריגה היותר תחתונה כמו גם בגוף גשמי כמו שהוא (וכמו שמבואר במ\"א בענין ראתה<sup data-n=\"1124\">79</sup> שפחה על הים מה שלא ראה יחזקאל כו' מפני עוצם מעלת מדריגות שרש גילוי אור גדול כזה עד שגם שפחה ראתה יותר מראיית נבואת יחזקאל כו', משא\"כ במ\"ת שלא ראה והשיג כאו\"א רק לפום שעו\"ד אעפ\"י שהי' גילוי גדול יותר אך הי' בא לפי ערך המקבלים כו'. ואמנם בחי' גילוי סובב בממלא לעתיד יהי' שלא לפי ערך המקבלים שהרי נאמר וראה כל בשר גם חומר גופני בלי הזדככות כלל ואעפ\"כ ישיג אור א\"ס כמו שהוא למעלה ממש כו' וד\"ל).\n<b>ונמצא</b> מובן מזה דהשגה שישיגו המקבלים מבחי' גילוי אור דסובב בממלא גם כמו שהן בלי הזדככות כלל הוא גבוה הרבה יותר מהשגה שישיגו בבחי' עליי' ממלא בסובב אחר שיזדככו ויעלו כמו ע\"ד שעלה אליהו וחנוך למרום כנ\"ל שהרי אור זה המתגלה מבחי' סובב בממלא שרשו יותר נעלה הרבה במקור חוצבו בעצמו' אא\"ס מאחר שיוכל לירד למטה מטה כ\"כ כנ\"ל וא\"כ ההשגה שישיגו מגילוי אור זה הוא נמשך ובא ממקור ושרש גבוה יותר מהשגת אור שמשיגי' גם בעליי' ממלא לסובב אף אחר הזדככו' כו' וד\"ל. ומעתה יתורץ כל הנ\"ל, דגם שלכאורה לא יש הפרש בעיקר יחוד ממלא וסובב בין יחודם למטה או למעלה כנ\"ל מ\"מ ההפרש גדול ביניהם שבחי' יחוד סובב וממלא למטה הוא יותר גבוה מיחודם למעלה בעליו'",[["1122","77","<b>כמו שעלה אליהו וחנוך למרום</b>: מלכים-ב ב, א ואילך. (וראה בהנסמן בלקו\"ש ח\"ב ע' 516). מס' דרך ארץ זוטא פ\"א."],["1123","78","<b>וראו כל בשר</b>: ישעי' מ, ה."],["1124","79","<b>ראתה שפחה על הים</b>: מכילתא פ' בשלח עה\"פ טו, ב. רש\"י שם טו, ב. זח\"ב סד, ב. צד, א. זח\"ג כב, ב."]]],[2101000189,"ממלא לסובב כו'. והנה ע\"י קיום המצות דעכשיו דכתיב בהו אחרי ה' תלכו כנ\"ל הוא בחי' עליי' ממלא לסובב מלמטה למעלה כנ\"ל, ולעתיד יהי' קיבול שכר המצות בבחי' ירידת אור דסובב בממלא שהוא גבוה יותר כנ\"ל<sup data-n=\"1125\">80</sup> ומשום דרוח<sup data-n=\"1126\">81</sup> אייתי רוח ואמשיך רוח כי באתערותא דלתתא נעשה אתערותא דלעילא כמים<sup data-n=\"1127\">82</sup> הפנים כו' וכמ\"ש אם<sup data-n=\"1128\">83</sup> ישים אליו לבו רוחו ונשמתו אליו יאסוף כו' ע\"כ ע\"י ההילוך שמלמטה יומשך הילוך העליון שמלמעלה כו'.\n<b>אך</b> כ\"ז לימות המשיח בלבד אבל לעתיד באלף השביעי שנק' עוה\"ב לאחר קיבול שכר המצוה כו' אמר והתהלכתי מעצמי בלי אתערותא דלתתא, והיינו שכולל ב' מיני הילוך הנ\"ל עליות ממלא לסובב וירידת סובב לממלא כאחד ממש אעפ\"י שלכאור<sup data-n=\"1129\">84</sup>ה הן כמו ב' הפכים כמו כל ירידה ועלייה כו'. אך הענין הוא דיש בחי' מקיף וסובב היותר עליון מבחי' סובב שנמשך לממלא כי פי' סובב כ\"ע הוא רק בחי' אור א\"ס שלפני הקו כנ\"ל אבל אינו רק מקיף וסובב לעלמין בלבד אבל עצמיות אוא\"ס ממש הוא למעלה גם מהיות נק' בשם סובב לעלמין מאחר דאינו מקור גם להשפעת אור ג\"כ כו', וה\"ז כמשל העיגול שבתוכו קו ממשיך מעליונו לתחתונו שיש בקו עליה וירידה אבל העיגול מצד עצמו הרי מעגל למטה ולמעלה בשוה, אך מ\"מ יש בעיגול מטה ומעלה מצד הקו אבל לא מצד עצמו כלל כו', כך אור דסובב בקו שמשוה ומעלה ומטה דקו אינו רק הארה בעלמא מעצמות אור הסובב שמצד עצמותו כו' וד\"ל. וזהו והתהלכתי עליה וירידה כאחד מצד עצמות כו' דסובב כו' שאין בו בחי' מעלה ומטה כלל ועליה וירידה כאחת הוא, והכל בתוככם לפי שישראל<sup data-n=\"1130\">85</sup> עלו במחשבה כו' וד\"ל.\n<b>ואולך</b><sup data-n=\"1131\">86</sup> אתכם קוממיות, פי' קוממיות כי הנה מ\"ש והתהלכתי הוא בא באתערותא דלעילא מעצמו בלי אתערותא דלתתא כלל מטעם הנ\"ל וע\"כ אמר ואוליך אתכם קוממיות ב' קומות דלמעלה ומטה כאחד כו'. דהנה אמרו בגמרא על אדה\"ר<sup data-n=\"1132\">87</sup> שמיעטו והעמידו על מאה אמה פי' כמ\"ש בה\"ר<sup data-n=\"1133\">88</sup> ג'<sup data-n=\"1134\">89</sup> אימות וז' כפולות חב\"ד וז' מדות כו' והיינו כל מדה וספי' שכלולה מי\"ס ומאה אמה היינו בחי' ע\"ס שכאו\"א כלול מי\"ס וזהו הנק' קומת אדם והוא לנגד מאה<sup data-n=\"1135\">90</sup> ברכות שחייב אדם לברך כו' כי הנה ק' ברכות הן ק' המשכות לנגד בחי' מאה מדרגות דע\"ס עליונות שכאו\"א",[["1125","80","<b>כנ\"ל</b>: מכאן ואילך חסר בכת\"י א, ונדפס כאן עפ\"י כת\"י ב, וכנראה הוא משובש בכ\"מ."],["1126","81","<b>דרוח אייתי רוח ואמשיך רוח</b>: זח\"ב קסב, ב. וראה אוה\"ת בראשית רפו, א."],["1127","82","<b>כמים הפנים כו'</b>: משלי כז, יט."],["1128","83","<b>אם ישים אליו לבו</b>: איוב לד, יד."],["1129","84","<b>אור</b>: תיבה אחת אינה ברורה בהכת\"י."],["1130","85","<b>שישראל עלו במחשבה</b>: ב\"ר בתחילתו. ובכ\"מ."],["1131","86","<b>ואולך אתכם קוממיות</b>: ראה ג\"כ אמ\"ב שער הק\"ש פפ\"ט."],["1132","87","<b>אדה\"ר שמיעטו והעמידו על מאה אמה</b>: ראה חגיגה יב, א. ב\"ב עה, א."],["1133","88","<b>בה\"ר</b>: כ\"ה בהכת\"י."],["1134","89","<b>ג' אמות וז' כפולות</b>: ס\"י פ\"א מ\"ב. וראה תניא פ\"ג ובליקוט פירושים ומ\"מ שם."],["1135","90","<b>מאה ברכות שחייב אדם לברך</b>: מנחות מג, ב."]]],[2101000190,"כלול מי\"ס ונק' מאה אמה כנ\"ל וידוע דהברכה היא בחי' המשכת סובב בממלא באמרו ברוך הוי\"ה כו'. והנה פי' קוממיות ב' קומות דק' אמה היינו להיות כי בבחי' הקו שנמשך מאור העצמות יש בחי' אור ישר ובחי' אור חוזר וכאו\"א נק' קומת אדם שהן בחי' ק' אמה, והיינו בחי' ב' מיני הילוך הנ\"ל. ומפני שלעתיד אמר והתהלכתי מעצמי בלי אתערותא דלתתא בהילוך שלמטה כלל להיותו למעלה מבחי' מעלה ומטה לגמרי דהיינו מצד העיגול עצמו כנ\"ל ע\"כ יהי' התגלות דמאה ברכות כלול מב' קומות דאו\"י וא\"ח כאחד. וזהו ואולך אתכם קוממיות ב' קומות וע\"כ יהי' בחי' התגלות זאת גם בגוף גשמי כנ\"ל וד\"ל. וזהו דאמרז\"ל עתידין<sup data-n=\"1136\">91</sup> צדיקים שיאמרו לפניהם קדוש, כי קדוש הוא בחי' מובדל דהיינו מבחי' סובב בממלא שישראל שיעלו למעלה בבחי' העצמות ממש ע\"כ יאמרו לפניהם קדוש כו' וד\"ל.",[["1136","91","<b>עתידין צדיקים שיאמרו לפניהם קדוש</b>: ב\"ב עה, ב."]]],[2101000191,"<h3>כמיפלגי ברקיע</h3>\n<b>כמיפלגי ברקיע </b>\n<b>קמיפלגי</b><sup data-n=\"1137\">1</sup> ברקיע<sup data-n=\"1138\">2</sup> ספק אם בהרת קודמת לשער לבן הקב\"ה אומר טהור ומתיבתא דרקיע אמרי טמא מאן נוכח אמרו נוכח רבה בר נחמני דאמר רב\"נ אני יחיד בנגעים ואהלות ואמר טהור, ובמ\"א<sup data-n=\"1139\">3</sup> נתפרש הטעם משום שנאמ' בתורה לטהרו ואח\"כ לטמאו כו' ע\"ש. להבין זה צריך להקדים תחלה ענין התנאים ואמוראים שמתוך מעשם אנו רואים גודל הניסים שהיו יכולים לעשות כמו ברפב\"י<sup data-n=\"1140\">4</sup> שאמר גינאי חלוק לי נהרא ומיד נתקיים ובקיבוץ ס\"ר ישראל בקי\"ס הי' זה פלא, וכן אמרו זוטרא<sup data-n=\"1141\">5</sup> דבכו מחיה המתים, וכהנה רבות.\n<b>והענין</b> הוא כי הנה ידוע שיש בחי' השתלשלות ולמעלה מהשתלשלות והוא פי' תיבת קדב\"ה כלומר קדוש וברוך כו' ברוך הוא בחי' חכמה כמ\"ש<sup data-n=\"1142\">6</sup> בזהר",[["1137","1","<b>קמיפלגי</b>: מאמר זה הוא הנחת כ\"ק אדמו\"ר הצ\"צ ממאמר אדה\"ז בשנת תקס\"ט. ונו\"א (בתוס' הגהות) נדפס בלקו\"ת תזריע כב, ב. ונו\"א נדפס בסה\"מ הנחות הר\"פ ע' קנד (בכותרת: ס\"ט, יום ה' דשלשה ימי הגבלה בדרך). ונו\"א נמצא בכת\"י 929 (סח, א). ונו\"א באריכות בס' מאמרי אדהאמ\"צ ויקרא ח\"ב ע' תנו (ועיג\"כ שם ע' תמג ובמ\"מ שם).\nוראה המאמר בשינויים בדרמ\"צ להצ\"צ מצות טומאת המצורע פ\"ב ופ\"ג (קג, א ואילך). ובשינויים בסה\"מ תרל\"ה ח\"א ע' רכ ואילך. והגהות על המאמר באוה\"ת תזריע כרך א' ע' רנב (שו\"ה בקדושה, מן תיבת: קוב\"ה). שם ע' שמז. כרך ב' ע' תקכז וע' תקלא. וראה שם כרך ג' ע' תתטו. כרך ד' ע' א'נב. וראה גם סה\"מ עזר\"ת ע' קעו ואילך. לקוטי שיחות חי\"ב ע' 64 ואילך. ונמצא עוד כמה ביאורים על לשון המאמר בלקו\"ת (ועד\"ז הוא בנוסח המאמר שלפנינו כאן) בלקו\"ש ח\"ז ע' 308 (ונדפס ג\"כ באגרות קודש ח\"ו ע' לט)."],["1138","2","<b>קמיפלגי ברקיע</b>: ב\"מ פו, א."],["1139","3","<b>ובמ\"א נתפרש הטעם משום שנאמ' בתורה לטהרו ואח\"כ לטמאו</b>: נזיר סה, ב. תזריע יג, נט."],["1140","4","<b>ברפב\"י שאמר גינאי חלוק לי נהרא</b>: חולין ז, א."],["1141","5","<b>זוטרא דבכו מחיה המתים</b>: ע\"ז י, ב."],["1142","6","<b>כמ\"ש בזהר דאיהו ברוך</b>: זח\"ב קסב, א. זח\"ג רסד, ב."]]],[2101000192,"דאיהו ברוך, ויש בזה ב' פירושים הא' מלשון והמלך<sup data-n=\"1143\">7</sup> שלמה ברוך שפירושו שהוא איש הברו\"ך מזולתו, והוא בחי' מקבל, והב' הוא מלשון ברו\"ך שמברך לזולתו ומשפיע לו, ושניהם אמת כי חכמה היא מקור האצי' שממנו נמשכים כל הי\"ס כמשל התפשטות ההשגה מסקירת השכל ואח\"כ נמשך במדות והוא פי' ברו\"ך שמשפיע וכמו בריכה כו' אלא שהבריכה היינו השפע הנמשכת מאותו הברו\"ך המשפיע וכידוע<sup data-n=\"1144\">8</sup> דר\"ת ברו\"ך הוא רא\"ש ומקו\"ר כ\"ל ברכ\"ה כו'. ואמנם החכמה לגבי מה שלמעלה הימנה היא בחי' אי\"ן ממש והתהוותה הוא שלא בדרך השתלשלות כי ענין ההשתלשלות הוא עילה ועלול שהעלול מתהוה מכח העילה ממש להיות שהם בסוג א' וכדמיון התהוות התפשטות השגה מסקירת השכל, וכן התהוות התפעלות המדה מהתבוננות שמהות ועצם השכל מתלבש בהשגה זו וכן מהות ההשגה ועצמותה ממש מתלבשים בההתפעלות, אבל החכמה לגבי הכתר כתיב<sup data-n=\"1145\">9</sup> מאי\"ן תמצא וכבר נודע פי' לשון מציאה שהוא ד\"מ כמו המוצא איזו חפץ שאינו יודע מאין באתה לו, כמ\"כ התהוות החכמה מהכתר שהוא בחי' השכל מלמעלה מן השכל אינו בא בדרך גילוי אור והשפעה רק מבחי' אחוריים וצמצום גדול עד שנק' רק מציאה והיינו שאמר מאי\"ן כו' וגם הכתר הרי הוא נמשך מבחי' מל' דא\"ס ובחי' המל' נק' בשם אור וזיו מהמאציל עצמו, וכמשל הזיו שאינו פועל שינוי תוספת או מגרעת בהמאור כנודע והוא הנק' קדוש ומה שנמשך ממנו בבחי' חכמה שמשם הוא בחי' השתלשלות נק' ברוך כו' ובדרך כלל הם סכ\"ע וממכ\"ע.\n<b>והנה</b> התנאים ואמוראים היה כל עסקם בהמשכת אור א\"ס ע\"י התורה כי כל עבודתם הי' בעסק התורה כדאשכחן בר'<sup data-n=\"1146\">10</sup> יהודה דהוה מצלי מתלתין יום כו' וכיוצא. והענין הוא כי הנה ענין התורה והתפלה הוא שהתפלה היא הקדמה להתורה והוא מה שמתבונן בגודל הפלאת וערכת מעלת הא\"ס ב\"ה איך שלגדולתו אין חקר ובכל העולמות מריש כל דרגין עד סוף כל דרגין אין מאיר ממנו ית' רק הארה א' כטיפה מהים עד שכל הקרוב קרוב קמי' יותר כלא מפני שמכיר יותר פחיתות השגתו בו ית' ואי לזאת יפול מאד בדאגה ובמרירות, וע\"ז כיוונו באמרם ז\"ל אין<sup data-n=\"1147\">11</sup> מוסרין ס\"ת אלא למי שלבו דואג בקרבו שהדאגה אינה עצבון גשמי ח\"ו רק מהעדר גלוי האלקות כו', ואמנם ע\"י התורה ישמח לבו כדכתי' פקודי<sup data-n=\"1148\">12</sup> הוי' משמחי לב ומדקאמר משמח\"י משמע שמתחלה לא הי' השמחה.\n<b>והענין</b> הוא שע\"י התורה ממשיך אור א\"ס הסוכ\"ע להיות מאיר על נפשו גם<sup data-n=\"1149\">13</sup> בהיותו לומד בחכמתו ורצונו שנעשה כלי להשראתו והוא כמו השלהבת",[["1143","7","<b>והמלך שלמה ברוך</b>: מלכים א ב, מה."],["1144","8","<b>וכידוע דר\"ת ברוך הוא ראש ומקור כל ברכה</b>: ראה ת\"ז ת\"ע (קכ, ב). פרדס שער ערכי הכינויים בערכו."],["1145","9","<b>כתיב מאין תמצא</b>: איוב כח, יב. [וראה במ\"מ בס' מאמרי אדהאמ\"צ ויקרא שם ע' תנח]."],["1146","10","<b>בר' יהודה דהוה מצלי מתלתין יום כו'</b>: סוף מס' ר\"ה."],["1147","11","<b>אין מוסרין ס\"ת [ סתרי תורה] אלא למי שלבו דואג בקרבו</b>: ראה חגיגה יג, א. [וראה במ\"מ בס' מאמרי אדהאמ\"צ שם ע' תסא]."],["1148","12","<b>פקודי ה' משמחי לב</b>: ע\"פ תהלים יט, ט."],["1149","13","<b>גם</b>: בדרמ\"צ קג, סע\"א (שם נמצא קרוב להלשון כאן) ליתא תיבה זו."]]],[2101000193,"שקשורה בגחלת שהיא בהעלם וכדי שתבא לגילוי צריך לנפחה וכל שינפח בחוזק יותר כך יוסיף התגלותה כמ\"כ התורה יש בה בבחי' העלם התלבשות אור הא\"ס שכל המצות הן רצונו ית' ואע\"פ שאינן מושגים לנו ה\"ז כדמיון האוחז כלי מלא דינרים כו' ששמח בהם אע\"פ שאינו רואה אותם בפועל רק מצד שיודע שהם שם בודאי וכידוע<sup data-n=\"1150\">14</sup> בגמ' דלקיחה ע\"י ד\"א שמה לקיחה. וע\"כ נאמר כי<sup data-n=\"1151\">15</sup> אמרתך חייתני והוא מצד האור דתורה גם שהוא בהעלם כו'<sup data-n=\"1152\">16</sup>. ואמנם התנאים שהיו מבחי' מוחין דגדלות הי' בכחם להוציא אור התורה לגילוי וכמשל הנופח בשלהבת כו' וע\"כ הי' בכחם לעשות נסים ונפלאות גדולים, וכמו רפב\"י דאמר גינאי חלוק לי נהרא וחרבו המים והוא כי ים ויבשה הוא אתכסיא ואתגליא והיינו בבחי' השתלשלות ששם יש העלם וגילוי אבל ע\"י אור דתורה שנמשך מבחי' סכ\"ע וקמי' שוין אז נהפכו המים לחרבה כו'.\n<b>וזהו</b> ענין מתיבתא דרקיע. כי<sup data-n=\"1153\">17</sup> הנה התורה ישנה באצי' ובבי\"ע וכמו עד\"מ מצות ציצית שהיא למטה מצמר כבשים כמ\"כ למעלה באצי' יש בחי' כבשים כמו והכבשים<sup data-n=\"1154\">18</sup> הפריד יעקב ויש בהם צמר שהוא כמ\"ש ושער<sup data-n=\"1155\">19</sup> רישי' כעמר נקא, וכן תפילין יש ד' מוחין וקשר<sup data-n=\"1156\">20</sup> של ד' הוא בחי' מל' דתבונה והוא שכמו למטה הוא מעור בהמה כך למעלה יש בחי' לבושי' והוא עד\"מ השכל שבנפש שפעמים מתלבש בדבר חכמה כשחושב חכמת אלקית ופעמים חושב חכמות אחרות והם לבושים נמוכים ופעמים חושב ומעמיק בדברים בטלים שהם לבושים יותר גסים כו' וכמ\"כ למעלה יש כמה מיני לבושים לאור ההשגה עליונה דבינה ובחי' מל' דתבונה נק' עו\"ר והוא ענין לבוש החשמ\"ל כו' וכיוצא בזה בכל המצות, והנה אותן הנשמות שלמדו למטה ותלמודו<sup data-n=\"1157\">21</sup> בידו הוא יושב ג\"כ בג\"ע ולומד היינו שמשיג איכות וכמות המצוה שבאצי' כמו הציצית והתפילין וכל פרטי דיניהם תכל\"ת ולב\"ן שהם הכל מדריגות<sup data-n=\"1158\">22</sup> כו' וכנודע לי\"ח. עמ\"ש<sup data-n=\"1159\">23</sup> פ' בהר ד\"ה כי תבואו כו'.\n<b>וזהו</b> ענין מתיבתא דרקיע, פי' כי כמה מקומות יש שלומדים למעלה והוא ג\"ע עליון שהוא בבריאה וג\"ע התחתון ביצי' וכיוצא פרטי מדריגות והיינו הכל",[["1150","14","<b>וכידוע בגמ' דלקיחה ע\"י ד\"א שמה לקיחה</b>: סוכה לז, א."],["1151","15","<b>כי אמרתך חייתני</b>: תהלים קיט, נ."],["1152","16","<b>כו'</b>: בגוכי\"ק יש כאן סימן להוספת הגהה בצידי העמוד. אך צידי העמודים קרועים (וליתא גם בכת\"י המעתיק, ובשאר מקומות המקבילים לכאן)."],["1153","17","<b>כי הנה התורה ישנה באצי' ובבי\"ע</b>: ראה ס' מאמרי אדהאמ\"צ ויקרא שם ע' תסו. וש\"נ."],["1154","18","<b>והכבשים הפריד יעקב</b>: ויצא ל, מ. (שם: והכשבים)."],["1155","19","<b>ושער רישי' כעמר נקא</b>: דניאל ז, ט."],["1156","20","<b>וקשר של ד' הוא בחי' מל' דתבונה</b>: ראה פע\"ח שער התפילין פ\"ה. [ונסמן עוד בהמ\"מ במאמרי אדהאמ\"צ ויקרא שם ע' תסח]."],["1157","21","<b>ותלמודו בידו</b>: פסחים נ, א. ועוד."],["1158","22","<b>מדריגות</b>: בדרמ\"צ שם (קג, ב) הל' כאן: מדריגות מדריגות."],["1159","23","<b>עמ\"ש פ' בהר ד\"ה כי תבואו</b>: (תיבות אלו הם הוספת הגה\"ה מאדמו\"ר הצ\"צ). ראה ד\"ה כי תבואו בלקו\"ת בהר מ, ב ואילך (והוא מש\"פ בהר שנת תק\"ס, וע\"ש במ\"מ)."]]],[2101000194,"ערך ואופן התפיס' שלהם וההשגה באותן המצות כו' ומתיבתא דרקיע הם הנשמות היושבים בג\"ע העליון שמאיר שם מהארת הבינה דאצי' כמ\"ש בת\"ז<sup data-n=\"1160\">24</sup> בינה מקננא בכורסייא שהוא עולם הבריאה, והיא הנק' רקיע, כי הנה ידוע<sup data-n=\"1161\">25</sup> ע\"פ ועל ראשי החיות רקיע כו' שהם ב' מיני חיות הא' חיון תתאין שהם בחי' המרכבה דבי\"ע והרקיע שע\"ג הוא בחי' מל' דאצי' וחיון עילאין הם חג\"ת דאצי' והרקיע שע\"ג הוא בחי' בינה וכמ\"ש<sup data-n=\"1162\">26</sup> בזהר השמי\"ם שמי\"ם ב\"פ רקיע עילאה ותתאה כו', ונק' רקיע ע\"ד<sup data-n=\"1163\">27</sup> הידוע בענין אמ\"ר ר\"ת אור מים רקיע שהאו\"ר הוא בחי' חכמה הנעלמה שהוא כח של ההשכלה הפרטיות טרם בואה בבחי' גילוי וסקירה (ואוי\"ר ביו\"ד הוא אור הכתר שנק' ישת<sup data-n=\"1164\">28</sup> חשך סתרו וכמו האוי\"ר שאינו מושג לחוש הראות) ומי\"ם הוא בחי' בריקת השכל שהוא כמו מים שהם מציאות דבר רק<sup data-n=\"1165\">29</sup> דניידי כו' ורקי\"ע הוא בחי' ההשגה שהיא מוגבלת ממש בכל פרטיה וכידוע וע\"כ הבינה שהיא מקור ושרש השגת הנבראים באלקות נק' רקיע, והיושבים בג\"ע העליון ולומדי' נק' מתיבתא דרקיע ונחלקו בדין הבהרת כו'.\n<b>ומתחלה</b> צריך להקדים ענין הבהרת מהו, והוא ע\"ד מ\"ש בזהר<sup data-n=\"1166\">30</sup> בענין הנגעים סגירו דנהורא עילאה כו', פי' כי החכמה<sup data-n=\"1167\">31</sup> תחי' והדם<sup data-n=\"1168\">32</sup> הוא הנפש ושורה החיות שם והנגע הוא הסתלקות החיות דאור אבא שזהו בהרת ואח\"כ כשיש שער לבן הוא טמא וצריך הסגר כו'. והענין הוא כי הנה ידוע שיש י\"ס דקדושה וי\"ס דנוגה והם בהשתלשלות נוגה דאצי' כו' עד נוגה דעשי', והענין כי באצי'<sup data-n=\"1169\">33</sup> איהו וגרמוהי חד ממש שהי\"ס מתכללים זה מזה חסד מגבורה וגבורה מחסד וכמ\"ש בזהר<sup data-n=\"1170\">34</sup> לאכללא שמאלא בימינא וימינא בשמאלא והיינו מצד הארת אור א\"ס שבהן המלובש בחכמה שמייחד אותן (החוטא<sup data-n=\"1171\">35</sup> יכופר גם שאין<sup data-n=\"1172\">36</sup> מיתה בלא חטא כו') ובחי'",[["1160","24","<b>בת\"ז בינה מקננא בכורסייא</b>: ת\"ו (כג, א)."],["1161","25","<b>ידוע ע\"פ ועל ראשי החיות רקיע</b>: ע\"פ יחזקאל א, כב. וראה זח\"ב ריא, א."],["1162","26","<b>וכמ\"ש בזהר השמים שמים ב\"פ רקיע עילאה ותתאה</b>: תהלים קטו, טז. זח\"ב ריג, א. וראה לקו\"ת תזריע שם כב, ד."],["1163","27","<b>ע\"ד הידוע בענין אמ\"ר ר\"ת אור מים רקיע</b>: ראה זח\"ב קלו, ב. קסז, א. ע\"ח שער המלכים (שי\"א) פ\"ו. אוה\"ת חיי\"ש כרך ד' תשפח, ב. ועוד."],["1164","28","<b>ישת חשך סתרו</b>: תהלים יח, יב."],["1165","29","<b>רק דניידי כו'</b>: ראה עירובין מו, א."],["1166","30","<b>בזהר בענין הנגעים סגירו דנהורא עילאה</b>: זח\"ג מט, ב. וראה ע\"ח שער לאה ורחל (של\"ח) פ\"ז."],["1167","31","<b>החכמה תחי'</b>: קהלת ז, יב."],["1168","32","<b>והדם הוא הנפש</b>: פ' ראה יב, כג."],["1169","33","<b>באצי' איהו וגרמוהי חד</b>: ת\"ז בהקדמה ג, ב."],["1170","34","<b>בזהר לאכללא שמאלא בימינא</b>: ראה זח\"ב כו, ב. כז, א. רו, ב. זח\"ג קעח, א. וראה לקו\"ת מטות פו, ב. ואתחנן ז, ד. ובהמ\"מ לשם."],["1171","35","<b>החוטא יכופר גם שאין מיתה בלא חטא כו'</b>: ענין זה מבואר יותר בדרמ\"צ קב, א, וז\"ל: והיינו מצד הארת אא\"ס שבהן המלובש בחכמה שמייחד אותן (כי לגבי אא\"ס מתבטלים חו\"ג ונעשה שלום במרומיו ולכן גם מדת הגבורה מסכמת להיות החוטא יכופר גם שאין מיתה בלא חטא כו' מ\"מ יתרפא החולה ולא ימות), אמנם זהו בי\"ס דקדושה כו' אבל בחי' נוגה דאצי' כו'. וראה ס' מאמרי אדהאמ\"צ ויקרא שם ע' תעה. [וכאן בכת\"י מעתיק של מאמר זה (מס' 791) רשם על שורה זו ”יתיר\", ואפשר לא הבין המעתיק קשר הדברים לכאן וע\"כ סבר שקטע זה נמחק]."],["1172","36","<b>שאין מיתה בלא חטא</b>: שבת נה, א."]]],[2101000195,"נוגה היינו ג\"כ בחי' אלקות שהרי באצי'<sup data-n=\"1173\">37</sup> לא יגורך רע כתי' אלא שהם בחי' ענפין מתפרדי' שהחסד בלתי סובל את הגבורה ואינן מתייחדים זה ע\"ז והיינו מצד שהם נרגשים ליש ודבר עד שאינו סובל זולתו והסיבה לזה הוא מצד שאין אור א\"ס מלובש שם רק בבחי' מקיף בלבד וע\"כ נק' קליפת נוגה שהקליפה היא שאין<sup data-n=\"1174\">38</sup> לה טעם ולחלוחית כו' ומזה נמשך בבי\"ע בחי' יש ממש וצבא השמים כו'.\n<b>והנה</b> מאחר שהשי\"ת יצר אותם מסתמא<sup data-n=\"1175\">39</sup> צ\"ל כן וממילא שיש להם יניקה תמיד מהקדושה כי בלא זה היו כלא היו, אלא שליניקה זו יש שיעור וקצבה ואמנם לפעמים חוטפים יותר מהמדה וע\"ז צריך תיקון ובירור כו' והוא ענין הבהרת שהוא הסתלקות החיות דאור אבא ביו\"ד דחכמה ואז ממילא יכולה הנוגה דאצילות בחי' יש לקבל יניקה וממנו נמשך אח\"כ עד לעשי' ששם הם עומקי הקליפות והיניקה זו שהם מקבלים אח\"כ שער לבן שהשער הוא בחי' המשכה ויניקה כו' וכמ\"ש<sup data-n=\"1176\">40</sup> בע\"ח שמשערות דנוק' הם יונקים, שלכך פשיטא להו למתיבתא דרקיע שאם בהרת שהוא הסתלקות אור אבא מאדם העליון דאצי' קדמה לשער לבן שהוא היניקה שיונקי' טמא הוא כלומר ודאי חטפו יותר מהשיעור וצריך תיקון ע\"י הסגר כו', והא פשיטא להו שאם השער לבן קדם טהור הוא שהרי יניקה צ\"ל להם מהקדושה מעט ומאחר שהיניקה קדמה לההסתלקות דאור אבא בודאי לא לקחו יותר מהשיעור שהרי חכמה היא המונעת היניקה כנ\"ל.\n<b>אבל</b> ספק הקב\"ה אומר טהור, והם אומרים טמא, טעמם הוא שמדמים זה לכל ספיקות שבתורה שספיקן טמא וגם כאן שמא קדמה הבהרת וקבלו יניקה יותר וה\"ז טמא, והיינו כפי הבא להם בהשגת התורה שבג\"ע העליון המקבל מבינה דאצי' השגה עליונה, אבל הקדו\"ש ברו\"ך הוא שהוא אור א\"ס הסכ\"ע אומר טהור והיינו משום שגם שקבלו יניקה מ\"מ מאחר שהוא ספק ואינו ידוע בבירור אין בכך כלום או שלא קבלו יניקה יותר מהראוי כלל גם שקדמה הבהרת מפני שלא נודע, או אף שקבלו לא יהי' מזה התעוררות דינים, וכיוצא בזה הוא בממזר<sup data-n=\"1177\">41</sup> שספיקו טהור מצד זה שלו יהי כן אבל מפני שלא נודע בבירור אינו מזיק כלל, ואמנם זהו למעלה מההשגה ולא ידעו הם מזה שעיקר למודם הוא מה שבא בהשגה בג\"ע עליון כי מה שלמעלה מהשגה נק' עדן שעין<sup data-n=\"1178\">42</sup> לא ראתה וכו' רק הקדו\"ש ב\"ה שמובדל הוא למעלה מחו\"ב וכו'.",[["1173","37","<b>באצי' לא יגורך רע</b>: ע\"פ תהלים ה, ה. ראה לקו\"ת במדבר ג, סע\"ג. [וש\"נ בארוכה]."],["1174","38","<b>שאין לה טעם ולחלוחית כו'</b>: בדרמ\"צ שם נוסף: ר\"ל שאין אא\"ס מלובש בתוכן."],["1175","39","<b>מסתמא צ\"ל כן</b>: בדרמ\"צ שם נוסף: ר\"ל שיש צורך בהתהוות הקליפות."],["1176","40","<b>וכמ\"ש בע\"ח שמשערות דנוק' הם יונקים</b>: ראה ע\"ח שער ק\"נ (שמ\"ט) פ\"ד. ועוד. וראה ס' מאמרי אדהאמ\"צ ויקרא שם ע' תעח (בשם הזוהר) ובהמ\"מ שם."],["1177","41","<b>בממזר שספיקו טהור</b>: קידושין עג, א. וראה הגה\"ה ע\"ז בדרמ\"צ (הוצאת תשנ\"א ואילך) קיג, ב."],["1178","42","<b>שעין לא ראתה כו'</b>: ישעי' סד, ג. ברכות לד, ב."]]],[2101000196,"<b>ומאן</b> נוכח פי' שיבא להתאמת אצלם שהם מוגבלים בהשגה, אמרי נוכח רב\"נ שהוא יחיד בנגעים וכו', פי' כי אע\"פ שהתורה היא בבחי' השגה אצלם מ\"מ יש בה הארה שלמעלה מהשגה והוא מ\"ש בע\"ח<sup data-n=\"1179\">43</sup> שהאור מקיף בוקע הארה בתוך הא\"פ והיינו שהא\"פ הוא המוגבל בהשגה והמקיף הוא מה שאינו מוגבל וא\"כ הי' הא\"פ בלתי משיג כלל בהמקיף שלו רק הארה בוקעת בו להיות אעפ\"כ מרגיש גם מה שלמעלה וכו', וכמ\"כ בתורה הי' הארה מלמעלה מהחכמה בתוך חכמת התורה המושגת במתיבתא דרקיע בבחי' בקיעא והיינו מדרגת רב\"נ שנק' מפני זה יחיד בנגעים כו' והוא מצא דרש ורמז בתוך התורה על דין זה אע\"פ שהוא למעלה מההשגה והיינו מ\"ש לטהרו תחלה כנ\"ל.",[["1179","43","<b>בע\"ח שהאור מקיף בוקע הארה בתוך הא\"פ</b>: ראה ע\"ח שער השתלשלות י\"ס דרך עגולים (ש\"ב) ענף ג'. וראה לקו\"ת שה\"ש ל, ב."]]],[2101000197,"<h3>זכור את יום השבת</h3>\n<b>זכור את יום השבת </b>\n<b>זכור</b><sup data-n=\"1180\">1</sup> את יום השבת לקדשו<sup data-n=\"1181\">2</sup> וכתיב שמור<sup data-n=\"1182\">3</sup> את יום השבת לקדשו וארז\"ל זכור<sup data-n=\"1183\">4</sup> ושמור בדיבור א' נאמרו מה שאין הפה יכול לדבר ואין האוזן יכולה לשמוע, ויש להבין מאחר שאין האוזן יכולה לשמוע למה נאמרו בדיבור א' אחר שלא יכלו לשמוע (ואם שמעו למעלה מן הטבע, לאיזה טעם נאמ' להם בדיבור א' דווקא, יותר טוב הי' שיאמר להם בשתי דברות) והנה עוד יש להבין במ\"ש אשר<sup data-n=\"1184\">5</sup> ישנו פה ואשר איננו פה כו' דכל הנשמות שעתידים להיות בעוה\"ז עד סוף כל הדורות הי' במעמד ה\"ס לקבל את התורה ובודאי נשמה בלא גוף לא תוכל לקיים מעשה המצוה בגשמיות, וא\"כ קבלת התורה שקבלו אותן הנשמות בלא גופים עדיין קבלו על העתיד דוקא, דהיינו כאשר יבא למטה בהתלבשות בגופים וזה יפלא לכאורה דהא אין אדם מקנה דבר שלא ברשותו ושמא לא יסכים הגוף ויעכב על קבלה זאת וימנע מעשות קיום התורה, וגם יש להבין במ\"ש לא<sup data-n=\"1185\">6</sup> יהי' לך אלקי' אחרים על פני מהו על פני דוקא הלא אין עוד מלבדו כתיב.\n<b>אך</b> הנה כ\"ז יובן בהקדים שרש ענין קבלת התורה במעמד הר סיני דהנה אין הכוונה בקבלת התורה במעמד ה\"ס בשביל קבלת פרטי הי' דברות בלבד, כמו במצות שבת וכבוד אב וכיוצא, שהרי רוב מצות כיוצא בהן נתנו אח\"כ ולא נאמרו אז ואיך יתכן לומר שזה נק' קבלת התורה כולה מאחר שלא כל התורה ניתנה אז רק",[["1180","1","<b>זכור את יום השבת</b>: נדפס בשינויים בתו\"א יתרו ע, ד. וראה גם ד\"ה זה בס' מאמרי אדהאמ\"צ הנחות תקע\"ז ע' קיט. וראה בהנסמן לקמן להביאור."],["1181","2","<b>זכור את יום השבת לקדשו</b>: שמות כ, ח."],["1182","3","<b>שמור את יום השבת</b>: דברים ה, יב."],["1183","4","<b>זכור ושמור בדיבור א' נאמרו</b>: מכילתא שמות כ, ח."],["1184","5","<b>אשר ישנו פה</b>: דברים כט, יד."],["1185","6","<b>לא יהי' לך אלקים אחרים</b>: שמות כ, ג."]]],[2101000198,"אח\"כ פרשיות פרשיות כאו\"א במועדו ובזמנו כל משך מ' שנה שהיו במדבר כידוע, אלא עיקר ענין קבלת התורה הוא בחי' המשכות כח אלקי בישראל להיות יכולים להמשיך גילוי אוא\"ס בעסק עבודתם בתומ\"צ לדורות בנ\"י העתידים ג\"כ, וזה הכח וההכנה הזאת בנפשם קבלו בשעת מעמד ה\"ס וע\"כ גם כל הנשמות שלא באו בגופים עדיין הוצרכו לקבלה זאת להיות מוכנים להמשיך גילוי אוא\"ס בעסקם בתומ\"צ כאשר יבואו בגופים בעוה\"ז, וז\"ש אשר ישנו פה ואשר איננו פה כו' כולם הושוו בקבלה זאת, כי הלא אנו רואים שאין כח זה אלקי רק לישראל בלבד, שהרי אם יעשה אותם האדם אשר לא מבנ\"י המה לא ימשיך גילוי אלקות כלל כידוע והיינו לפי שבמעמד ה\"ס נמשך בנפש כל א' מישראל כח קבלת התורה להיו' בחי' גילוי אוא\"ס בנפש האדם כשיעסוק בתומ\"צ ואם לא בחי' קבלה זאת הרי ידוע דאין ערוך כלל לנבראים עם הבורא והמאציל כו' שנק' קדוש ומובדל רק כי בחי' זיו והודו של שמו נמשך על כל העולמות וכמ\"ש כי<sup data-n=\"1186\">7</sup> נשגב שמו לבדו הודו על ארץ ושמים, דגם בחי' שמו נשגב ומרומם בערך, לפי שגם שמו לא נמשך רק בחי' הזיו ממנו, והוא הנק' בחי' הארה דהארה כו' וד\"ל, וא\"כ איך יש בערך יכולת נפש האדם בע\"ג לעורר בחי' גילוי אוא\"ס בבע\"ג, רק ע\"י בחי' קבלת התורה נמשך ומתגלה אוא\"ס בנפש האדם כל שעה שעוסק בתומ\"צ כנ\"ל וד\"ל.\n<b>והנה</b> מזה הטעם יובן ענין הקולות וברקים שהי' בשעת מ\"ת ברעם ורעש גדול, כמ\"ש וכל<sup data-n=\"1187\">8</sup> העם רואים את הקולות כו' ויחרד כל העם אשר במחנה, דהנה ידוע ומבואר במ\"א דכל בחי' התחדשו' והתהוות דבר חדש א\"א שיתהווה בחי' יש מיש אלא בבחי' יש מאין עד\"מ צמיחת הגרעין מן החטה הנזרעת בארץ א\"א שתצמיח בלתי אם לא שיורקב וישוב אל העפר תחלה ויהי' בחי' ביטול היש לאין דכח הצומח ואז יחזור ויתחדש ויצמח מחדש, אבל כל זמן שהחטה אינה נרקבת ואינה בבחי' ביטול ישותה לא תצמח מחדש, א\"כ הרי דוקא בחי' ביטול היש מוליד התהוות חדשה, וככה יובן בדוגמא למעלה דאין גילוי אוא\"ס מאיר מחדש בנפש כ\"א ע\"י בחי' ביטול היש בתחלה, והוא טעם ענין קבלת התורה בקולות וברקים ברעש גדול להחריד תחלה, וכמארז\"ל דעכדו\"ד<sup data-n=\"1188\">9</sup> פרחה נשמתן כו' בבחי' חרדה הגדולה וביטול במציאות ממש לאוא\"ס ב\"ה, ועי\"ז הביטול היש נמשך התחדשות והתהוות אור אלקי חדש בנפשם כמשל הנ\"ל, וזהו מ\"ש כי<sup data-n=\"1189\">10</sup> לבעבור נסות אתכם בא אלקי' כו' פי' נסות מלשון הרמת נס והיינו ענין ובחי' התנשאות והעלאות נפשם לבטלם ממציאותם ולהעלותם ולקשרם באוא\"ס ב\"ה להיות מובדלים מן העמים ע\"כ בא אלקים עליהם בקולות וברקים ברעם ורעש גדול.\n<b>והנה</b> המלאכים<sup data-n=\"1190\">11</sup> בקשו לקבל את התורה כמ\"ש תנה הודך על השמים ולא ניתנה להם, והגם שישראל נשמתם מלובש בגופים חומריים וגופי המלאכים",[["1186","7","<b>כי נשגב שמו לבדו</b>: תהלים קמח, יג."],["1187","8","<b>וכל העם רואים את הקולות</b>: שמות כ, טו."],["1188","9","<b>דעכדו\"ד פרחה נשמתן</b>: שבת פח, ב."],["1189","10","<b>כי לבעבור נסות אתכם</b>: שמות כ, יז."],["1190","11","<b>המלאכים ביקשו את התורה כמ\"ש תנה הודך</b>: שבת פח, ב. תהלים ח, ב."]]],[2101000199,"רוחניים יותר כמ\"ש עושה<sup data-n=\"1191\">12</sup> מלאכיו רוחות, אך הטעם הוא לפי ששרש המלאכים הוא מבחי' הבל דיבור העליון כמ\"ש וברוח<sup data-n=\"1192\">13</sup> פיו כל צבאם הנק' עלמא דאתגלי' להיותו בא בבחי' הגילוי מן ההעלם למטה מטה עד\"מ הדיבור באדם שאינו אלא לזולתו כידוע והרי אותיות הדיבור נעשים דבר נבדל מעצם האדם לאחר שיוצא לחוץ ואינו מתאחד בעצמות נפשו, משא\"כ בחי' אותיו' המחשבה שמתאחדים בעצמות הנפש בתמידות בלי פירוד כלל, שהרי הנפש נק' נפש המשכלת שמשכלת השגות באותיות המחשבה, ונמצא גם אותיו' המחשב' נק' נפש המשכלת כי א\"א לנפש להשכיל שכל בלי אותיו' המחשב' שמחשב ומעיין בו בעיון המחשב' והרהור כנודע, ובהכרח שהשכל מתלבש תמיד במחשב' והיו לאחדים (וע\"כ מחשבה<sup data-n=\"1193\">14</sup> הוא חשב מ\"ה כמו חכמה<sup data-n=\"1194\">15</sup> כ\"ח מ\"ה) אבל באותיות הדיבור לא יש הכרח שיתלבש בו השכל גם בשעה שמדבר אותם כו' יוכל לחשוב אותו השכל ולא ידבר בדעת ובבינה עד שלא ישמע מה שמדבר רק במחשבה בלבד חושב כוונת השכל לפי שהדיבור נבדל (משא\"כ המחשבה לא יוכל להפריד השכל ממנו, כי בהכרח צריך להלביש השכל במחשבה ובלעדה לא יתגלה כלל בבינה רק בחכמה כו') ומכ\"ש שיוכל להפסיק הדיבור, או לדבר מה שנגד השכל והרצון, אבל המחשבה לא יכול להפסיקה כי משוטטת תמיד (וכמ\"ש ונהר<sup data-n=\"1195\">16</sup> יוצא מעדן יוצא תמיד וכמ\"ש במ\"א) וכך יובן עד\"מ למעלה שיש ב' מיני אותיות עליונים, הא' הנק' בחי' דיבור העליון, שהוא בחי' כח אלקי נבדל מעצמות המאציל ומשם נחצבו המלאכים ומ\"מ נק' אותיות להיותם בחי' המשכות למטה מלשון ואתא<sup data-n=\"1196\">17</sup> בוקר ואתא<sup data-n=\"1197\">18</sup> מרבבות קודש כו' כידוע, והב' בחי' אותיות המחשבה שנק' עלמין סתימין דלא אתגליין והן המתאחדין בעצמיו' בחי' חו\"ב דאצי' כמשל המחשב' באדם שמתאחדת תמיד בשכל כנ\"ל כמ\"ש כי<sup data-n=\"1198\">19</sup> לא מחשבותי מחשבותיכם כו' ומשם נחצבו נש\"י כמארז\"ל ישראל<sup data-n=\"1199\">20</sup> עלו במחשבה, במחשבה דוקא למעלה מבחי' דיבור כו', והן ס\"ר אותיות דתורה שהן שרשים לס\"ר<sup data-n=\"1200\">21</sup> נש\"י, כי תלת<sup data-n=\"1201\">22</sup> קשרין אינון, ישראל מתקשראן באורייתא ואורייתא בקוב\"ה כו', ולכך ניתנה התורה לישראל דווקא ולא למלאכים עליונים, כי התורה מתאחדת בחכמה עילאה כמארז\"ל דאורייתא<sup data-n=\"1202\">23</sup> מחכמ' עילאה נפקת בחי' שרש נש\"י שהוא בחי' המחשבה עליונה מתאחדת בחכמה עילאה ג\"כ כנ\"ל במשל הנ\"ל וד\"ל.",[["1191","12","<b>עושה מלאכיו רוחות</b>: תהלים קד, ד."],["1192","13","<b>וברוח פיו כל צבאם</b>: תהלים לג, ו."],["1193","14","<b>מחשבה הוא חשב מ\"ה</b>: זח\"א כד, א. ת\"ז תס\"ט (קיב, ב)."],["1194","15","<b>חכמה כ\"ח מ\"ה</b>: ת\"ז שם. זח\"ג כח, א. לד, א. ובכ\"מ."],["1195","16","<b>ונהר יוצא מעדן</b>: בראשית ב, י. וראה זח\"ב קכג, ב. ובכ\"מ."],["1196","17","<b>ואתא בוקר</b>: ישעי' כא, יב."],["1197","18","<b>ואתא מרבבות קודש</b>: ע\"פ דברים לג, ב."],["1198","19","<b>כי לא מחשבותי מחשבותיכם</b>: ישעי' נה, ח."],["1199","20","<b>ישראל עלו במחשבה</b>: ב\"ר בתחילתו. ובכ\"מ."],["1200","21","<b>ס\"ר אותיות דתורה שהן שרשים לס\"ר נש\"י</b>: ראה הערת כ\"ק אדמו\"ר זי\"ע בסה\"מ תש\"ח ע' 241. וראה לקו\"ת בהר מג, ד. סה\"מ הנחות הר\"פ ע' סג. עב. תו\"ח תולדות יא, ב."],["1201","22","<b>תלת קשרין אינון</b>: זח\"ג עג, א. וראה הערת כ\"ק אדמו\"ר זי\"ע בסה\"מ ת\"ש ע' 61."],["1202","23","<b>דאורייתא מחכמ' עילאה נפקת</b>: זח\"ב פה, א. קכא, א."]]],[2101000200,"<b>ואע\"פ</b> שהוא אינו נק' רק בשם לבוש לנפש כידוע, הנה מ\"מ בחי' הלבוש של המחשבה נק' לבוש פנימי שמתאחד בנפש כנ\"ל, אבל לבוש הדיבור נק' לבוש חיצוני כי הוא נבדל מעצמות כנ\"ל, ומ\"ש לבושין<sup data-n=\"1203\">24</sup> תקינת לון דמנייהו פ\"נ לב\"נ כו' היינו דווקא בחי' לבוש שהוא בחי' לבוש פנימי שמיוחד בעצמיות שמשם שרש כנ\"י, וע\"ז אמר לבושין תקינת לון כו', וזהו ג\"כ ענין איהו<sup data-n=\"1204\">25</sup> וגרמוהי חד, כי הנה אמר ב' מיני יחודים, הא' דאיהו וחיוהי חד, והב' דאיהו וגרמוהי חד, פי' איהו וחיוהי קאי על בחי' חו\"ב דאצי' שנק' חיוהי כמ\"ש והחכמה<sup data-n=\"1205\">26</sup> תחי' כו', ולהיו' כי בחי' חכמה דאצי' מתיחדת בעצמות אוא\"ס, כי<sup data-n=\"1206\">27</sup> הוא המדע והוא הידוע כמאמ' אנת<sup data-n=\"1207\">28</sup> חכים ולא בחכמ' ידיעא, כי הוא וחכמתו אחד כו' ע\"כ אמר דאיהו שהוא עצמיו' אוא\"ס וחיוהי שהוא בחי' חו\"ב חד בהון שמתייחד בהון בתכלית היחוד, וכמ\"כ יחוד הב' ג\"כ דאיהו וגרמוהי חד, דהיינו בחי' אותיו' המחשבה שנק' גרמוהי בחי' לבוש וכלי פנימי לשכל כנ\"ל המתאחד בחו\"ב כנ\"ל, וגם שם אוא\"ס מתייחד ביחוד גמור, וז\"ש דאיהו וגרמוהי חד, ומטעם הנ\"ל בענין התאחדות המחשב' בעצמות כו' כנ\"ל וד\"ל. וזהו שבקשו המלאכים שנמשכו מבחי' הדיבור שיומשך ע\"י קבלת התורה שיקבלו בחי' גילוי אוא\"ס כנ\"ל ולא ניתנה להם להיות שאין בחי' הדיבור מתייחד כ\"כ כמו בחי' המחשבה שרש נש\"י שעלו במחשבה שע\"ז נאמר איהו וגרמוהי חד כו' שמתייחד באחדות גמורה באוא\"ס ע\"כ ישראל דווקא יוכלו לקבל את התורה להמשיך גילוי יחוד אור א\"ס בעסק תורתם ועבודתם כנ\"ל ולא זולתם כנ\"ל וד\"ל.\n<b>אך</b> להבין שרש הדברים הנ\"ל, הנה להבין שרש ענין קבלת התורה, יש להקדים תחלה להבין שרש ענין בחי' היחודים שנעשה ע\"י התומ\"צ כמ\"ש ליקוב\"ה ושכינתי', דהיינו בחי' יחוד דסובב וממלא שנק' קוב\"ה ושכינתי' יחו\"ע ויחו\"ת כידוע, ובכללות ההשתלשלות היינו בחי' יחוד דאוא\"ס באבי\"ע למהוי א' בא' דהיינו בחי' אחה\"פ שבעצמו' אוא\"ס למעלה מע\"ס דאצי' כמ\"ש ולאו מכל אלין מדות כלל, שיהי' שורה ומיחד בע\"ס דאצי' ודבריא' שנק' אחד תתאה כו', הנה לכאורה יש להבין איך יתכן שיהי' תלוי בחי' המשכות אוא\"ס בנאצלי' ונבראים כו' דווקא ע\"י מעשה המצות כמ\"ש אם<sup data-n=\"1208\">29</sup> בחוקותי תלכו כו' ונתתי גשמיכם בעתם כו' ועץ השדה יתן פריו כו' וכן מ\"ש והי'<sup data-n=\"1209\">30</sup> אם שמוע תשמעו אל מצותי כו' ונתתי מטר ארצכם בעתו כו' שכ\"ז מורה על בחי' המשכת הרוחני' דמאציל באבי\"ע ג\"כ כידוע, ואם לא ילכו בחוקותי ומצותי לא ישמעו ימנע המאציל בחי' המשכה הרוחני' כו', והלא ברית כרותה מימי המבול במראה הקשת שאמר וראיתי'<sup data-n=\"1210\">31</sup> לזכור ברית עולם כו' דהיינו",[["1203","24","<b>לבושין תקינת לון</b>: ת\"ז בהקדמה ד\"ה פתח אליהו."],["1204","25","<b>איהו וגרמוהי חד</b>: ת\"ז בהקדמה לפני ד\"ה קום יחזקאל."],["1205","26","<b>והחכמה תחי'</b>: קהלת ז, יב."],["1206","27","<b>כי הוא המדע והוא הידוע</b>: רמב\"ם הל' יסוה\"ת פ\"ב ה\"י. מו\"נ ח\"א פס\"ח. שמונה פרקים פ\"ח. וראה תניא פ\"ב ובליקוט פירושים ומ\"מ שם."],["1207","28","<b>אנת חכים ולא בחכ' ידיעא</b>: ת\"ז בהקדמה ד\"ה פתח אליהו."],["1208","29","<b>אם בחוקותי תלכו</b>: ויקרא כו, ג."],["1209","30","<b>והי' אם שמוע תשמעו</b>: דברים יא, יג."],["1210","31","<b>וראיתי' לזכור ברית עולם</b>: בראשית ט, טז."]]],[2101000201,"שיהי' קיום תמידי לשפע כל העולמות מן המאציל מריש כל דרגין דאצי' עד סוף כל דרגין בעוה\"ז הגשמי', וז\"ש עוד<sup data-n=\"1211\">32</sup> כל ימי הארץ זרע וקציר כו' קיץ וחורף יום ולילה לא ישבותו כו', וא\"כ א\"א שיופר הברית הזה לעולם גם בלתי קיום המצות, ולמה אמר אם בחוקותי תלכו כו' ואם לאו יתבטל הליכות השפעתן מן המאציל האלקי' הרוחני' והגשמיי', הרי אין לה ביטול עולמית מצד כריתות ברית כמ\"ש וראיתי' לזכור ברית עולם כו'.\n<b>אך</b> הענין הוא דזה ודאי שא\"א להיו' בחי' ביטול לגמרי בהמשכת הרוחני בסדר השתלשלו' דאבי\"ע מחמת כריתו' ברית כנ\"ל, אבל הנה מ\"מ צריכי' לקיום המצות, לפי שכל בחי' ההמשכה והשפע שנמשך מן המאציל לד' עולמות דאבי\"ע אינו בא רק בבחי' צמצום ומדה ושיעור רק כדי חיות וקיום העולמו' בלבד ע\"פ מאמר קו המדה כידוע בזהר ובע\"ח, אבל כדי שיהי' נמשך תוס' אור ושפע חדשה יותר מכפי מדה הקצובה שהוסדה מכבר בסדר ההשתלשלות מצד כריתו' ברית כנ\"ל הנה לזה צריך דווקא קיום המצוה למטה, וז\"ש אם בחוקותי תלכו כו' אזי יומשך תוס' אור חדש בתוס' מרובה על העיקר שכבר הוסד ע\"פ מאמר קו המדה כו' ואם לאו לא יומשך תוספו' או\"ח מחודש, אלא רק כמו שהוסד בוימ\"ב הילוך השפע בבחי' צמצום ומדה כדי שיעור וחיות וקיום העולמו' בלבד, וז\"ש אם<sup data-n=\"1212\">33</sup> לא בריתי יומם ולילה חוקות שמים וארץ לא שמתי, ויתפרש בב' אופני', הא' ע\"פ פשוט דקאי בכריתות ברית שכבר נעשה ביום ולילה שלא ישבותו כמ\"ש לנח והקימותי את בריתי אתכם<sup data-n=\"1213\">34</sup> כו' זאת אות הברית את קשתי נתתי בענן כו' וראיתי' כו', ובדרז\"ל ידוע שתנאי<sup data-n=\"1214\">35</sup> הי' להקב\"ה במע\"ב אם יקיימו מוטב ואם לאו אחזיר אתכם לתהו כו', וזהו אם לא בריתי בקיום תורה, חוקות יום ולילה חוקות שמים וארץ לא שמתי כו' חוקות מזונם ע\"פ ק\"ה ג\"כ והיינו ע\"פ הנ\"ל וד\"ל.\n<b>וזהו</b> שרש ענין המצות כמארז\"ל לעבדה ולשמרה, לעבדה<sup data-n=\"1215\">36</sup> זו רמ\"ח מ\"ע כו' דמשמע שע\"י רמ\"ח מ\"ע נמשך בחי' תוס' או\"ח תמיד בג\"ע העליון והיינו פי' לעבדה, כי הגם שהג\"ע כבר נברא יש מאין כמ\"ש ויברא<sup data-n=\"1216\">37</sup> ה' אלקי' גן בעדן מקדם כו' אבל להוסיף אור אלקי בג\"ע הוא ע\"י עבודת האדם למטה במעשה המצות והיינו פי' שכר<sup data-n=\"1217\">38</sup> מצוה מצוה כידוע שהוא בחי' המשכות תוס' אור ענג העליון לנש\"י ע\"י מצוה עצמה מפני שהיא בחי' רצון וענג העליון עצמו דהיינו בחי' מל' דאצי' שנעשה ע\"י לבריאה וזהו גדול משכרה של מצוה שהוא בחי' צמצום האור המתלבש במדה ושיעור למקבלים כו' וד\"ל. והנה בכל פעם ופעם שנאמר בה ציווי של איזה מצוה",[["1211","32","<b>עוד כל ימי הארץ</b>: בראשית ח, כב."],["1212","33","<b>אם לא בריתי יומם ולילה</b>: ירמי' לג, כה."],["1213","34","<b>והקמותי את בריתי אתכם</b>: בראשית ט, יא."],["1214","35","<b>שתנאי הי' להקב\"ה במע\"ב</b>: ראה שבת פח, א. ובכ\"מ."],["1215","36","<b>לעבדה ולשמרה לעבדה זו רמ\"ח מ\"ע</b>: ראה זח\"א כז, א. זח\"ב קסה, ב. ובהנסמן בסה\"מ מלוקט ח\"ו ע' יד."],["1216","37","<b>ויברא ה' אלקים גן בעדן</b>: כ\"ה בהכת\"י. וראה בראשית ב, ח."],["1217","38","<b>שכר מצוה מצוה</b>: אבות פ\"ד מ\"ב. וראה תניא פל\"ז. ובכ\"מ."]]],[2101000202,"מסיים בה אני הוי', כמו<sup data-n=\"1218\">39</sup> בפרש' ציצית שמסיים בה אני הוי', וכמ\"כ בהרבה מצות, לפי שבכללו' המצות נאמר ועשיתם<sup data-n=\"1219\">40</sup> אתם וארז\"ל כאלו עשאוני כו' פי' שהן עושין לשם הוי' להיו' אני מתלבש בשם הוי', וז\"ס אני הוי' כו'.\n<b>וביאור</b> הדברים הנה בחי' תוס' או\"ח מעצמיו' המאציל באבי\"ע שנמשך ע\"י המצוה כנ\"ל הנה נמשך בד' מדרגו' שהן ד' אותיות דשם הוי', והנה היו\"ד שהוא בחי' הצמצום דחכמ' בנקודא תחלה ואח\"כ מן היו\"ד נמשך בחי' התרחבות והתפשטות לאורך ורוחב שהוא הה\"א דבינה, ואח\"כ נמשך בחי' המשכה מלמעלה למטה שהוא הוי\"ו ואח\"כ מן הוי\"ו נמשך בחי' התפשטות דה\"א אחרונה, וזהו הכלל בסדר השתלשלו' מעיל\"ע שבא ע\"י ד' מדרגות הללו בחי' צמצום והתפשטות והמשכה והתפשטות הנכללי' בד' אותיות הוי' ובדרך פרט יש בכל פרטי המשכות ושפע בחי' שם הוי', כמו באור החכמה נמשך שם הוי' במילוי יודי\"ן, ובחסד וכל המדות במילוי אלפי\"ן והוא שם מ\"ה כו' כידוע, ועד\"ז יש כמה מיני אופני המשכות דשם הוי' בכל מצוה ומצוה לפי מה שהוא למעלה, מאחר שהן<sup data-n=\"1220\">41</sup> נק' רמ\"ח אברין דמלכא שהן בחי' כלים לאורות כידוע וידוע דאיהו<sup data-n=\"1221\">42</sup> וחיוהי חד ואיהו וגרמוהי חד, וכאשר על ידן נמשך תוס' אור יותר מכפי צמצום המדה הראשונה באורו' וכלי' ה\"ז בחי' המשכות שם הוי' מחדש שלא נמשך עדיין מן המאציל, וז\"ש אנ\"י הוי', פי'<sup data-n=\"1222\">43</sup> אנ\"י אור הכתר שנק' אי\"ן, ואנ\"י מתלבש בשם הוי' חדש ע\"י כל מצוה לפי שרשו למעלה בכלים דאצי' כו', ודרך כללו' כל המצות הנה יש מצות רבות שאינם מרמזות רק לבחי' יו\"ד דשם הוי', כמו המשכת המוחין חב\"ד, שע\"י שבת ותפילין ומצות ות\"ת<sup data-n=\"1223\">44</sup> וכה\"ג, ויש הרבה מצות שאינן אלא בבחי' הה\"א דבינה, כמו מצות סוכה במקיפים דאימא, וכללו' מצות יו\"ט באור אימא הוא כידוע, וכן יש הרבה מצות ששרשן בבחי' וי\"ו דשם הוי', כמו מצות לולב ואתרוג ומצות המשפטים שהוא בחי' ת\"ת שנק' אמת כמ\"ש משפטי<sup data-n=\"1224\">45</sup> ה' אמת, ומשפט<sup data-n=\"1225\">46</sup> איהו רחמי שהוא ת\"ת, ואות אמת הוא הוי\"ו כמ\"ש<sup data-n=\"1226\">47</sup> בזהר ע\"פ ונתתם לי אות אמת, וכה\"ג הרבה מצות שנכללי' באות וי\"ו, וכן יש הרבה מצות ששרשן בה\"א אחרונה כמו מצות הצדקה, צדק<sup data-n=\"1227\">48</sup> דאיהו דין דינא<sup data-n=\"1228\">49</sup> דמלכותא כו' וצדקה בה\"א הוא בחי' המשכת החסדי' כו' כידוע, וא\"כ כללו' כל המצות נכללי' בשם הוי', ומונע מעשות איזה מצוה ששרשה ביו\"ד מונע שפע אור חדש שהוא נמשך ע\"י זאת המצוה ביו\"ד כו', ולכך המונע עשית המצוה נק'",[["1218","39","<b>כמו בפרש' ציצית</b>: במדבר טו, מא."],["1219","40","<b>ועשיתם אתם וארז\"ל כאילו עשאוני</b>: זח\"ג קיג, א. וראה ויק\"ר פל\"ה, ז."],["1220","41","<b>שהן נק' רמ\"ח אברין דמלכא</b>: ראה ת\"ז תי' ל. זח\"ב קיח, א."],["1221","42","<b>דאיהו וחיוהי חד</b>: ת\"ז בהקדמה לפני ד\"ה קום יחזקאל."],["1222","43","<b>פי' אני אור הכתר שנק' אין</b>: ראה פרדס שער הטעמים פ\"א."],["1223","44","<b>ות\"ת</b>: כ\"ה בהכת\"י."],["1224","45","<b>משפטי ה' אמת</b>: תהלים יט, י."],["1225","46","<b>ומשפט איהו רחמי</b>: ראה ת\"ז בקדמה ד\"ה פתח אליהו."],["1226","47","<b>כמ\"ש בזהר ע\"פ ונתתם לי אות אמת</b>: יהושע ב, יב. זח\"ג ב, א. וראה זח\"א ב, ב."],["1227","48","<b>צדק דאיהו דין</b>: ראה ת\"ז ד\"ה פתח אליהו."],["1228","49","<b>דינא דמלכותא</b>: גיטין י, ב, ובכ\"מ."]]],[2101000203,"פוגם ג\"כ כמו בפוגם ע\"י ל\"ת, כמו שנאמ' בק\"ש שעל המטה אם פגמתי באות יו\"ד כו', שהרי במניעו' האור חדש נקרא פגם וחסרון ביותר מפגם וחסרון האור שכבר נמשך בכלים מכבר בנפש ע\"פ מאמר קו המדה ע\"י העונות וחטאים דל\"ת, ואם בפגם וחסרון דל\"ת יש ד' מיתו' ב\"ד סקילה לתקן הפגם באות יו\"ד, ושריפה כנגד הה\"א כו', מכ\"ש במניעו' מ\"ע ולכך ע\"י מניעו' מ\"ע מכין<sup data-n=\"1229\">50</sup> אותו עד שתצא נפשו כו' וד\"ל.\n<b>ובכ\"ז</b> יובן מ\"ש בתחלת הדברות אנכי<sup data-n=\"1230\">51</sup> הוי' אלקיך פי' אנכי מי שאנכי שהוא בחי' עצמו' אוא\"ס שלפני הקו\"ח באצי' כו' שנק' סובב הכללי סתימא דכל סתימין, וזהו אנכי מי שאנכי כו', אך ע\"י קבלת התורה בקיום המצות הנה בחי' אנכי זה נמשך מבחי' ההעלם לגילוי בתוס' או\"ח מרובה על המדה הראשונה להיות הוי' אלקיך פי' שם הוי' חדש והוא אלקיך מפני שנעשה ע\"י כמ\"ש ועשיתם<sup data-n=\"1231\">52</sup> אתם כו' וארז\"ל כאלו עשאוני כו', וזהו אני הוי' בכל קיום המצוה כנ\"ל וד\"ל.\n<b>ובכ\"ז</b> יובן ג\"כ הטעם הקולו' והברקי' שבמ\"ת כמ\"ש ויהי<sup data-n=\"1232\">53</sup> קולות וברקים כו' ויחרד כל העם אשר במחנה כו', לפי שכל בחי' המשכו' תוס' או\"ח כנ\"ל א\"א שיומשך בלתי ההעלאה בתחלה מלמטה למעלה כמאמר רוח אייתי רוח<sup data-n=\"1233\">54</sup> כו' כידוע וכמארז\"ל דאין<sup data-n=\"1234\">55</sup> טיפה יורדת מלמעלה שאין טיפיים עולים כנגדה כו', ובהיו' שבחי' המשכות תוס' אור הנ\"ל הנה הוא בא ממקום ומדרגה היותר עליון מכל ההשתלשלו' שנמשך בק\"ה באבי\"ע כנ\"ל ע\"כ הוצרך להיו' תחלה ביטול הנ\"ל לאין למטה בתכלית הביטול והוא בחי' החרדה עד שעכ\"ד<sup data-n=\"1235\">56</sup> פרחה נשמתן כו', ולזה הי' ענין קולו' וברקי' להחריד את העם להביאם לבחי' ביטול אמיתי בכדי שיאיר עליהם אח\"כ בחי' אנכי מי שאנכי כו' וד\"ל.\n<b>וזהו</b> שרש ענין קבלת התורה דהנה שרש בחי' היחודים שנעשה ע\"י המצות הוא בחי' תוס' או\"ח מעצמו' המאציל שלמעלה ממדרגת מסדר ההשתלשלות כנ\"ל והיינו פי' יחוד דאור א\"ס עצמו בעולמות למהוי א' הפשוט באחד דע\"ס כו', אך הנה זה הכח להיו' בחי' המשכות תוס' או\"ח הזה ע\"י קיום התורה או המצוה למטה הנה כח זה ניתנה לנו במעמד ה\"ס, שהרי גוי שעושה מצוה אין המצוה כלום, שהרי לא נמשך ע\"י מצות לבישת טלית שהגוי לובשו או ע\"י עסקו בתורה שום בחי' המשכה למעלה רק ע\"י ישראל דווקא כידוע, לפי שזה הכח ניתנה להם במ\"ת, וזהו עיקר ענין קבלת התורה וד\"ל, והנה המלאכים בקשו ג\"כ את התורה כמ\"ש תנה הודך על",[["1229","50","<b>מכין אותו עד שתצא נפשו</b>: כתובות פו, א."],["1230","51","<b>אנכי ה' אלקיך פי' אנכי מי שאנכי</b>: שמות כ, ב. וראה לקו\"ת פינחס פ, ב. זח\"א קסז, ב. זח\"ג רנז, ב."],["1231","52","<b>ועשיתם אתם וארז\"ל כאילו עשאוני</b>: זח\"ג קיג, א. וראה ויק\"ר פל\"ה, ז."],["1232","53","<b>ויהי קולות וברקים</b>: שמות יט, טז."],["1233","54","<b>רוח אייתי רוח</b>: זח\"ב קסב, ב. וראה אוה\"ת בראשית רפו, א."],["1234","55","<b>דאין טפה יורדת מלמעלה</b>: ראה זח\"ג רמו, ב. תענית כה, ב. ב\"ר פי\"ג, יג."],["1235","56","<b>שעכ\"ד פרחה נשמתן</b>: שבת פח, ב."]]],[2101000204,"השמים כו' ולא ניתנה להם מפני ששרש המלאכים מבחי' הדיבור שהוא בחי' עלמא דאתגלי', אבל לישראל ניתנה לפי שעלו במחשבה כנ\"ל.\n<b>וביאור</b> הדברים הנה מבואר בע\"ח שבבחי' אורו' וכלי' דאצי' יש בכלים ב' מדרגו' בחי' פנימי' הכלים ובחי' חיצוני' הכלים, ושרש נש\"י מבחי' פנימי' הכלי', ושרש המלאכים מבחי' חיצוני' הכלים, ומ\"ש<sup data-n=\"1236\">57</sup> בזהר דאיהו וגרמוהי חד קאי על בחי' פנימי' הכלי' ולא על בחי' חיצוני' הכלי', והיינו על שרש נש\"י שעלו במחשבה שהוא בחי' פנימי' הכלים ולא על בחי' הדיבור שהוא בחי' חיצוני' הכלי', לפי שהמחשבה מתאחדת מאד באור השכל והמדו' שבלב שהרי היא תמידו' בלי רצון האדם ג\"כ להיותה מתאחדת עם השכל והמדות ואינה מהות דבר בפ\"ע כלל, וע\"כ המחשבה משוטטת תמיד, וכמ\"ש<sup data-n=\"1237\">58</sup> ונהר יוצא מעדן יוצא תמיד כנהר זה שנמשך בתמידו' כו', אבל הדיבור תלוי ברצון האדם שברצותו יפסיק הדיבור, הרי יש שליטה בשכל על הדיבור שלא ידבר כשאינו רוצה אבל אין למוח שליטה על המחשבה שלא יחשוב מה שאינו רוצה אלא בהכרח תשוטט מחשבתו תמיד כידוע, והיינו לפי שהמחשבה הוא עצם א' עם השכל לכך אין לו שליטה עליה כמו שלא יוכל לשלוט בעין הפתוח שלא יביט בה כו' וכיוצא בו, משא\"כ כח בחי' הדיבור שהוא כח נבדל מעצם השכל שבמוח ע\"כ יש שליטה למוח ורצון להעמיד א\"ע מלדבר כמו שיש שליטה למוח על האברים החיצוני' כמו ברגלי' שלא ילך וכיוצא כו' וד\"ל.\n<b>וזהו</b> משל להבין ההפרש בין נשמות למלאכים, דהנה שרש המלאכים נמשך רק מבחי' האותיו' הדיבור העליון כמ\"ש וברוח<sup data-n=\"1238\">59</sup> פיו כל צבאם כו' והוא הנק' בחי' חיצוני' הכלי' שהן בבחי' פירוד קצת מעצם האורות דאצי' כמשל הדיבור כנ\"ל, וע\"כ הגם שיש למלאכים מס\"נ אינו נמשך מבחי' סובב הכללי הנ\"ל בחי' או\"ח הנ\"ל עי\"ז, רק דוקא ע\"י נש\"י שעלו במחשבה שנק' פנימי' הכלי', שע\"ז אמרו דאיהו וגרמוהי חד, כמשל המחשבה שמתאחדת בשכל עד שאין שליטה עליה כנ\"ל, ע\"כ במס\"נ דישראל דוקא נמשך בחי' סובב הכללי כנ\"ל, ולכך לא ניתנה התורה למלאכי' אלא לישראל דווקא משום דעל שרש נשמתם אמר דאיהו וגרמוהי חד להיותם מבחי' המחשבה נק' פנימי' הכלי' כו' וד\"ל.\n<b>ומעתה</b> יש להבין ההפרש בין איהו וחיוהי חד לאיהו וגרמוהי חד כנ\"ל, דהנה בחי' חיוהי הוא בחי' חב\"ד דאצי' דהנה בחי' עצמיו' אוא\"ס הוא למעלה לגמרי מבחי' השתלשלות אפי' מהיות מקור דמקור להתהוות ע\"ס דאצי' וגם התלבשותו בבחי' חכמ' להיותו נק' חכי' כו' אין זה אלא מצד בחי' הכלי' ולא מצד בחי' האורו' כמ\"ש<sup data-n=\"1239\">60</sup> בזהר עבד מאני רברבא וקארי בה גרמי' חכים כו' דהיינו רק מצד בחי' הכלים וד\"ל.",[["1236","57","<b>ומ\"ש בזהר דאיהו וגרמוהי חד</b>: ת\"ז בהקדמה לפני ד\"ה קום יחזקאל."],["1237","58","<b>וכמ\"ש ונהר יוצא מעדן</b>: בראשית ב, י. וראה זח\"ב קכג, ב. ובכ\"מ."],["1238","59","<b>וברוח פיו כל צבאם</b>: תהלים לג, ו."],["1239","60","<b>כמ\"ש בזוהר עבד מאני רברבא</b>: ראה זח\"ב מב, ב."]]],[2101000205,"<b>וביאור</b> הדברים ידוע עד\"מ כח השכל שבכלי המוח, הרי אין האדם נק' חכם אלא כשמשכיל ומתבונן איזה שכל וסברא בכלי מוח תבונתו, אבל מצד בחי' אור כח השכל הרי מתאחד הוא בעצם הנפש ונק' נפש המשכלת שהשכל כלול בה ומתאחד עמה בתכלי' כו', וכך למעלה הרי אמר חכים<sup data-n=\"1240\">61</sup> ולא בחכמה ידיעא כלל כו' משום דהוא<sup data-n=\"1241\">62</sup> המדע והוא היודע כו' והוא מצד בחי' אור החכמה שכלולה ומתאחדת בעצמו' אוא\"ס, ומ\"ש אנת חכים כו' היינו בהתלבשותו בבחי' כלי כו', וזהו פי' דאיהו וחיוהי חד דהיינו בחי' האורו' דאצי' שמתייחדי' בעצמו' המאציל כנ\"ל בחכמה וד\"ל, אבל איהו וגרמוהי חד קאי בבחי' הכלים דאצי' כמו כלי החכמה שהוא בחי' המחשבה שבכלי המוח דאע\"פ שמתאחדים ג\"כ בשכל כנראה בחוש אבל אין זה היחוד אמיתי כמו ביחוד כח השכל שבעצם הנפש, כי אין המחשבה מתיחדת רק בשכל הנגלה ולא בשכל הנעלם מן הרעיון הכלול בעצם הנפש, וגם יחוד המחשבה בשכל הנגלה ג\"כ אינה בחי' התאחדות גמורה כמו התאחדות והתכללות כח השכל בעצם הנפש כשנק' נפש המשכלת, שהרי בהתגלו' השכל במחשבה בכלי המוח הרי ניכרין אותיו' המחשבה במהות דבר בפ\"ע חוץ מן השכל עצמו (ואפי' מחשבת שכל שבלא אותיו' עדיין הרי גם טרדת עיון המחשבה בשכל נחלקת לדבר בפ\"ע מובדל מעיקר המושכל, שהרי מושכל א' יתלבש בעיון טרדת המחשבה בכמה אופנים שונים כו' וד\"ל).\n<b>וזהו</b> עיקר ההפרש בין בחי' איהו וחיוהי חד לבחי' איהו וגרמוהי חד למעלה, ונמצא שעלו<sup data-n=\"1242\">63</sup> ישראל במחשבה שהוא בחי' כלי' דחב\"ד מבחי' פנימי' הכלים כנ\"ל ע\"ז אמר דאיהו וגרמוהי חד, כמו התאחדו' המחשבה בשכל עד שאין למוח שליטה עליו כלל כנ\"ל, אבל מ\"מ אין לזה ערך מבחי' היחוד דאיהו וחיוהי חד שהוא כמו בחי' יחוד דחכמה בעצמו' המאציל כנ\"ל, וא\"כ לכאורה יש להקשו' איך זכו ישראל לקבל' התורה שהוא להיות כח המשכת תוס' או\"ח תמיד מעצמיו' המאציל בע\"ס באורו' וכלי' כנ\"ל ע\"י קיום המצות למטה כו' כנ\"ל, אחר שאין שרש נש\"י למעלה רק בבחי' המחשבה שנק' גרמוהי, ואיך יוכל ליחד יחוד עליון הרבה ממנו להיו' איהו וחיוהי חד דהיינו בבחי' תוס' או\"ח (תמיד מעצמיו' המאציל בע\"ס באורו' וכלים) בחכמה וכיוצא כנ\"ל, מפני שבמ\"ת נתגלה מבחי' אנכי שהוא בחי' סובב הכללי כו' כנ\"ל. אך הענין דבאמת מצד שרש נש\"י במחשבה עילאה דחכמ' לא היו יכולי' לבוא למדרגת קבלת התורה הנ\"ל אלא מצד התלבשו' הנשמה בגוף שהוא נפש החיונית דנוגה, לפי שירידה צורך עלי' היא להיו' עולה מבחי' גרמוהי לבחי' חיוהי כו'.\n<b>וביאור</b> הדברים הנה תחלה יש להקדים בשרש נפשות החיוני' הבהמית דנוגה דהנה ידוע דשרש נפש הבהמי' למטה נמשך מבחי' מרכבה העליונה דפני",[["1240","61","<b>חכים ולא בחכמה ידיעא</b>: ת\"ז בהקדמה ד\"ה פתח אליהו."],["1241","62","<b>דהוא המדע והוא היודע</b>: רמב\"ם הל' יסוה\"ת פ\"ב ה\"י. מו\"נ ח\"א פס\"ח. שמונה פרקים פ\"ח. וראה תניא פ\"ב ובליקוט פירושים ומ\"מ שם."],["1242","63","<b>שעלו ישראל במח'</b>: ב\"ר בתחילתו. ובכ\"מ."]]],[2101000206,"שור כו', והנה בחי' מרכבה דפני<sup data-n=\"1243\">64</sup> ארי' להימין ופני שור כו' הם חיות<sup data-n=\"1244\">65</sup> הקדש הנושאות את הכסא שנק' כסא הכבוד וכתי' ועל<sup data-n=\"1245\">66</sup> הכסא דמות כמראה אדם כו' והוא בחי' אדם תתאה שהוא בחי' מל' דאצי' והכסא הוא בחי' כחב\"ד דבריאה ושש מעלו' לכסא הן בחי' ו\"ק דבריאה כו' וכמ\"ש וישב<sup data-n=\"1246\">67</sup> ה' מלך לעולם והיינו שנאמ' בשלמה וישב<sup data-n=\"1247\">68</sup> שלמה על כסא ה' כו' והחיות הנושאות את הכסא הוא בחי' המרכבה דפני ארי' כו', וענין נושאות את הכסא היינו שמעלין ומגביהין לבחי' אדם שעל הכסא הנ\"ל למעלה מעלה אשר לא הי' מתעלה מעצמו כ\"כ כמשל המרכבה שנושא את הרוכב כו' כידוע, וזהו שאנו אומרי' רוממי<sup data-n=\"1248\">69</sup> שדי כו', והטעם שיש בכח נבראי' בע\"ג להעלות לאור אלקי הנק' אדם שעל הכסא שהוא בחי' א\"ס כו', הנה ידוע לפי ששרש החיות שבמרכבה הזאת הוא מבחי' עולם התהו שלפני עולם התיקון וכמ\"ש ואלה<sup data-n=\"1249\">70</sup> המלכים אשר מלכו כו' לפני מלוך מלך כו' וכל מלוכה הוא בבחי' שם ב\"ן בגי' בהמה, וכמ\"ש<sup data-n=\"1250\">71</sup> באד\"ר בענין התהו באני עלמין ולא אתקיימו עד דאתברי פרצופא דאדם כו', וכמ\"ש בע\"ח דבחי' הכלים דתהו נפלו בעולם הבריאה כו', ומזה נמשך שרש החיות שבמרכבה פני ארי' פני שור כו' וע\"כ יש בכח החיות הללו להעלות לבחי' אדם דתיקון כו'.\n<b>וביאור</b> דבר זה ידוע עד\"מ ממה שאנו רואים שהמאכל שהוא בחי' צומח יחי' את האדם שהוא בחי' מדבר שלמעלה הימנו, וכן בשר החי' כמ\"ש<sup data-n=\"1251\">72</sup> ר\"נ עד דלא אכילנא בשרא דתורא כו' או כמ\"ש<sup data-n=\"1252\">73</sup> רבא חמרא וריחא פקחין כו' שהוא מפני ששרש המאכל והחי' גבוהין מן האדם, לפי ששרשן בבחי' התהו שקדם לבחי' התיקון שהוא בחי' פרצופא דאדם כנ\"ל, וז\"ש אחור וקדם צרתני אחור<sup data-n=\"1253\">74</sup> למע\"ב דאפי'<sup data-n=\"1254\">75</sup> יתוש קדמך כו' וכמ\"ש במ\"א ביאור זה באריכות וד\"ל.\n<b>והנה</b> כמו שמטעם זה יש ביכולת החיות שבמרכבה לנשאות ולהעלו' לבחי' אדם תתאה שעל הכסא שהוא בחי' מל' דאצי' כנ\"ל, כך מטעם זה אמרו האבות<sup data-n=\"1255\">76</sup> הן הן המרכבה באצי' עצמו דידוע ששרש האבות למעלה הוא בבחי' כלים באורות דמדות חג\"ת דז\"א דאצי' שנק' אדם עליון שעל הכסא כו' והאבות הן בחי' מרכבה",[["1243","64","<b>דפני ארי' להימין</b>: יחזקאל א, י."],["1244","65","<b>חיות הקודש הנושאות את הכסא</b>: ראה בחיי תרומה כה, י בשם פדר\"א. וראה פדר\"א ספ\"ד. שמו\"ר ספכ\"ג."],["1245","66","<b>ועל הכסא דמות כמראה אדם</b>: ראה יחזקאל א, כו."],["1246","67","<b>וישב ה' מלך לעולם</b>: תהלים כט, י."],["1247","68","<b>וישב שלמה על כסא ה'</b>: דה\"א כט, כג."],["1248","69","<b>רוממי שדי</b>: נוסח ברכת יוצר."],["1249","70","<b>ואלה המלכים אשך מלכו</b>: בראשית לו, לא. דה\"א א, מג."],["1250","71","<b>וכמ\"ש באד\"ר. . באני עלמין ולא אתקיימו</b>: ראה זח\"ג קמב, א."],["1251","72","<b>כמ\"ש ר\"נ עד דלא אכילנא בישרא דתורא</b>: ב\"ק עב, ב."],["1252","73","<b>כמ\"ש רבא חמרא וריחא פקחין</b>: יומא עו, ב. ובכ\"מ."],["1253","74","<b>אחור וקדם צרתני אחור למע\"ב</b>: תהלים קלט, ה. ויק\"ר פי\"ד, א. וראה לקו\"ת ר\"פ מטות. סה\"מ תקס\"ד ע' קפח. דרך חיים ע' 178. תו\"ח בראשית יט, ב. ובכ\"מ."],["1254","75","<b>דאפי' יתוש קדמך</b>: ויק\"ר שם. וראה סנהדרין לח, א."],["1255","76","<b>האבות הן הן המרכבה</b>: ב\"ר פמ\"ז, ו. ובכ\"מ."]]],[2101000207,"ג\"'כ להעלות לבחי' אדם העליון דאצי' שהוא בחי' ו\"ק דז\"א כו' כמשל המרכבה שנשא את הרוכב (וכמבואר למעלה בבחי' מרכבה תתאה דפני ארי' כו') כי בחי' ו\"ק דז\"א נק' אדם מפני שהאורו' באין בריבוי כלים שהן בחי' רמ\"ח אברין דמלכא שהן שרש הרמ\"ח מ\"ע למטה כידוע וכמ\"ש<sup data-n=\"1256\">77</sup> בע\"ח בטעם מספר רמ\"ח דווקא, לפי שבחי' ז\"א עצמו בעל ט\"ס וטפ\"ט עולה פ\"א וג' מיני כלים, פנימי ואמצעי וחיצון רת\"ס, ג\"פ פ\"א עולה רמ\"ג ועם ה\"ח המגדילי' עולה רמ\"ח, וכמבואר דבר זה במ\"א באריכות וד\"ל, ובחי' העלאת אדם זה היינו כמ\"ש לך<sup data-n=\"1257\">78</sup> הוי' הגדולה והגבו' כו' דהיינו שבחי' המדות דז\"א עולין למעלה מבחי' אדם דהיינו לבחי' עתיקא שהוא בחי' אור הכתר ששם נאמר כי<sup data-n=\"1258\">79</sup> לא אדם הוא להנחם (כמ\"ש בסמוך), והנה הגם ששרש נשמות האבות הוא מבחי' המחשבה שנק' גרמוהי כנ\"ל עכ\"ז לא הי' ביכולתו להעלות לבחי' ו\"ק דז\"א בעתיקא אלא רק מצד התלבשו' נשמתם בגופים דווקא ובהיותם בגופים היו בחי' מרכבה לבחי' המדו' דאצי' דהיינו בחי' דו\"ר טבעיים שמצד נפש החומריי' דנוגה ששרשה מבחי' בהמה רבה דתהו שלפני התיקון כנ\"ל.\n<b>וביאור</b> הדבר הנה ידוע שיש ב' מיני מדות אהוי\"ר, הא' אשר נולדי' ולקוחים רק מן השכל ובהבטל הטעם והשכל יתבטל התפעלו' האהבה או היראה ובתפלה נק' זה דו\"ר שכליי', והב' בחי' מדו' אהוי\"ר טבעיים שלא נלקחו מצד השכל שבנפש האלקי' אלא כמו טבע מוטבעין הן בנפש כמו טבע המדו' הגשמיו' המוטבעין בנפש הבהמית שהן כמו מדת הבהמה ממש שהן חזקי' ותקיפי' ביותר עד שלא תבטל לעולם, גם שיהי' השכל מנגד לה, כי כח המדו' הטבעיי' חזקי' יותר מכח השכל, מפני שזה הכח החזק ביותר שבמדו' הטבעיי' הנק' אהבה טבעי' כו' שרשה בבחי' המדות שברצון שלמעלה מן כח השכל אהבה רבה כמ\"ש במ\"א באריכות בפי' אשר נשבעת לאבותינו חג\"ת דז\"א מימי קדם דע\"י כו', והיינו מ\"ש באד\"ר<sup data-n=\"1259\">80</sup> דז\"א בעתיקא עצמו אחיד ותלי', משא\"כ או\"א במו\"ס אחיד כו', דהיינו דווקא מבחי' מדו' הטבעיי' דז\"א כו' שחזקי' ותקיפי' ביותר מכח השכל לפי ששרשם בע\"י עצמו שהוא בחי' הכתר כידוע, וזהו הטעם שאמרו האבות הן הן המרכבה למעלה באצי' להעלו' לבחי' אדם שנק' ז\"א למעלה מבחי' אדם שהוא בבחי' עתיקא עצמו כנ\"ל, והוא ע\"י בחי' דו\"ר טבעי' של נשמתם בהיותם בגופים, אבל אהוי\"ר שכליי' מצד נשמתם אינם מגיעי' רק למקום שרש נשמתם שבמחשבה עילאה שאינו אלא בבחי' חו\"ב ולא למעלה יותר כמ\"ש דאו\"א במו\"ס אחיד אבל לא בעתיקא עצמו אך ע\"י מס\"נ שלהם למטה במדו' טבעיי' ששרשם בבחי' אהבה רבה שבכתר הוא שהי' בחי' מרכבה להעלות לבחי' ו\"ק דז\"א בעתיקא עצמו כו' וד\"ל.\n<b>וזהו</b> טעם ירידת הנשמה בגוף, כי ירידה זאת צורך עלי' הוא, כמו באבות שעלו עי\"ז מבחי' גרמוהי לבחי' חיוהי ולמעלה מהם, כי מצד שרש נשמתם אינן",[["1256","77","<b>וכמ\"ש בע\"ח בטעם מספר רמ\"ח דוקא</b>: שער פרקי הצלם פ\"ו. וראה לקו\"ת שה\"ש יח, א."],["1257","78","<b>לך ה' הגדולה</b>: דה\"א כט, יא."],["1258","79","<b>כי לא אדם הזא להנחם</b>: שמואל-א טו, כט."],["1259","80","<b>באד\"ר דז\"א בעתיקא עצמו אחיד ותליא</b>: זח\"ג רצב, א. וראה ג\"כ לקו\"ת ס\"פ שמיני."]]],[2101000208,"אלא בבחי' גרמוהי שהוא בחי' המחשבה כו', וע\"י מס\"נ שלהם בעוד נשמתם בגופם זכו להיו' בחי' מרכבה להעלו' לבחי' המדו' דז\"א למעלה גם מבחי' חו\"ב שנק' חיוהי כנ\"ל, והיינו להיות יחוד דאיהו וחיוהי בבחי' תוס' אור ע\"י הכתר שנק' עתיקא כידוע דבחי' הכתר הוא בחי' ממוצע בין עצמיו' המאציל לנאצלים כו' (וכמ\"כ ע\"י קיום מעשה המצות למטה להיותם מלובשים בבחי' כלים דתהו שנפלו בבי\"ע, ע\"כ ביכולתם להמשיך בחי' תוס' אור מן המאציל כנ\"ל וד\"ל) וזהו טעם ענין קבלת התורה שיכלו ישראל לקבל אע\"פ שאין שרשם אלא במחשב' בחי' גרמוהי בלבד, כי ירידת נשמתם בגופים צורך עלי' הוא להיו' עולה למעלה גם מבחי' חיוהי כנ\"ל וד\"ל.\n<b>ומעתה</b> יש להבין בענין בחי' העלאה לאדם העליון למעלה מבחי' אדם שהוא מ\"ש כי לא אדם הוא להנחם כו' כי הנה אמר באד\"ר<sup data-n=\"1260\">81</sup> דלית שמאלא בהאי עתיקא כו', וז\"ש כי לא אדם הוא להנחם כו'. וביאור הדברים הנה מ\"ש כי לא אדם הוא להנחם כו' משמע שמדרך מהות וטבע האדם להנחם אך בבחי' ע\"י נאמר כי לא אדם הוא להנחם כו' להיות כי בחי' אדם הוא בחי' התיקון דשם<sup data-n=\"1261\">82</sup> מ\"ה בגי' אדם והיינו בחי' התכללות מג' קוין חח\"ן בג\"ה דתי\"ם.\n<b>וביאור</b><sup data-n=\"1262\">83</sup> הדברים הנה ג' קוין דרך כללות הן הנה ג' מדות חסד דין רחמי' שמסתעפי' מחו\"ב, החסד ענף החכמה כו', וענפיהן של ג' מדות אלו הן מנה\"י כו' והוא בחי' הנהגת של המדות עם זולתו עד\"מ באדם שמדותיו נחלקים לג' חד\"ר, והנהגת המדות הללו עם זולתו הוא בחי' התפשטו' של המדו', והנה יש במדו' הרבה שינוים מפני בחי' התחלקות המדות לכמה מדרגו' שונות, דהיינו לפי אופן השכל, לפעמים יחייב השכל כך, יהי' המשכת המדות כך, לפ\"ז האופן דווקא, ועד\"ז יש הרבה חילוקי מדרגו' במדת החסד וכן במדת הדין ובמדה\"ר, וגם בהנהגת המדות חד\"ר עם זולתו יש בהן שינוים רבים, כמו איש חסד וטוב יתנהג במדת החסד וטוב כמים הפנים כו' ולהפך עם איש רע ובליעל יתנהג במדה\"ד כו'.\n<b>ונמצא</b> בכ\"ז יובן למעלה שבחי' התפשטו' המדו' מחד\"ר דאצי' בבריאה תלוי במעשה התחתוני' כמ\"ש עם<sup data-n=\"1263\">84</sup> חסיד תתחסד כו' וע\"כ יפול שינוים רבים בעצם המדות חב\"ד ג\"כ, הגם שהם מסתעפים ע\"פ החו\"ב כנ\"ל ולפעמים כך ולפעמים כך כו' אך ע\"י המקבלים השפע של המדות כמו עם חסיד תתחסד יפול שינוים רבים להפך המדה שכבר נמשך מן החכמה מהיפך להיפך כמ\"ש וינחם<sup data-n=\"1264\">85</sup> ה' על הרעה כו', פי' וינחם משמע שהמדה של חסד ורחמים נתעוררה עכשיו להפך",[["1260","81","<b>באד\"ר דלית שמאלא בהאי עתיקא</b>: זח\"ג קכט, א."],["1261","82","<b>דשם מ\"ה בגימ' אדם</b>: מאו\"א א, קסו."],["1262","83","<b>וביאור הדברים</b>: להבא להלן — ראה גם ד\"ה להבין שרש ענין קבלת התורה, בס' מאמרי אדהאמ\"צ הנחות תקע\"ז ע' קיד ואילך."],["1263","84","<b>עם חסיד תתחסד</b>: שמואל-ב כב, כו. תהלים יח, כו."],["1264","85","<b>וינחם ה' על הרעה</b>: שמות לב, יד."]]],[2101000209,"מדה של דין ועונש לרעה שכבר נגזר ע\"פ החכמ', כמו אדם שמתנחם מעשות רע לטוב אליו שהוא מפני שמתעורר בלבבו מדת חסד להפך מדת הדין והרוגז שנתעורר בלבבו מכבר, וזהו נק' שינוי גמור, דהיינו גם במדה שכבר נמשכה שתשתנה מהיפך להיפך, ועד\"ז יש בהיפך בשינוי מחסד לדין כמ\"ש וינחם<sup data-n=\"1265\">86</sup> ה' אשר עשה את האדם כו' ויאמר אמחה כו' (אבל מה שמדו' באין בבחי' התחלקו' רבו' לפי אופן חיוב השכל כנ\"ל אין זה נק' שינוי גמור כי לא נשתנה דבר להפוכו, רק שלפעמי' יומשך חסד ע\"פ השכל ולפעמים יומשך דין ומדה\"ד שינוי נק' לגבי החסד, אבל לא שנשתנה החסד לדין כו') ועכ\"פ מובן שיפול שינוי גמור להפך ממדה למדה היפך ע\"י שינוי מעשה התחתונים מטוב לרע או מרע לטוב, דהיינו כמו גם לאחר שכבר נמשכה מדה\"ד לעונש לחוטא תהופך לטוב וחסד אם ישוב בתשובה כו', ולהיפך גם אחר שכבר נמשך החסד לאיש החסד כמ\"ש עם חסיד תתחסד ישתנה לדין ועונש אם יחטא וכיוצא, וא\"כ תמיד ימצא שינויי' במדות עליוני', וז\"ש בבחי' כ\"ע כי לא נק' אדם הוא להנחם, פי' לא כמו בחי' המדו' דז\"א שנחלקו בג' קוין שהוא נק' אדם להנחם ולהשתנות תמיד מחסד לדין או להיפך כנ\"ל אם לפי אופן השכל שיחייב לפעמים כך ולפעמים להיפך, או לפי אופן מעשה התחתוני' שעושין שינוי גמור להנחם עצם המדה להופכה לשנותה (כמו יה\"ר<sup data-n=\"1266\">87</sup> מלפניך שיכבשו רחמך את כעסך כו' שהכעס עצמו משתנה ומתהפך לטוב מפני תגבורת הרחמי' כמו אב על בנו גם בהיותו כועס עליו מאד שיתבונן ברחמנותו עליו מהפך לבבו מרע לטוב, וכמ\"ש במ\"א בענין והפכתי<sup data-n=\"1267\">88</sup> אבלם לששון כו' דמזה הטעם בחי' הגבו' גבוהי' לעתיד מבחי' החסדי' כו') אבל בבחי' כ\"ע שנק' עתיקא לא אדם הוא להנחם, לפי שבחי' הכתר הוא למעלה מבחי' החכמה כידוע שהוא בחי' הרצון הפשוט אשר בלתי מתחלק כלל למדרגו' שונו' כי כל בחי' התחלקו' אינו בא רק מבחי' החכמה ולמטה דהיינו מה שהשכל יחייב טעם לרצון כך או כך, אבל בעצם הרצון הרי אין טעם לרצון כלל כידוע (אפי' טעם כמוס שנק' ח\"ס אין בעצם הרצון הנק' כתר שבכתר והוא בחי' ע\"י שמאיר בגולגלתא דא\"א כו' כידוע) וא\"כ לא יפול שינוי לעולם בבחי' עתיקא שיהי' לפעמים כך ולפעמים להיפך לא מצד עצמו ולא מצד מעשה התחתוני' מאחר שהוא עצם אור א' פשוט בתכלית בלתי מתחלק למדרגו' חלוקו' כלל (ועד\"מ עצם נקודת הרצון באדם שנק' יחידה אינה מתחלק להיות שינוי אופנים כך ולא כך, מפני שלא ישתנה בחי' העצמיו' כלל וכמ\"ש במ\"א בענין נעשה ונשמע כו') וז\"ש באד\"ר דלית שמאלא בהאי עתיקא פי' שמאלא הוא בחי' הדין שהוא בחי' שינוי למדת החסד ובבחי' ע\"י אין בו שינוי כלל, ועצמו' המאציל חפץ חסד הוא מצד עצמותו כי<sup data-n=\"1268\">89</sup> טוב ה' כו' וטבע הטוב להיטב ובהאי עתיקא לית שמאלא להפך זה החסד, לפי שאין שם בחי' שינוים כלל ע\"כ ממילא כולו חסדי' וכמ\"ש<sup data-n=\"1269\">90</sup> בפרד\"ס דאור הכתר כולו רחמים פשוטים כו', וז\"ש בו כי לא אדם הוא להנחם בשינוים כלל,",[["1265","86","<b>וינחם ה' אשר עשה את האדם</b>: בראשית ו, ו."],["1266","87","<b>יה\"ר מלפניך שיכבשו רחמך</b>: ברכות ז, א."],["1267","88","<b>והפכתי אבלם לששון</b>: ירמי' לא, יג."],["1268","89","<b>כי טוב ה'</b>: תהלים לד, ט."],["1269","90","<b>וכמ\"ש בפרדס דאור הכתר כולו רחמים</b>: ראה ג\"כ ביאוה\"ז להצ\"צ כרך ב' ע' תשכ."]]],[2101000210,"וזהו ענין בחי' העלאה לאדם העליון שעל הכסא להיות עולה בעתיקא שלמעלה מבחי' אדם משום דז\"א בעתיק' עצמו אחיד ותלי', לפי שהאבות הן המרכבה במדו' טבעיים כו' כנ\"ל וד\"ל.\n<b>ובכ\"ז</b> יובן מ\"ש שמואל לשאול פסוק זה וגם<sup data-n=\"1270\">91</sup> נצח ישראל לא ישקר ולא ינחם כי לא אדם הוא להנחם, דהנה לכאורה לא יש שייכות כלל לענין הסרת ממלכת שאול ליתן טעם ע\"ז מפני שלא אדם הוא להנחם אחר שכבר נגזר עליו דלכאורה אדרבא הרי בשאול נאמר נחמתי<sup data-n=\"1271\">92</sup> כי המלכתי את שאול כו' ומשמע דחפץ בו בתחלה שהרי נק' בחיר ה' כמ\"ש הראיתם<sup data-n=\"1272\">93</sup> אשר בחר בו ה' כו' רק שחזר בו וניחם על אשר בחר בו כו' וא\"כ הרי יוכל להיות חזרה להיפך שיחזור וירצה בו וינחם על אשר מאס בו אחר שזהו בבחי' המדות העליונות העשויות להשתנות כמ\"ש נחמתי כו' וא\"כ איך אמר טעם להיפך כי לא אדם הוא כו'. אך הענין הוא דאדרבא מ\"ש וגם נצח ישראל כו' בא ליתן טעם על ממלכת דוד שכבר ניתנה לו וא\"א שיחזור בו כי לא אדם הוא להנחם לפי ששאול ביקש שינחם ה' ויעורר חסדו עליו להשיב לו את המלוכה והשיב לו שמואל שדבר זה א\"א לא מטעם שא\"א להנחם מדין לחסד שהרי נאמר וינחם<sup data-n=\"1273\">94</sup> ה' על הרעה כו' וכן ויאמר<sup data-n=\"1274\">95</sup> ה' לא אוסיף עוד לקלל כו' אך מטעם בחי' ממלכת דוד שא\"א להנחם עלי' לאחר שכבר ניתנה לו וע\"ז קאמר וגם נצח ישראל לא ישקר כו' כי לא אדם הוא להנחם כו'.\n<b>וי\"ל</b> למה דוקא על ממלכת דוד אמר שלא יוכל להנחם כי לא אדם הוא כו' ולא בשאר דבר זולתו. אך הנה הענין הוא דזהו ההפרש בין שרש ממלכת שאול לשרש ממלכת דוד דשרש מלכות שאול שנמשח<sup data-n=\"1275\">96</sup> בפך הוא נמשך מבחי' המדות העליונות דז\"א דאצי' שנק' אדם ושרש המשכת מלכות דוד שנמשח<sup data-n=\"1276\">97</sup> בקרן נמשך מבחי' הכתר עליון שלמעלה מבחי' אדם שע\"ז נאמר כי לא אדם הוא להנחם כנ\"ל. וביאור הדברים הנה מלכות שאול נבחרה למעלה מפני בחי' טעם וחכ' המלובש ברצון שבמדות כמ\"ש שמואל הראיתם אשר בחר בו ה' כי אין כמוהו בכל העם שאין כמוהו בישראל ביראה וחכמה וכדומה כמ\"ש בשאול משכמו<sup data-n=\"1277\">98</sup> ומעלה גבוה מכל העם כו' כלומר שגבוה במעלה מכל ישראל וע\"כ בחר בו ה' דהיינו רק בבחירה ורצון שבמדות עפ\"י השכל והטעם כנ\"ל שעפ\"י אופן השכל יהי' אופן המדות לפעמים כך כו' ואם יחייב השכל אח\"כ יהי' המשכת המדה להיפוך כמו וינחם אשר עשה את האדם ולהיפוך מרע לטוב וינחם ה' על הרעה כו' ושינוי חיוב השכל והחכ' תלוי עפ\"י שינוי מעשה התחתונים למטה שיהפכו גם המידה שכבר נמשכה מן השכל אם מחסד לדין או מדין לחסד כנ\"ל באריכות, וגם כאן במלכות שאול שנק'",[["1270","91","<b>וגם נצח ישראל לא ישקר</b>: שמואל-א טו, כט."],["1271","92","<b>נחמתי כי המלכתי את שאול</b>: שם טו, י."],["1272","93","<b>הראיתם אשר בחר בו ה'</b>: שם י, כד."],["1273","94","<b>וינחם ה' על הרעה</b>: שמות לב, יד."],["1274","95","<b>ויאמר ה' לא אוסיף עוד לקלל</b>: ראה בראשית ח, כא."],["1275","96","<b>שנמשח בפך</b>: ראה שמואל-א י, א."],["1276","97","<b>שנמשח בקרן</b>: שם טז, יג."],["1277","98","<b>משכמו ומעלה גבוה מכל העם</b>: שם ט, ב."]]],[2101000211,"בחיר ה' מאחר שבחר בו ורצה בו עפ\"י חיוב החכמה המלובש במדות דז\"א כמו מטעם צדקתו וכדומה הנה בחירה ורצון זה שבמדות שבלב עליון עשוי' להשתנות עפ\"י טעם ושכל אחר שיחייב אח\"כ היפכו כמו ויתעצב<sup data-n=\"1278\">99</sup> אל לבו ויאמר אמחה את האדם כו' כי ניחם על רצונו הקדום מפני כי רבה רעת האדם וכיוצא וגם כאן נשתנה רצון של חסד ואהבה שהי' לו על מלכות שאול ואמר נחמתי כי המלכתי את שאול כו' מטעם שלא הקים דבר ה' במלחמת עמלק כמבואר בכתוב כי טעם זה סתר למדת החסד להיות מתהפבת למדה\"ד מפני מעשיו אשר לא טוב הי' לפני ה' מאחר שכל שרש המשכת מלכותו לא נמשך רק מבחי' המדות שנק' אדם דאצי' ודרך בחי' אדם דאצי' להיות משתנה תמיד כמשמעות מ\"ש כי לא אדם הוא להנחם דמשמע שדרכו של אדם דוקא להנחם תמיד ממדה למדה היפכה כנ\"ל ע\"כ כשחטא שאול חטא אחד העבירו ממנו המלוכה מיד וכמארז\"ל שאול<sup data-n=\"1279\">100</sup> באחת ועלתה לו כו'.\n<b>אבל</b> שרש בחי' מל' דוד הוא למעלה מבחי' אדם וע\"כ אמרו דדוד בשתים ולא עלתה לו כו' לפי שא\"א להעביר ממנו המלוכה אעפ\"י שחטא הרבה פעמים משום דלא אדם הוא להנחם כו' והענין הוא כי שרש המשכות מל' דוד נמשכה מבחי' עתיקא שנאמר בו כי לא אדם הוא להנחם פי' כנ\"ל שאין שם בחי' שינויים כלל כי הוא בבחי' רצה\"פ שבפנימי' הכתר שלמעלה מבחי' התלבשו' עדיין בחו\"ב כו' ולכך אין בו בחי' התחלקות מדריגות כלל כי אין טעם לרצה\"פ כלל (אפי' טעם כמוס דבחי' ח\"ס כו') וא\"כ כאשר עלה ברצה\"פ למלכות דוד הי' למעלה מן הטעם והחכ' אלא רק רצון עצמי פשוט כו' שאין בו שינויים לעולם וז\"ש כי לא אדם הוא להנחם ולהשתנות כנ\"ל בפי' דלית שמאלא בהאי עתיקא כו' וע\"כ הגם שחטא הרבה פעמים הרי אין זה עושה שינוי ופגם רק בבחי' החכ' שבמדות להיות משתנה עי\"ז מחסד לדין אבל למעלה מבחי' החכ' שבמדות שנק' אדם אין זה עושה בחי' שינוי ופגם כלל כי שם הוא למעלה מבחי' התחלקות המדות שבאין בבחי' השתלשלו' למטה לפי ערך מעשה התחתוני' בשינויי' רבים אבל שם נאמר אם<sup data-n=\"1280\">101</sup> צדקת מה תתן לו כו' כי מעשה התחתוני' אין מגיע לשם כלל לפי שהוא מתנשא מימות עולם ורם ונשגב לבדו בבחי' אחדות הפשוטה דעצמות אא\"ס כידוע דבחי' ע\"י נחשב מסוף עולם הא\"ס כו' ולכך אמרו דדוד בשתים ולא עלתה לו כי לא נמשך שרש מלכותו מצד הטעם כמו מטעם צדקתו וכדומה שיבוטל מלכותו כשיבוטל הטעם כנ\"ל בשאול אלא שרש מלכותו מבחי' פנימי' כתר עליון שלמעלה מן הטעם וע\"כ אין שם שינויים כלל כנ\"ל וד\"ל.\n<b>אך</b> היא גופא י\"ל למה שרש מלכות דוד נמשכה מבחי' מדריגה עליונה כזאת דהיינו מבחי' פנימי' הכתר ששם שורה בחי' מל' דא\"ס כידוע, הענין הוא לפי<sup data-n=\"1281\">102</sup> שאמר בס\"י דנעוץ תחב\"ס וסוב\"ת דוקא כי סוף מעשה עלה במח\"ת (וכידוע המשל",[["1278","99","<b>ויתעצב אל לבו</b>: בראשית ו, ו."],["1279","100","<b>שאול באחת ועלתה לו</b>: יומא כב, ב."],["1280","101","<b>אם צדקת מה תתן לו</b>: איוב לה, ז."],["1281","102","<b>לפי שאמר בס\"י דנעוץ תחלתן בסופן</b>: פ\"א מ\"ז."]]],[2101000212,"בזה כאשר יעלה ברצון לבנות בית שתחלת עליית הרצון הוא רק בשביל סוף מעשה בלבד וא\"כ זהו בהכרח שעלה סוף מעשה דוקא בתחלת המח' שנק' רצו\"פ כו') וידוע דשרש בחי' מל' דוד למטה הוא בחי' מל' דאצי' למעלה שנק' סופא דכל דרגין ונעוץ בה מבחי' תחלתן שהוא בחי' פנימי' הכתר וכידוע בציור הג' קוין דהמל' עומדת בסיום הכתר והרי מלמטה למעלה המל' נק' כתר וע\"כ נק' המל' בשם כתר מל' כמ\"ש במ\"א באריכות ולהיות כן שרש המשכת מל' דוד נמשך דוקא מבחי' פנימי' ע\"י שעליו נאמר כי לא אדם הוא להנחם כי נעוץ תחב\"ס דוקא וע\"כ אנו אומרי' דוד<sup data-n=\"1282\">103</sup> מ\"י חי וקיים וכמשמעות הכתובי' שמל' דוד קיימת לעולם משיח בן דוד הוא כידוע וכמ\"ש בנבואת נתן לדוד על שלמה בנו וכוננתי<sup data-n=\"1283\">104</sup> את כסא ממלכתו עד עולם וחסדי לא יסור ממנו כאשר הסירותי מעם שאול כו' ונאמן ביתך וממלכתך עד עולם לפניך כסאך יהי' נכון עד עולם כו' (והרי במלכות משיח נאמר ונחה<sup data-n=\"1284\">105</sup> עליו רוח ה' כו' והריחו ביראת ה' כו' וארז\"ל דמורח<sup data-n=\"1285\">106</sup> ודאין שהוא מבחי' הוד דע\"י כמ\"ש במ\"א) וכ\"ז מפני שנמשח דוד בקרן ולא בפך, כי שרש בחי' קרן הוא בבחי' כתר כמ\"ש חנה רמה<sup data-n=\"1286\">107</sup> קרני בה' פי' רמה בבחי' הרוממות דפנימי' כתר עליון שמרומם לבדו ומתנשא מימות עולם שהן בחי' ז\"ת דא\"א שמתלבשי' בנאצלי' כו' ושם נאמר רמה קרני בה' וכן כתיב ותרם<sup data-n=\"1287\">108</sup> כראם קרני כו' כי הקרן מורה על בחי' הרוממות דוקא כמו וירם<sup data-n=\"1288\">109</sup> קרן לעמו כו' וכן אמר דוד ע\"ע נאום<sup data-n=\"1289\">110</sup> הגבר הקים עול כו' (ובכ\"ז מובן מ\"ש ה' לשמואל על דוד כי<sup data-n=\"1290\">111</sup> ראיתי בבניו לי מלך לפי שנעוץ סוב\"ת וע\"כ מלכותי' מל' עלם כו' כמו שמל' דא\"ס שיהי' לעתיד כמ\"ש ה'<sup data-n=\"1291\">112</sup> ימלוך לע\"ו וכמ\"ש<sup data-n=\"1292\">113</sup> בדניאל לפי שבחי' נצחיות דא\"ס מאיר בו לפי שנעוץ תחב\"ס דהיינו בחי' מל' דא\"ס במל' דאצי' שרש מל' דוד וז\"ש לי מלך לי דוקא וד\"ל) אבל מלכות שאול ששרשה רק מבחי' החכ' שמלובשת במדות דז\"א כמ\"ש שמואל עליו הראיתם אשר בחר בו הוי' כי אין כמוהו כו' כנ\"ל ע\"כ נמשח בפך ולא בקרן כמ\"ש בשאול ויקח<sup data-n=\"1293\">114</sup> שמואל את פך השמן כו' ובדוד נאמר ויקח<sup data-n=\"1294\">115</sup> את קרן השמן וז\"ש רמה קרני ולא רמה פכי כי אין שרש בחי' הפך בבחי' רמה רק בבחי' אדם ולא בבחי' הרוממות דכתר עליון שלמעלה מבחי' אדם כנ\"ל וד\"ל.\n<b>ובכ\"ז</b> מובן הטיב מה שהשיב שמואל לשאול על אשר ביקש שישיבו לו המלוכה כי נצח ישראל לא ישקר כו' פי' בחי' נצחיות דא\"ס שמאיר במלכות דוד כנ\"ל",[["1282","103","<b>דוד מלך ישראל חי וקיים</b>: ר\"ה כה, א."],["1283","104","<b>וכוננתי את כסא ממלכתו</b>: שמואל-ב ז, יג."],["1284","105","<b>ונחה עליו רוח ה'</b>: ישעי' יא, ב."],["1285","106","<b>דמורח ודאין</b>: סנהדרין צג, ב. וראה סה\"מ תקס\"ב ע' סב. סה\"מ תקס\"ח ע' שסט. סידור ט, ד. ובכ\"מ."],["1286","107","<b>רמה קרני בה'</b>: שמואל-א ב, א. וראה ביאוה\"ז להצ\"צ ע' תקמג."],["1287","108","<b>ותרם כראם קרני</b>: תהלים צב, יא."],["1288","109","<b>וירם קרן</b>: תהלים קמח, יד."],["1289","110","<b>נאום הגבר הקים עול</b>: ראה שמואל-ב כג, א. מו\"ק טז, ב."],["1290","111","<b>כי ראיתי בבניו לי מלך</b>: שמואל-א טז, א."],["1291","112","<b>ה' ימלוך לעולם ועד</b>: שמות טו, יח."],["1292","113","<b>וכמ\"ש בדניאל</b>: ראה דניאל ג, לג. ועוד."],["1293","114","<b>ויקח שמואל את פך השמן</b>: שמואל-א י, א."],["1294","115","<b>ויקח את קרן השמן</b>: שם טז, יג."]]],[2101000213,"הטעם לא יפול בו שינויים<sup data-n=\"1295\">116</sup> להשתנות שנק' שקר כי הוא שפת אמת אשר אין בו שינוי ותיכון לעד כי אמת הוא רת\"ס דקו האמצעי שעולה ומבריח מבחי' הכתר עד בחי' מל' כידוע וזהו כי לא אדם הוא להנחם פי' שהוא למעלה מבחי' אדם שכולל ג' קוין להשתנות מחסד לדין וכיוצא ומטעם הנ\"ל שאין שינוי כלל בפנימי' הכתר וע\"כ א\"א להעביר המלוכה מבית דוד שכבר ניתנה לו כי א\"א שם להנחם אלא בהכרח שישאר מלך לעולם כמ\"ש בו ונאמן<sup data-n=\"1296\">117</sup> ביתך וממלכתך עד עולם ומטעם הנ\"ל.\n<b>ואחר</b> כ\"ז יובן שרש ענין זכור ושמור בדיבור א' נאמרו כו', דהנה מבואר למעלה בתכלית עבודת בחי' המרכבה דפני ארי' כו' וכן האבות שהן המרכבה למעלה יותר הוא רק להעלות לבחי' אדם שעל הכסא למעלה מבחי' אדם ומטעם הנ\"ל וכ\"ז כדי שיהי' מחמת העלאה זאת בחי' המשכה מלמעלה מבחי' אדם בחי' תוס' אור חדש ויבא ויומשך למטה במדות דאצי' אך ההפרש בין עבודת חיות הקודש שבמרכבה לעבודת האבות שהן המרכבה הנה יובן בהקדים ענין א' מ\"ש בע\"ח דיש ב' מיני זיווגים באו\"א הא' זיווג חיצוני דזיווגייהו תדיר ונק'<sup data-n=\"1297\">118</sup> תרין ריעין דלא מתפרשין כידוע והוא רק בשביל קיום העולמות בחיצוני' דהיינו שיתקיימו במציאותם עפ\"י מאמר קו המדה שנמשכו מתחלת ההשתלשלות אבל אינו בחי' תוס' אור חדש כלל אך זיווג הב' באו\"א הוא הנק' זיווג פנימי שהוא כדי לחדש נשמות חדשות והוא ענין ובחי' המשכות התחדשות אור חדש מעצמות המאציל שלא בא עדיין בבחי' ההשתלשלות בתחלה והנה בשביל יחוד וזיווג חיצוני הנ\"ל די בהעלאת מ\"נ של חיצוני' העולמות והוא בחי' ביטול היש לאין בכל עולם לפי ערכו ע\"ד שנא' וצבא<sup data-n=\"1298\">119</sup> השמים לך משתחווי' שעי\"ז גורם בחי' המשכה מחדש מאין דחכ' ליש דבינה והוא שנק' תרין ריעין דלא מתפרשין מפני שזה היחוד תמידי אבל אין בחי' ההמשכה זאת חדשה לגמרי רק שעי\"ז מתחדש לבא השפע בעולמות תמיד ולא יבוטל סדר השתלשלות שהוסדה מתחלה כמו שאנו או' מחדש<sup data-n=\"1299\">120</sup> בכל יום מע\"ב שהוא חו\"ב שעי\"ז נתחדש חיות השפע בכל יום כדמיון חידוש החיות באדם בכל יום אבל אינו חדש מעיקרו וזהו שנק' לקיום העולמות בלבד אבל לחדש נשמות חדשות לגמרי צריך להיות בחי' יחוד וזיווג פנימי בחו\"ב דהיינו שיומשך מבחי' עצמו' המאציל אור חדש ממש בחו\"ב ואין זה אלא ע\"י העלאת מ\"נ של נשמות הצדיקים דוקא כמ\"ש בע\"ח בענין י' הרוגי מלוכה שהן מעלין מ\"נ לאו\"א כו' (וזהו ג\"כ ההפרש בין יוסף לשבטי' שאמר קמה אלומתי כו' וכמ\"ש במ\"א) לפי שנשמות הצדיקים נמשכו מטפת יסוד אבא מבחי' הפנימי' של המוחין כמ\"ש כי<sup data-n=\"1300\">121</sup> אתה אבינו שהוא בחי' אור אבא מקור תולדות הנשמות וכמשל הטפה במוח האב שמתהווה מבחי' פנימי' הנפש ועצמותה ממש כו' וע\"כ ביכולת",[["1295","116","<b>שינויים. . שנק' שקר כי הוא שפת אמת</b>: ראה משלי יב, יט. וראה תניא פי\"ג ובליקוט פירושים ומ\"מ שם."],["1296","117","<b>ונאמן ביתך וממלכתך עד עולם</b>: שמואל-ב ז, טז."],["1297","118","<b>ונק' תרין ריעין דלא מתפרשין</b>: ראה זח\"ב נו, א."],["1298","119","<b>וצבא השמים לך משתחווים</b>: נחמי' ט, ו."],["1299","120","<b>מחדש בכ\"י מע\"ב</b>: נוסח ברכת יוצר."],["1300","121","<b>כי אתה אבינו</b>: ישעי' סג, טז."]]],[2101000214,"העלאת מ\"נ של נשמות הצדיקי' דוקא לעורר המשכת תוס' אור חדש מעצמות המאציל באו\"א כו' וד\"ל.\n<b>ובזה</b> יובן ג\"כ ההפרש בין עבודת חיות הקודש שבמרכבה שהעלאת מ\"נ שלהם כמו כשנק' מים<sup data-n=\"1301\">122</sup> תחתוני' בוכים אנן בעינן למהוי קדם מלכא כו' אינו גורם רק בחי' זיווג חיצוני רק לקיום העולמות בלבד כנ\"ל אבל עבודות העלאת מ\"נ של האבות שהן המרכבה בבחי' הפנימי' כנ\"ל בפי' המאמר דז\"א בע\"י תלוי גורמים זיווג פנימי באו\"א לחדש נשמות חדשות כנ\"ל וד\"ל. והנה כמו שע\"י בחי' המרכבה דפני ארי' כו' או בחי' מרכבה דאבות עושין בחי' העלאה לאדם העליון וממשיכים מלמעלה מבחי' אדם דאצי' ודבריאה כו' כך ע\"י מעשה המצות למטה יש בחי' העלאה לאדם העליון להמשיך בו תוס' אור חדש מעצמו' המאציל כנ\"ל באריכות בענין אני הוי' כו' שנמשך שם הוי' מחדש בכלים דז\"א שזהו עיקר ענין היחודי' עליונים דסובב הכללי כו' שנעשה ע\"י המצות לפי שבמצות יש ג\"כ בחי' העלאות והמשכות כי יש הרבה מצות שעיקרן רק בחי' העלאה מדברים גשמיי' דנוגה שנפלו בשבירה מבחי' רפ\"ח ניצוצות דתוהו שקדם לבחי' התיקון שמטעם זה ביכולתם להעלות ג\"כ לבחי' אדם לבחי' כי לא אדם הוא כנ\"ל והיינו כמו מצות תרומות ומעשרות שבתבואות גשמיי' שנפלו בשבירה והן צומחין בבחי' א\"ח<sup data-n=\"1302\">123</sup> והתרומה והמעשר הוא ענין העלאה והגבהה לברר מהן ולהעלות למעלה כו' וכיוצא בהן מצות הקרבנות בהעלאות חלב ודם ע\"ג המזבח ואש<sup data-n=\"1303\">124</sup> שלמעלה יורד ואוכל הקרבן כו' וכללות כל המצות שהן בבחי' ההעלאה הוא מצות הצדקה כמ\"ש צדקה<sup data-n=\"1304\">125</sup> תרומם גוי פי' תרומם בבחי' רוממות ההעלאה למעלה לפי שמעשה הצדקה מלובשת בגשמיות דכסף וזהב דנוגה וכו' ויש הרבה מצות שהן בבחי' המשכה מלמעלה למטה כמו מצות ציצית שנמשכין עי\"ז ל\"ב נ\"ח מבחי' א\"מ דטלית וע\"י מצות תפילין נמשך ד' מוחין לז\"א כו' וע\"י מצות סוכה נמשך בחי' מקיפים דאימא וכן ע\"י השופר נמשך הארת ע\"י כו' וכיוצא בזה ובהן מעוררי' לבחי' עתיקא שלמעלה מבחי' אדם להמשיך תוס' אור חדש למטה כו' כנ\"ל וד\"ל, וכ\"ז הכח ניתן לישראל בקבלת התורה בין בבחי' חיצוניות כמו ע\"י מעשה המצות או כמו עבודת החיות שבמרכבה כו' בין בבחי' הפנימי' בעבודת האבות שנק' מרכבה כנ\"ל והיינו במס\"נ באחד שמעלין מ\"נ לאו\"א כו' הנה כ\"ז ניתן להם בשעת מ\"ת וזהו הנק' קבלת התורה שהרי מי שאינו מבנ\"י אינו ממשיך כלום לא בחיצוניות מעשה המצות ולא בפנימי' אפי' במס\"נ כו' וד\"ל.\n<b>ובכ\"ז</b> מובן מ\"ש רז\"ל דזכור ושמור בדיבור א' נאמרו, דהנה אמרו בזוהר<sup data-n=\"1305\">126</sup> דזכור לדכורא ושמור לנוק' והענין הוא כנ\"ל שע\"י בחי' ההעלאות דוקא נעשה בחי'",[["1301","122","<b>מים תחתוני' בוכין אנן בעינן למהוי קדם מלכא</b>: ת\"ז תי' ה'. תוס' הרא\"ש בראשית בתחלתו."],["1302","123","<b>א\"ח</b>: אור חוזר."],["1303","124","<b>ואש שלמעלה יורד ואוכל הקרבן</b>: יומא כא, ב."],["1304","125","<b>צדקה תרומם גוי</b>: משלי יד, לד."],["1305","126","<b>בזוהר דזכור לדכורא ושמור לנוקבא</b>: זח\"ב צב, א."]]],[2101000215,"ההמשכות דאור חדש בחיצוניו' ובפנימיות שהוא ב' מיני זיווגים דאו\"א כנ\"ל וזהו פי' שמור לנוק' שהוא בחי' העלאת מ\"נ של המקבלי' שנק' נוקבא כמ\"ש ואל<sup data-n=\"1306\">127</sup> אישך תשוקתך כידוע והטעם שנק' שמור הענין הוא כי פי' שמור לשון המתנה כמו ואביו<sup data-n=\"1307\">128</sup> שמר כו' ושמרתי<sup data-n=\"1308\">129</sup> לך את הברית כו' וה\"ז ענין מה שהלב משמר ומצפה מתי יבא דבר הנאהב לו שנק' תוחלת ממושכה כו' כידוע וכמו העני שמצפה ומייחל אל הבעה\"ב מתי ישפיע לו מאומה ותמיד עיניו נשואות אל המשפיע וכן כל עיני מקבל נשואות תמיד אל המשפיע ולכך שמור לנוק' שבחי' נוק' משמרת ומצפה ועיניה נשואות כלפי המשפיע וז\"ש עיני כל אליך כו' וז\"ש ג\"כ ותשב<sup data-n=\"1309\">131</sup> בפתח עינים או עיניך<sup data-n=\"1310\">132</sup> יונים ומטעם זה נאמר הסיבי עיניך מנגדי<sup data-n=\"1311\">133</sup> כו' וכמ\"ש במ\"א וככה ממש עיני<sup data-n=\"1312\">130</sup> כללות נש\"י נשואות בהעלאת מ\"נ כלפי הקב\"ה להיות בחי' המשכה וגילוי מהעלם עצמו' אא\"ס שנק' אנכי כמ\"ש לעתיד ונגלה<sup data-n=\"1313\">134</sup> כבוד ה' עין בעין<sup data-n=\"1314\">135</sup> יראו כו' וז\"ש כעיני<sup data-n=\"1315\">136</sup> עבדי' אל יד אדוניהם פי' עבדים הן בחי' מט\"ט וסנד\"ל דיצי' ועשי' וכמ\"ש<sup data-n=\"1316\">137</sup> בזהר ע\"פ לא תצא כצאת העבדי' ואמה ושפחה הוא בבחי' בריאה והיינו כעיני<sup data-n=\"1317\">138</sup> שפחה שהוא בחי' מל' דבריאה אל גבירתה שהוא בחי' מל' דאצי' כך עינינו שהוא העלאת מל' דאצי' אל ה' אלקינו שהוא בחי' יחוד פנימי דאו\"א שיש שם אור חדש מעצמו' המאציל כנ\"ל שיומשך בגילוי מן ההעלם העצמו' כנ\"ל וז\"ש עד שיחננו וכל חן וחנינה הוא הוא בחי' תוס' אור רצו\"פ מבחי' העצמות דוקא וכמ\"ש במ\"א וד\"ל.\n<b>וזהו</b> זכור ושמור בדיבור א' נאמרו, פי' זכור לדכורא שהוא בחי' המשכות תוס' אורות חדשים מעצמות המאציל כנ\"ל הבא ע\"י בחי' העלאת מ\"נ דנוק' שנק' שמור מטעם הנ\"ל אעפ\"י שבדרך ההשתלשלות יש הפרש גדול ביניהם שזה עולה מלמטה למעלה כמ\"ש כעיני עבדים כו' כנ\"ל וזה יורד מלמעלה למטה בבחי' דכר משפיע אבל למעלה מבחי' ההשתלשלות דקו וחוט כו' שהוא בחי' עיגול מקיף כללי להקיף כל ההשתלשלות כא' מבלי שימצא שם בחי' מעלה ומטה כלל וכלל כידוע ע\"כ שם בחי' מקבל ומשפיע שוין ממש כי אין שם בחי' עליות וירידות כלל א\"כ זכור ושמור דדכר ונוק' נאמרו שם בדיבור א' כו' וד\"ל (והוא ג\"כ ענין קבלת התורה שקיבלו ישראל להיות כלול בהן שני הכחות דדכר ונוק' יחד להיות מעלין מ\"נ וממשיכים מ\"ד בחיצוניו' ובפנימיות כנ\"ל ע\"כ יכלו לקבל זכור ושמור בדיבור א' מה שאין האזן יכולה לשמוע ובזה מתורץ קושי' הנ\"ל וד\"ל).",[["1306","127","<b>ואל אישך תשוקתך</b>: בראשית ג, טו."],["1307","128","<b>ואביו שמר</b>: בראשית לז, א. וראה פירש\"י שם."],["1308","129","<b>ושמרתי לך את הברית</b>: ראה דברים ז, יב."],["1309","131","<b>ותשב בפתח עינים</b>: בראשית לח, יד."],["1310","132","<b>עיניך יונים</b>: שה\"ש א, טו."],["1311","133","<b>הסבי עיניך מנגדי</b>: שה\"ש ו, ה וראה זח\"ג פד, א."],["1312","130","<b>עיני כל</b>: תהלים קמה, טו."],["1313","134","<b>ונגלה כבוד ה'</b>: ישעי' מ, ה."],["1314","135","<b>עין בעין יראו</b>: ישעי' נב, ח."],["1315","136","<b>כעיני עבדים אל יד אדוניהם</b>: תהלים קכג, ב."],["1316","137","<b>וכמ\"ש בזוהר ע\"פ לא תצא כצאת העבדים</b>: זח\"ב צד, ב."],["1317","138","<b>כעיני שפחה</b>: תהלים שם."]]],[2101000216,"<h3>להבין שרשי הדברים</h3>\n<b></b><b>בעזר\"ה<sup data-n=\"1318\">1</sup> </b>\n<b>להבין</b><sup data-n=\"1319\">2</sup> שרשי הדברים הנ\"ל בענין זכור ושמור בדיבור א' נאמרו (באופן אחר). הנה י\"ל שרש ענין האבות הן המרכבה הנ\"ל למה נק' האבות בשם המרכבה דבשלמא בחי' המרכבה דפני ארי' ופני שור כו' שייך לקרותם בשם מרכבה מטעם המבואר למעלה דשרש פני ארי' כו' הוא מבחי' מלכים דתוהו שנפלו בשבה\"כ בעולם הבריאה וע\"כ יש בכחם להעלות לבחי' אדם שעל הכסא כמשל הסוס שנושא את הרוכב כך החיות נושאות את הכסא כו' אבל האבות ששרשם במח' עילאה שע\"ז אמר איהו וגרמוהי חד וגם איהו וחיוהי מתאחד במחשבה שנק' גרמוהי כנ\"ל ע\"כ מאחר שמיוחדין בעצמות המאציל למה נק' בשם מרכבה הלא בחי' מרכבה הוא בחי' דבר נפרד כמרכבה דסוס שנפרד מן הרוכב, וגם זה הטעם שיש בכח המרכבה להעלות אדם הרוכב לפי ששרשו מבחי' התוהו לכאורה זה לא יתכן לומר באבות וא\"כ למה נק' האבות בשם מרכבה דוקא.\n<b>אך</b> הענין יובן בהקדים להבין ענין מרכבת החיות דפני ארי' כו' בתוס' ביאור במה שנושאים את הכסא ועל הכסא דמות כמראה אדם כנ\"ל דהנה<sup data-n=\"1320\">3</sup> פי' אדם הוא בחי' התכללות ג' קוין וע\"ז מורה תמונת אות הא' שהוא יו\"ד בראשו ויו\"ד בתחתיתו וקו באמצע המחבר לב' היודין שהוא בחי' התכללות והתחברות מבחי' חסדי' דאבא ובחי' גבורות דאימא יחד שע\"ז מורה היו\"ד העליון ויו\"ד התחתון שמתחברין יחד בקו הזה אשר באמצע והוא עיקר בחי' אדם שהוא בגי' שם מ\"ה שהוא במילוי אלפין דוקא כידוע אך י\"ל למה נק' בחי' ההתכללות וההתחברות מג' קוין בחי' מ\"ה דוקא אם מפני שע\"י בחי' הביטול שנק' מ\"ה יוכל להיות בחי' התכללות והתחברות מב' הפכים ג\"כ (כידוע במשל ב' בנ\"א הפכיי' כעשיר ועני שזה ברוממות וזה בשפלות או שני מלכים גדולים או הפכיי' בטבעי המדות מחו\"ג כמים ואש יוכלו להתחבר יחד כאשר יבא בחי' ביטול במציאות בהם מחמת שכאו\"א ישפיל א\"ע כו' וכנראה בחוש שבחי' השפלות תעשה בחי' האחדות כו' והרוממות תעשה הפירוד כו' וכמ\"ש במ\"א).\n<b>וזהו</b> ענין חטא של סדום<sup data-n=\"1321\">4</sup> שאמרו שלי שלי שלך שלך לפרוש א\"ע להיות כאו\"א לבדו בלתי מצטרך לזולתו שזהו בחי' התוהו היפך בחי' התיקון שהוא בחי' התכללות להיות כאו\"א מקבל מזולתו לפי שלא ימצא שלימות בלעדי זולתו וכן זולתו לא ישלים נפשו בלעדו כו' מפני בחי' השפלות והחסרון שמוצא כאו\"א בעצמו",[["1318","1","<b>בעזר\"ה</b>: בכת\"י ג רשום: ביאור שני על הנ\"ל."],["1319","2","<b>להבין שרשי הדברים</b>: נדפס בשינויים בתו\"א יתרו עב, ו. וראה בארוכה ד\"ה פדה בשלום בסה\"מ תרל\"ב ח\"א ע' יב ואילך, וע' טו ואילך. וש\"נ בארוכה. חלק מהמאמר כאן הובא ג\"כ בהמשך תער\"ב ח\"א ע' תפ."],["1320","3","<b>דהנה פי' אדם. . התכללות ג' קוין</b>: ראה ג\"כ לקו\"ת אמור קכו, ג. אוה\"ת שמות ע' מד. ולכללות הבא להלן ראה המשך מים רבים תרל\"ו ע' קיח ואילך."],["1321","4","<b>סדום שאמרו שלי שלי שלך שלך</b>: ראה אבות פ\"ה מ\"י."]]],[2101000217,"ונמצא ע\"י בחי' הביטול והשפלות שהוא בחי' מ\"ה מתאחדי' ומתחברי' כמה הפכיי' או שני גדולים כו'. וכדוגמא זו יש בארץ שכל מדינה יש בה חסרון דבר א' שצריכה לקבל אותה ממדינה אחרת וכן מדינה האחרת תחסר מדבר אחר שצריכה לקבל ממדינה זו עד שעי\"ז מתאחדי' כולם לפי שאין לך מדינה א' שלא תחסר כל בה שלא תצטרך לזולתה. וז\"ש ה'<sup data-n=\"1322\">5</sup> בחכ' יסד ארץ בשם מ\"ה דתיקון כו' ולכך נהפכה סדום לפי שהייתה נגד בחי' התיקון כו' (ומ\"ש בא\"י לא<sup data-n=\"1323\">6</sup> תחסר כל בה היינו לפי שכוללת לכל הארצות להיותה נקראת אמצעיתו דכל עלמא כמו בחי' הלב בגוף כו' וה\"ז למעלה כמו בחי' קו האמצעי דתיקון שכלול מכולם כו' וד\"ל) א\"כ למה נק' בציור תמונת אדם שהוא ציור כולל כמה מציאות מדריגות בתמונת ג' קוין כו'. אך באמת הא בהא תלי' דמשום דשרש בחי' ההתכללו' באה ע\"י בחי' מ\"ה ע\"כ יהי' כלול מכמה מדריגות בתמונת ג' קוין ואע\"ג דבחי' ביטול דמה הוא בחי' ביטול והתכללו' במקור הראשון היא הנותנת לקרות בשם אדם בתמונת ג' קוין דוקא כו'.\n<b>וביאור</b> הדברי' הנה תחלה י\"ל ביאור ענין התחלקות הג' קוין כו' דהנה בחי' קו הימין שרשו הוא בחי' החסדי' שיורדי' ונמשכין מגבוה לנמוך כמ\"ש חסד<sup data-n=\"1324\">7</sup> דרוע' ימינא שנמשך השפע מלמעלה למטה מטה כטבע המים שיורדין מגבוה לנמוך כידוע ובחי' קו השמאל שרשו בבחי' גבורות שהוא בחי' ההסתלקות למעלה כטבע האש אשר עולה מלמטה למעלה דוקא וזהו ג\"כ שרש הכהנים והלוים שהכהנים<sup data-n=\"1325\">8</sup> המה מבחי' החסדי' שממשיכים מלמעלה למטה ושרש הלוים מבחי' הגבורות שעולין מלמטה למעלה וכמ\"ש ועבד<sup data-n=\"1326\">9</sup> הלוי הוא שעבודתו בשיר על הקרבן להעלות בהעלאה למעלה כמ\"ש<sup data-n=\"1327\">10</sup> בזוהר ונמצא שהן ב' הפכי' ממש כמו מיכאל וגבריאל או שר של אש ושר של מים למטה כו'. והנה דבר המחבר ב' הפכי' כאלה הוא בחי' מ\"ה שהוא בחי' קו האמצעי שנק' אדם שם מ\"ה כו' וענין ובחי' מ\"ה זה היינו כאשר נמשך מלמעלה מהם בחי' ביטול אז יתכללו ויתחברו גם שני הפכים כמ\"ש עושה<sup data-n=\"1328\">11</sup> השלום במרומיו כמיכאל וגבריאל שהן כמו אש ומים ואין מכבין זא\"ז לפי שמאיר עליהם אור עליון הנעלה משניהם יחד ששם מתבטלין הב' הפכים ואין שם דבר והיפוכו כלל מאחר שהאור הוא נעלה מערכם לגמרי כי מה שהן ב' הפכים כמו בחי' המשכת החסדי' והסתלקות דגבורו' אין זה אלא בבחי' אור הנמשך ובא בהשתלשלות אזי בא בבחי' רצוא ושוב כמ\"ש והחיות<sup data-n=\"1329\">12</sup> רו\"ש אבל שם לא שייך לומר בחי' רצוא ושוב כלל אחר שהוא למעלה מבחי' השתלשלות עדיין אלא האור הוא בבחי' ביטול והתכללות בעצמו' המאציל לא שייך לומר לא בחי' הסתלקות ולא בחי' המשכה כו' וע\"כ כאשר",[["1322","5","<b>ה' בחכ' יסד ארץ</b>: משלי ג, יט."],["1323","6","<b>לא תחסר כל בה</b>: דברים ח, ט."],["1324","7","<b>חסד דרועא ימינא</b>: ת\"ז בהקדמה ד\"ה פתח אליהו."],["1325","8","<b>שהכהנים המה מבחי' החסדים</b>: זח\"א רנו, ב. זח\"ג מח, ב. קכא, ב. ועוד."],["1326","9","<b>ועבד הלוי הוא</b>: במדבר יח, כג. וראה לקו\"ת קרח נה, ב."],["1327","10","<b>כמ\"ש בזוהר</b>: זח\"ג קעח, ב."],["1328","11","<b>עושה השלום במרומיו כמיכאל וגבריאל</b>: איוב כה, ב. במדב\"ר פי\"ב, ח. זח\"ג יב, ב. וראה ביאוה\"ז לאדהאמ\"צ ר\"פ לך לך."],["1329","12","<b>והחיות רו\"ש</b>: יחזקאל א, טו."]]],[2101000218,"נמשך משם בחי' הארה שהיא עליונה משני ההפכים אזי יתבטלו ממציאותם ויתכללו יחד ועד\"מ ב' עבדי' הפכיי' כשבאין לפני המלך מתאחדי' ממש מפני מעלת מדריגת רוממות המלך שנעלה הרבה משניהם יחד או כמשל ב' תלמידים המחולקים זה אוסר וזה מתיר וכאשר באים לקבל מרבם לא ימצא ביניהם<sup data-n=\"1330\">13</sup> כי יתבטלו כלי השגתם לגבי מעלת השגת רבם כו'. וזהו הטעם שנק' הארה זו מאור העליון על ב' ההפכי' בשם מ\"ה לפי שנמשך בהן מלמעלה בחי' הביטול הנק' מ\"ה דהיינו בחי' מ\"ה שבעליון נמשך בהן להיות מתכללים עי\"ז. דהנה התכללותם זאת הגם שבאה בסיבת הביטול דמ\"ה מ\"מ הרי ישנם במציאות ממש רק שכאו\"א מתכלל ומתאחד גם עם היפכו משא\"כ בחי' מ\"ה שבעליון משניהם שנק' מ\"ה מצד שמושלל מבחי' ישות של המשכות דבר מה כנ\"ל שא\"א לומר בבחי' אור הבטל וכלול בעצמות ענין ובחי' חו\"ג רצוא ושוב כו'. ונמצא שיש ב' מדריגות בבחי' מ\"ה א' בבחי' מ\"ה שבאור העליון והב' בחי' המשכת מ\"ה זה באורות הנמשכין למטה וז\"ש מה<sup data-n=\"1331\">14</sup> שמו מה שם בנו פי' מה שמו הוא בחי' אור אבא עצמו וממנו נמשך בחי' מ\"ה בחי' ביטול בבנו שהוא בחי' התחלקות המדות דז\"א חו\"ג דאצי' להיות נכללים יחד והוא בחי' התכללות דג' קוין בציור אדם כנ\"ל וזהו מ\"ה שם בנו ומה הראשון הוא הנק' אדם קדמאה שהוא בחי' אור אבא ומה הב' נק' אדם שני כו' כמ\"ש<sup data-n=\"1332\">15</sup> בזוהר בכמה דוכתי וד\"ל. ובזה יובן דהגם שבחי' ההתכללות דחו\"ג בא ע\"י בחי' מ\"ה שהוא מורה בחי' הביטול במקור העליון שלמעלה משניהם כנ\"ל מ\"מ אדרבה בחי' ביטול דמ\"ה זה היא הנותנת וגורמת להיות במדות בחי' ציור אדם בתמונת ג' קוין בכמה פרטי' שונים לפי שעי\"ז מתכללי' כל ריבוי פרטי אורות גם ההפכיי' יחד והרי נמצאין במציאותן ממש רק שמתאחדי' והיו לאחדים לפי שאין בהם רק הארת שם מ\"ה דחכ' לחברם יחד אבל לא שמתבטלי' ממציאותם לגמרי כמו בבחי' מ\"ה דחכ' עצמו כו' וד\"ל.\n<b>והנה</b> עבודת המרכבה דפני ארי' כו' היינו שנושאין את הכסא ועל הכסא בחי' אדם הנ\"ל שהוא בחי' התכללות הג' קוין הבא מבחי' מ\"ה דא\"ק כו' ושרש ענין עבודתם בהעלאת אדם זה הנה הוא להעלות אותו למעלה מבחי' אדם כנ\"ל כדי שיומשך אח\"כ תוס' אור חדש באדם זה והיינו בחי' הארת שם מ\"ה מחדש להיות בו בחי' ההתכללות מג' קוין כו' ולא יהי' בבחי' ענפין מתפרדין כו' אבל אין בחי' ביטול והתכללות נמשך באדם זה רק ע\"י מה שנושאין את האדם הזה ומעלין אותו למעלה מבחי' אדם כדי שיומשך משם בחי' שם מ\"ה חדש באדם זה כו'. וביאור הדברי' הנה ידוע דבחי' עצמו' אא\"ס מובדל בערך לגמרי גם מהיות בחי' מקור להתחלקות ע\"ס וכמאמר לאו<sup data-n=\"1333\">16</sup> דאית לך מכל אינון מדות כלל אך נמשך בבחי' צמצום ומדה בקו\"ח כו' כמ\"ש בע\"ח וע\"כ כאשר יעלה בחי' מדות דאדם זה למעלה מבחי' הקו כו' יומשך משם בחי' אור עליון שלמעלה מבחי' התחלקת דע\"ס ועי\"ז יהי' בהן בחי' התכללות",[["1330","13","<b>ביניהם</b>: כ\"ה בהכת\"י, ואוצ\"ל: ביניהם מחלוקת."],["1331","14","<b>מה שמו ומה שם בנו</b>: משלי ל, ד."],["1332","15","<b>כמ\"ש בזהר בכמה דוכתי</b>: זח\"ב עט, א. וראה מאו\"א א, קסו. ס' הערכים חב\"ד ערך אדה\"ר ע' קסו."],["1333","16","<b>לאו דאית לך מכל אינון מדות</b>: ת\"ז בהקדמה ד\"ה פתח אליהו."]]],[2101000219,"יותר מבראשונה מטעם הנ\"ל וד\"ל. וזהו מ\"ש בחיות שבמרכבה ודמות<sup data-n=\"1334\">17</sup> פניהם פני אדם, דהנה בכל א' מד' חיות שבמרכבה יש בחי' פני אדם וכמ\"ש ופני<sup data-n=\"1335\">18</sup> אדם לארבעתם א\"כ מ\"ש ודמות פניהם פני אדם הנה זהו ענין כללות בחי' פרצוף אדם העליון שעל הכסא ומ\"ש ופני אדם לארבעתם היינו בחי' פני אדם בפרט שיש בכאו\"א והפרט נמשך מן הכלל כו' והענין הוא כי הנה בחי' פני אדם הוא רק בחי' וענין התכללות מכמה מדריגות יחד ויש בזה כמה מדריגות לפי שיש בחי' התכללות רק במדות בלבד כמו חג\"ת או במוחין בלבד כמו חב\"ד כו' ועד\"ז יש פרטי פרטי' של בחי' התכללות וכאו\"א נק' פני אדם וא\"כ יוכל להיות בחי' פני אדם גם בבחי' פרטיות מדריגה של כאו\"א מד' חיות שבמרכבה וז\"ש ופני אדם לארבעתן והיינו משום דבחי' חכ' דאדם יש בכל הברואים כמ\"ש כולם<sup data-n=\"1336\">19</sup> בחכ' עשית (וכמ\"ש במ\"א בענין ושמן מחלמיש צור שנמצא בחי' שמן דחכ' גם בצור כמ\"ש בפרד\"ס כו'). אבל בחי' אדם הכללי שכולל כל פרטי אדם שבד' חיות הוא בחי' אדם העליון שעל הכסא (וכמ\"ש במ\"א ע\"פ ומשה עניו מכל האדם אשר על פני האדמה כי הי' בחי' אדם יותר כללי מכל בחי' אדם אשר ע\"פ האדמה והיינו בחי' א\"ק כו' וד\"ל) וזהו ודמות פניהם פני אדם פי' דמות פני אדם הכללי המאיר עליהם נק' דמות פניהם בכלל להיותו הכולל דמות פני אדם שבפרט שבכאו\"א וזהו דמות פניהם הכללי הוא פני אדם העליון כו' וד\"ל.\n<b>אך</b> מהיכן יומשך להיות בחי' פני אדם העליון בבחי' התכללות ג' קוין כנ\"ל כ\"כ עד שיומשך בחי' התכללות דפני אדם למטה מטה גם בפרטי פרטי' בד' חיות שבמרכבה הנה זהו ע\"י שהחיות נושאין את הכסא ועל הכסא דמות כמראה אדם כנ\"ל והתנשאות זאת היא למעלה מעלה מבחי' אדם כדי שיומשך משם אח\"כ תוס' אור מעצמות המאציל להיות בחי' התכללות יותר מטעם דלאו דאית לי' מכל אינון מדות כלל כנ\"ל וזהו ודמות פניהם פי' בחי' פנימי' הרצון והתשוקה מלמטה למעלה בהעלאה לכסא האדם הוא רק מפני שכל מגמתם ופנימיותם הוא להיות בחי' המשכה אח\"כ להיות בחי' אדם בהתחברות והתכללות ג' קוין עד שיהי' גם בהם בחי' פני אדם בפרט כנ\"ל וכמ\"ש והחיות רו\"ש כו' וד\"ל.\n<b>ומעתה</b> יובן תירוץ הקושי' הנ\"ל בענין האבות הן המרכבה למה נק' בשם מרכבה כו'. דהנה שרש האבות הוא בבחי' חג\"ת דז\"א דאצי' כידוע והיינו בבחי' הכלים דז\"א כמו אברהם הי' בחי' מרכבה לבחי' הכלי דחסד דאצי' שמתלבש בחסד דבריאה שהוא שרש נשמת אברהם כו' ועד\"ז יצחק ויעקב בגבורה ות\"ת וע\"ז אמרו האבות הן המרכבה ואעפ\"י שע\"ז אמר דאיהו וגרמוהי חד כנ\"ל מ\"מ שייך לקרותם בשם מרכבה כמו שהחיות שבבריאה נק' מרכבה מטעם שמעלין לבחי' אדם שהוא בחי' ז\"א כך יש לקרות לאבות שהן בבחי' כלים דז\"א בשם מרכבה מפני שהן מעלין",[["1334","17","<b>ודמות פניהם פני אדם</b>: יחזקאל א, י."],["1335","18","<b>ופני אדם לארבעתם</b>: ראה יחזקאל א, י. והערת כ\"ק אדמו\"ר זי\"ע בהמשך מים רבים תרל\"ו ע' נא."],["1336","19","<b>כולם בחכ' עשית</b>: תהלים קד, כד."]]],[2101000220,"לבחי' א\"ק שהוא אור אבא כנ\"ל בפי' מה שמו ומה שם בנו כו' וג\"כ מאותו הטעם שנק' החיות מרכבה להיות ביכולתם להעלות את הרוכב לפי ששרשם ממדריגה עליונה מבחי' התוהו שקדם לבחי' התיקון כמבואר למעלה כך יש טעם ביכולת האבות להעלות גם לבחי' א\"ק שהוא בחי' אור אבא לפי ששרשם למעלה מבחי' החכ' דאור אבא כו' וד\"ל.\n<b>ולהבין</b> זה יש להקדים תחלה ביאור ענין המאמר באדר\"ז<sup data-n=\"1337\">20</sup> דאו\"א ממו\"ס דא\"א נפקן אבל ז\"א בעתיקא אחיד ותלי' כו' ע\"ש. וזה המאמר יפלא לכאורה שהרי בחי' המדות שנק' ז\"א נמשך רק מבחי' חו\"ב שנק' או\"א כי כמו אב ואם המולידים בן ובת כך בחי' חו\"ב מולידים את המדות אוי\"ר כנודע ואיך אמר דז\"א בעתיקא עצמו אחיד שהוא למעלה הרבה מבחי' מו\"ס דא\"א כידוע בע\"ח בכמה דוכתי. אך הענין הוא מובן עד\"מ מבשרי אחזה כו' דהנה ידוע פי' מו\"ס הנק' חכמה שבכתר שהוא כמו בחי' כח המשכיל שבאדם שהוא למעלה מן השכל הגלוי בטעם וסברא ומה שנק' בשם משכיל היינו ע\"ש שהוא בחי' מקור השכל הגלוי כשעדיין הוא בהעלם בבחי' כח היולי וע\"כ נק' ח\"ס כנודע וז\"ש דאו\"א במו\"ס אחידן דחו\"ב נמשכין מבחי' העלם כח המשכיל וכמ\"ש והחכ' מאין תמצא<sup data-n=\"1338\">21</sup> כו' וכמ\"ש במ\"א באריכות אבל בחי' המדות דז\"א בעתיקא עצמו אחיד פי' בבחי' כשב\"כ שלמעלה מבחי' חכ' שבכתר והוא הנק' בחי' עתיקא שהוא בחי' פנימי' א\"א כו'.\n<b>וביאו'</b> הדברים הנה הגם שאנו רואים שהמדות נמשכין ונולדים מן ההתבוננו' שנק' בינה כמ\"ש כי<sup data-n=\"1339\">22</sup> אם לבינה תקרא שבחי' בינה נק' אם הבנים לפי שהמדות נולדו מן ההתבוננו' והחכ' נק' אב כי ממנו מקור התולדה כידוע מ\"מ אין עיקר מהות המדות מתהווים מחו\"ב אלא רק שיוצאים מן ההעלם לגילוי בדרך מעבר בלבד מחו\"ב להיות גילוי התפעלות בלב ע\"י השכל וכנראה בחוש בטבע הטוב להטיב דגם שיתפעל בחסד מצד ההתבוננו' מ\"מ אין ההתבוננו' רק כמו סיבה לעורר מדה זאת הטבעי' שיש בנפשו להטיב ולרחם כי עיקר המדות ומהותם כבר הוטבע בנפש בבחי' טבעיי' וע\"י חו\"ב יצאו לידי גילוי בלבד מהעלם עצם מציאותם כו' ונמצא שרש מהות עצם המדות הן למעלה מחו\"ב כו'. וזהו ההפרש גם בעבודת ה' בין דו\"ר שכליי' לדו\"ר טבעיי' שנק' אהבה המסותרת בבחי' עצמיו' וטבעיות שבחי' אהבה הטבעי' הרי נק' בשם אה\"ר להיותה כמו שהיא בעצמי' מהות טבע בנפש שהיא למעלה מבחי' התפשטותה והתגלותה ע\"י השכל שמעוררה ומולידה שאינו אלא הארה בעלמא מוגבלת מעצמותה כו' וע\"כ בחי' אהבה שנולדה מן השכל נק' אהבת עולם ונק' אהבה זוטא ונמצא בחי' דו\"ר טבעיי' גבוהים בשרשם גם מבחי' מקור דחו\"ב הנק' משכיל מקור השכל כי הרי שרשם בבחי' עצמיות הנפש כמו רצון העצמי שלמעלה מן הטעם גם מן הטעם כמוס הנעלם שברצון שנק' ח\"ס כידוע וכמו",[["1337","20","<b>באדר\"ז דאו\"א ממו\"ס דא\"א נפקן</b>: זח\"ג רצב, א."],["1338","21","<b>והחכמה מאין תמצא</b>: איוב כח, יב."],["1339","22","<b>כי אם לבינה תקרא</b>: משלי ב, ג. וראה זח\"א ריט, א."]]],[2101000221,"בחי' אה\"ר שהיא בחי' עצם רצון פשוט שלמעלה מבחי' טעם לגמרי רק מפני שזהו עצם מציאותה כמו טבע הטוב להטיב למעלה מן הטעם רק שזהו עצם טבעו כו'. אך מ\"מ יש מעלה יתירה בדו\"ר שכליי' מדו\"ר טבעיי' מצד אחר והוא לפי שבחי' הבירור דמדות רעות דנוגה שבאת זלעו\"ז כו' שמקבלין מדו\"ר טבעיי' שבנפש כמו אברהם שיצא ממנו ישמעאל<sup data-n=\"1340\">23</sup> חסד דקליפה כו' אינו אלא בחכ' דוקא כי<sup data-n=\"1341\">24</sup> בחכ' אתברירו דוקא, והיינו דוקא בדו\"ר שכליי' ולא בדו\"ר טבעיי' שלמעלה מן השכל ואמנם לאחר שנבררו מדות דנוגה ע\"י החכ' שבמדות שנק' דו\"ר שכליי' הרי מצד עצם מציאות ומהות טבע עצם המדות גבוהים הם מדו\"ר שכליי' מטעם הנ\"ל וד\"ל.\n<b>ובכ\"ז</b> יובן מארז\"ל יפה<sup data-n=\"1342\">25</sup> כח הבן מכח האב כו' דלכאורה איך אפשר שיהי' כח הבן הנולד יפה מכח האב שהולידו כו'. אך עפ\"י הנ\"ל מובן מפני דגם שתולדות הבן נמשך מטיפת כח האב שהוא בחי' חו\"ב נק' אב כו' כנ\"ל מ\"מ מצד שרש עצמיות הבן יפה כחו מכח טיפת האב המולידו לפי ששרש כח הבן הוא למעלה מבחי' טיפת האב המוליד להיות כי ידוע דהטפה במוח האב מתהווה מעצם הנפש שלמעלה הרבה מבחי' מוחין דאב כו' וד\"ל. והנמשל מזה יובן למשכיל למעלה בענין מאמר הנ\"ל דאו\"א ממו\"ס דא\"א נפקן שהוא הנק' משכיל שממנו מתהווה בחי' טיפת אבא הבאה מן המוחין והוא ענין כוונות<sup data-n=\"1343\">26</sup> דפסוק ראשון דק\"ש הוי' אלקינו כו' שהוא יחוד או\"א להוליד המדות דז\"א כידוע אבל יפה כח הבן שהוא בחי' המדות דז\"א מצד שרשו בעצמיות הכתר הנק' עתיקא גם מבחי' כח האב שהוא בחי' מוחין דאבא שאינו אלא מבחי' מו\"ס דא\"א וד\"ל. וזהו שאנו או' שמע ישראל דוקא לפי שע\"י בחי' ישראל שעלה במח\"ס מבחי' עצמיות הכתר הנק' עתיקא משום דז\"א בע\"י אחיד כנ\"ל עי\"ז נעשה בחי' יחוד הוי' אלקינו הנק' עתיקא משום דז\"א בע\"י אחיד כנ\"ל עי\"ז נעשה בחי' יחוד הוי' אלקינו או\"א להיות מקבלי' מח\"ס כו' וזהו פי' ישראל<sup data-n=\"1344\">27</sup> לי ראש כו' וכמ\"ש ישראל<sup data-n=\"1345\">28</sup> אשר בך אתפאר כו' וד\"ל.\n<b>אך</b> י\"ל מפני מה ירדו בחי' דו\"ר טבעיי' כ\"כ למטה במדריגה להיות למטה מן השכל והטעם אחר ששרשם גבוה כ\"כ כנ\"ל. אמנם הענין יובן עד\"מ מנפילת אבן מן החומה שכל שהגובה של החומה ביותר יותר תפול למטה למרחוק כי לפי ערך העלי' כך ערך הירידה וכמ\"ש<sup data-n=\"1346\">29</sup> בס\"י שיש עומק רום ועומק תחת ולפי ערך עומק הרום כך ערך הירידה למטה בעומק תחת וכמשל מי ששכלו עמוק יותר יותר",[["1340","23","<b>אברהס שיצא ממנו ישמעאל</b>: פסחים נו, א. ויק\"ר פל\"ו, ה. ספרי ואתחנן ו, ד. ועוד."],["1341","24","<b>כי בחכ' אתברירו</b>: ראה זח\"ב רנד, ב. ע\"ח שי\"ח פ\"ה ועוד. מבו\"ש ש\"ה ח\"א פ\"ב. אגה\"ק סכ\"ח. וראה הערת כ\"ק אדמו\"ר זי\"ע בסה\"מ תש\"ח ע' 206."],["1342","25","<b>יפה כח הבן מכח האב</b>: שבועות מח, א."],["1343","26","<b>כוונות דפסוק ראשון דק\"ש הוי' אלקינו. . יחוד או\"א</b>: ראה הערת כ\"ק אדמו\"ר זי\"ע בסה\"מ תש\"ג ע' 168."],["1344","27","<b>ישראל לי ראש</b>: ראה דרמ\"צ טו, ב בשם הזוהר."],["1345","28","<b>ישראל אשר בך אתפאר</b>: ישעי' מט, ג."],["1346","29","<b>וכמ\"ש בס\"י שיש עומק רום ועומק תחת</b>: פ\"א מ\"ה."]]],[2101000222,"יוכל להוריד השכל למטה כידוע בענין וידבר<sup data-n=\"1347\">30</sup> שלשת אלפי' משל כו' או עד\"מ האבוקה דכל שהיא גדולה יותר יותר תאיר למרחוק להאיר גם במקום חושך ואפילה ואם אינה גדולה לא תאיר למרחוק רק למקום קרוב ולא במקום חושך ביותר כו'. וכיוצא בכל אלה יובן הנמשל למעלה בטעם השפלת המדות הטבעיי' להיות למטה מן הדעת לפי ששרשם הוא למעלה מן הדעת כנ\"ל בפי' טעם המאמר דז\"א בע\"י עצמו אחיד למעלה מחו\"ב כו' והוא הטעם שיורדין למטה כ\"כ כו' וד\"ל.\n<b>ובכ\"ז</b> מתורץ הקושי' הנ\"ל בענין האבות הן המרכבה כו'. דהנה מבואר למעלה דשרש האבות הוא בבחי' חג\"ת דז\"א בבחי' הכלים דוקא והוא כמו בחי' דו\"ר טבעיי' למטה שהן למטה מן המוחין כו' אך מ\"מ שרש עצמיותם הוא בבחי' עתיקא עצמו ולזה אמרו דיפה כח הבן גם מכח האב שהוא בחי' מוחין דאבא כו' (וגם יפה מכח מקור המוחין דאבא הנק' משכיל כנ\"ל ששרש טבע המדות בבחי' כשב\"כ כו') וא\"כ הרי יפה כח האבות שנק' מרכבה לז\"א גם מבחי' המוחין דאו\"א דנפקין ממו\"ס דא\"א כו' כמו שרש אהבה דאברהם איש החסד שרשו הוא בבחי' אה\"ר שבעצמות הכתר כו' (וכמ\"ש במ\"א שזהו מ\"ש ושמר<sup data-n=\"1348\">31</sup> לך את הברית והחסד אשר נשבע לאבותיך כו' ע\"ש) משום דז\"א בע\"י עצמו אחיד כנ\"ל וזהו הטעם שיש ביכולת האבות שנק' מרכבה לז\"א להעלות לבחי' אדם קדמאה גם שהוא בחי' אור אבא כמ\"ש מה שמו כו' כנ\"ל (וגם ביכולתם להעלות לבחי' ח\"ס מקור אור אבא ג\"כ מטעם ששרשם בבחי' כתר שבכתר כו' כנ\"ל שגם בחי' ח\"ס הרי נק' חכמה וע\"ז נאמר ג\"כ והחכ'<sup data-n=\"1349\">32</sup> מאין תמצא וכמ\"ש יהיב<sup data-n=\"1350\">33</sup> חכמתא לחכימין כו' עד\"מ כאשר נמשך תוס' כח ואור חדש בכח המשכיל ההיולי כו' שנק' חכימין כו' ולמעלה הוא בחי' התלבשות אא\"ס בחכ' להיות נק' חכים וד\"ל). וע\"ד הנ\"ל בחיות שבמרכבה דבריאה שנושאות את הכסא דאדם התחתון כו' כך האבות שהן בבחי' חג\"ת דז\"א מעלין לבחי' א\"ק מטעם שיפה כח הבן מכח האב מצד שרשו למעלה מבחי' מוחין דאב כו' כנ\"ל וד\"ל.\n<b>וזהו</b> מארז\"ל ע\"פ ועשיתם<sup data-n=\"1351\">34</sup> אתם כאלו עשאוני כו' פי' לפי שישראל בהיות שהן המרכבה להעלות לבחי' א\"ק כנ\"ל הנה אחר בחי' ההעלאה הזאת נמשך בחי' תוס' אור מעצמות אא\"ס בחכ' שנק' א\"ק כנ\"ל בבחי' המשכה שנמשך באדם התחתון ע\"י בחי' ההעלאה דמרכבה התחתונה דפני ארי' כו' והיינו להיות בחי' התלבשות אא\"ס בחכ' שנוכל לומר עליו אנת חכים כו' כי אא\"ס מצד עצמו למעלה גם מבחי' מקור לחכמה וכמ\"ש לא דאית לך מכל אינון מדות כלל אך ע\"י בחי' העלאות דנשמות הצדיקים דוקא שהן בחי' מרכבה לז\"א כנ\"ל וז\"א בע\"י עצמו אחיד כו' ע\"כ יומשך אח\"כ בחי' המשכה מעצמות אא\"ס בחכ' (גם להיות בחי' ח\"ס כו') וזהו",[["1347","30","<b>וידבר שלשת אלפים משל</b>: מלכים-א ה, יב."],["1348","31","<b>ושמר לך את הברית והחסד</b>: דברים ז, יד."],["1349","32","<b>והחכ' מאין תמצא</b>: איוב כח, יב."],["1350","33","<b>יהיב חכמתא לחכימין</b>: דניאל ב, כא."],["1351","34","<b>ועשיתם אתם כאילו עשאוני</b>: זח\"ג קיג, א. וראה ויק\"ר פל\"ה, ז."]]],[2101000223,"שארז\"ל כאלו עשאוני להמשיך בחי' חכמה כו' והוא בחי' יחוד דחו\"ב שבק\"ש בב' תיבות דה' אלקינו שיהיו מקבלי' ממו\"ס כו' כנ\"ל וד\"ל.\n<b>אך</b> עדיין י\"ל לכאורה בתירוץ הקושי' הנ\"ל דאם מטעם שז\"א בע\"י אחיד כו' יפה כח האבות להעלות לבחי' חכמה ג\"כ כנ\"ל למה אמרו דישראל<sup data-n=\"1352\">35</sup> עלה במח' שאינה אלא לבוש בעלמא למדות ואין למח' דמיון כלל עם מדות טבעיי' כו' וגם מבואר למעלה דזהו פי' המאמר דאיהו וגרמוהי שהוא התאחדות המחשבה בשכל כו' א\"כ הרי אין שרשם במדות רק בחכ' ולא למעלה מן החכמה והדרא קושי' לדוכתא למה נק' האבות מרכבה להעלות לבחי' אדם כו'.\n<b>אך</b> הנה כ\"ז יובן בהקדים פי' ישראל ובפרט במה שבפסוק ראשון דק\"ש או' שמע ישראל דוקא ולא אברהם או יצחק כו'. דהנה יעקב שנק' ישראל אמר אלקי<sup data-n=\"1353\">36</sup> אבי אברהם ופחד יצחק הי' לי כו' וידוע דשרש אברהם הוא בחי' החסד דקו הימין חח\"נ כו' ושרש יצחק הוא בקו השמאל בחי' גבורה והוא הנק' פחד יצחק כו' שהן ב' הפכים זה בבחי' או\"י מלמעלה למטה וזה בבחי' או\"ח מלמטה למעלה כטבע המים והאש שהן ב' הפכי' טבע המים שיורדין מגבוה לנמוך וטבע האש לעלות כו' וא\"כ איך אמר יעקב אלקי אבי אברהם בחי' או\"י וגם פחד יצחק שהוא בבחי' א\"ח כו' האיך ישכנו ב' הפכים כא' כו'. אך הענין הוא משום דיעקב<sup data-n=\"1354\">37</sup> נק' בריח התיכון כו' הכולל ב' הקוין ימין ושמאל והוא בחי' ת\"ת שכולל חו\"ג וישראל הוא בחי' דעת שכולל חו\"ב כו' ולכך ארז\"ל דיעקב<sup data-n=\"1355\">38</sup> לא מת מפני שלא יש יניקה מקו האמצעי לחיצוני' ולא כאברהם<sup data-n=\"1356\">39</sup> שיצא ממנו ישמעאל כו' ולכך<sup data-n=\"1357\">40</sup> נק' יעקב בחיר שבאבות ולהיותו בבחי' קו האמצעי ע\"כ אמר ע\"ע אלקי אבי אברהם פי' אברהם הוא בבחי' קו הימין דחכ' וחסד הנק' ימין מקרבת ולפי שאור אבא מקור החסדי' אמר אלקי אבי אברהם וגם בחי' שמאל דוחה דקו השמאל הנק' פחד יצחק הי' לי שנכלל בקו האמצעי דיעקב ופי' הי' לי שנמשך אלי ליכלל הגבורות בחסדים (כי בחי' ז\"א רובו חסדים כידוע) וזהו הטעם שאמרו דיעקב לא מת לפי שז' מלכים שמתו ונפלו למטה שרש אחיזתם בקו השמאל כידוע ואמנם כאשר הגבורות דקו השמאל נכללו בחסדי' דקו האמצעי לא יש ממילא שום יניקה לסט' דמות כו' ועיקר הטעם מפני שיעקב מקבל מבחי' החכ' שבקו הימין וכמ\"ש אלקי אבי אברהם<sup data-n=\"1358\">41</sup> אב\"ר<sup data-n=\"1359\">42</sup> מ\"ה דחכ' וכתיב ימותו<sup data-n=\"1360\">43</sup> ולא בחכ' לפי שבחי' החכמה הוא בחי'",[["1352","35","<b>דישראל עלה במח'</b>: ב\"ר בתחילתו. ובכ\"מ."],["1353","36","<b>אלקי אבי אברהם ופחד יצחק</b>: בראשית לא, מב."],["1354","37","<b>דיעקב נק' בריח התיכון</b>: זח\"ב קעה, ב. וראה אוה\"ת ויחי שצה, ב."],["1355","38","<b>דיעקב לא מת</b>: תענית ה, ב. ובכ\"מ."],["1356","39","<b>כאברהם שיצא ממנו ישמעאל</b>: פסחים נו, א. ויק\"ר פל\"ו, ה. ספרי ואתחנן ו, ד. ועוד."],["1357","40","<b>ולכך נק' יעקב בחיר שבאבות</b>: שער הפסוקים תולדות כז, כה. וראה ג\"כ ב\"ר פע\"ו, א. זח\"א קיט, ב. קמז, ב."],["1358","41","<b>אברהם אבר מ\"ה דחכ'</b>: ראה זח\"א ד, א. וראה תו\"א מג\"א צ, א."],["1359","42","<b>אב\"ר</b>: בכת\"י ב: אב."],["1360","43","<b>ימותו ולא בחכ'</b>: איוב ד, כא."]]],[2101000224,"הביטול שהוא היפוך בחי' הישות והגסות שמשם שרש יניקת החיצוני' שנק' מות כו' וד\"ל.\n<b>והנה</b> כמו שיעקב נק' בריח התיכון לחבר ב' הפכים דחו\"ג דאברהם ויצחק למטה כך בחי' ישראל דלעילא שהוא בחי' דעת עליון דכתר שרש הקו האמצעי דת\"י מחבר ומייחד לב' הפכים דחו\"ב שהן כללות הב' קוין כידוע והוא מ\"ש ישראל<sup data-n=\"1361\">44</sup> לסגולתו בחי' סגול העליון דכח\"ב (וכמ\"ש<sup data-n=\"1362\">45</sup> במ\"א על<sup data-n=\"1363\">46</sup> מאמר הזהר בפסוק כי יעקב בחר לו י\"ה כו'). וזהו שאנו אומרים ביחוד עליון דפסוק ראשון דק\"ש שמע ישראל דוקא לפי שישראל זה היינו בחי' דעת עליון שמייחד חו\"ב ועל ידו יהי' יחוד דחו\"ב שנק' ה' אלקינו וז\"ש שמע ישראל ה' אלקינו וד\"ל. וזהו שארז\"ל דישראל<sup data-n=\"1364\">47</sup> עלה במח' כו' ע\"ד שאמרו יעקב<sup data-n=\"1365\">48</sup> משמש במרום כו' דהנה המחשבה הוא מבחי' אותיות שנק' בשם כלים למדות כנראה בחוש שהמדות שבלב כאשר יתפעלו מיד יתלבשו במחשבה לחשוב ולהרהר מה שלבו חפץ ונק' הרהורי לבו והן בחי' הכלים להגביל ולהלביש אור התפעלות המדה כו' דהיינו לצייר אופן התפשטותה והתגלותה בכמה אופנים שונים והן כלים מכלים שונים כו' ולמעלה הנה שרש נשמות הצדיקים נמשכו מפנימי' הכלים דהיינו מבחי' המח' שנק' לבושין לגופא דמנהון פרחין נשמתין לב\"נ כו' והמלאכים נמשכו מחיצוניות הכלים כידוע וזהו שהאבות נק' מרכבה למדות עליונות מפני ששרשם במח' עליונה. אך הנה אמרו בזהר<sup data-n=\"1366\">49</sup> דאית מחשבה ואית מחשבה כו', דהיינו מח' שלמטה מן המדות כנ\"ל ומח' עילאה דבינה שהיא מקור המדות והוא בחי' אותיות השכל שבלעדן לא יומשך התפעלות בלב כידוע ולמעלה מעלה מן השכל ג\"כ יש בחי' אותיות דמח' עליונה יותר שמשם נמשך שרש חו\"ב דאצי' והוא בחי' גילוי הרגשת הדעת עליון שהוא בחי' גילוי המשכת חו\"ב דא\"א לייחד חו\"ב הנגלית באצי' כנ\"ל וז\"ש דיעקב משמש במרום לייחד חו\"ב דאצי' ע\"י התגלות בחי' דעת עליון ודוקא יעקב שהוא בחי' ת\"ת שכולל חו\"ג ע\"י התלבשות הכלים והלבושים דוקא שהוא בחי' מח' תתאה כנ\"ל וזהו שאמרו ג\"כ דישראל עלה במח' עליונה שלמעלה מחו\"ב לייחדם מפני שהאבות בחי' מרכבה למדות בבחי' מח' תתאה ומטעם הנ\"ל בפי' המאמר דז\"א בע\"י אחיד כו' וע\"כ במרכבה שלהם למדות הטבעיות עולין במח' עילאה שלמעלה גם מחכ' שנק' א\"ק כנ\"ל. ובזה מתורץ הקושי' הנ\"ל דגם שהמח' למטה לבוש בעלמא למדות אבל מצד שהן בחי' המרכבה נושאות למדות דז\"א למעלה במח' עילאה שלמעלה מחו\"ב לייחדם כו' וז\"ש שמע ישראל דוקא כנ\"ל וד\"ל (ונמצא מיחוד איהו וגרמוהי נעשה יחוד דאיהו וחיוהי כו' וד\"ל).",[["1361","44","<b>ישראל לסגולתו</b>: תהלים קלה, ד."],["1362","45","<b>וכמ\"ש. . הזהר</b>: בכת\"י ב: וכמא' הזהר."],["1363","46","<b>על מאמר הזוהר בפסוק כי יעקב בחר לו י\"ה</b>: זח\"א קסא, ב. זח\"ב קכו, א. וראה ביאוה\"ז ל, ד. נא, ג. פ, א. תו\"ח וירא קי, ג. וישלח קצב, ג ואילך. ס' מאמרי אדהאמ\"צ במדבר ח\"א ע' קנב. וש\"נ."],["1364","47","<b>דישראל עלה במח'</b>: ב\"ר בתחילתו. ובכ\"מ."],["1365","48","<b>יעקב משמש במרום</b>: זח\"א קלג, א. וראה ביאוה\"ז יג, ד ואילך."],["1366","49","<b>בזהר דאית מחשבה ואית מחשבה</b>: ראה ת\"ז תי' סט (קטו, א)."]]],[2101000225,"<b>ואחר</b><sup data-n=\"1367\">50</sup> כל הנ\"ל יש לבאר שרש ענין זכור ושמור בדיבור א' נאמרו כנ\"ל. דהנה ידוע דזכור<sup data-n=\"1368\">51</sup> לדכורא ושמור לנוק' ושרש הדברים הנה הוא שבת דמעלי שבתא ושבת דיממא דשבת דמעלי שבתא הוא בחי' שמור לנוק' ושבת דיממא הוא בחי' זכור לדכורא כו' (וע\"ז רמזו רז\"ל אלמלא שמרו ישראל שתי שבתות כהלכתן א' מלמטה למעלה והב' מלמעלה למטה).\n<b>וביאור</b> הדברים הנה בחי' דכר ונוק' ידוע שהוא בחי' ההעלאה ובחי' ההמשכה והנה בחי' שבת דמעלי שבתא הוא בחי' ההעלאה מלמטה למעלה וע\"כ אומרים בליל שבת מזמור לדוד וברכו כו' ומזמור שיר ליום השבת כו' ובסעודת הלילה אומרים אזמר בשבחין כו' וביום שבת או' בקידוש זכור את יום השבת כו' מפני שהוא בחי' ההמשכה וכמ\"ש וקראת<sup data-n=\"1369\">52</sup> לשבת עונג וכל קריאה בחי' המשכה מלמעלה למטה כידוע (אבל בליל שבת אומרים בקידוש ויכולו השמים כו' שהוא בחי' ההעלאה כמו כלתה<sup data-n=\"1370\">53</sup> נפשי וכן ויכל אלקים כו') ולכך אומרים בסעודת היום דא היא סעודתא דעתיקא ובלילה אומרים דא היא סעודתא דחקל תפוחין כו'<sup data-n=\"1371\">54</sup> וכמ\"ש במ\"א). וביאור ענין בחי' ההעלאה בליל שבת הנה יובן עד\"מ מי שהוא בעל שכל מופלג בחכמה כאשר צריך להוריד ולצמצם כל כח חכמתו לכלול א\"ע בדבר קטן מאד כמו לצייר או לכתוב ה\"ז בחי' ירידה גדולה לגבי כח חכמתו ובודאי לא שכל חכמתו ממש מתצמצמת ומתלבשת באותו ציור או כתיבה ושאר מלאכה שהרי אין מהצורך לציור או כתיבה בחי' עמקות חכמה כלל רק בכח התנועה ובמחשבה בעלמא די לעסוק בה וא\"כ בהכרח לומר שכח חכמתו העצמי' אז נשארת בהעלם ובצמצום עצמותו בלתי מתפשטת במוחו מפני שמצמצם א\"ע לכלול א\"ע בדבר המלאכה וע\"כ ממילא מובן שכאשר חוזר ונח ושובת מאותו הציור והכתיבה שבעבורו נתצמצם אזי חוזר ג\"כ הארת כח חכמתו להיות כבראשונה והוא<sup data-n=\"1372\">55</sup> הנק' נייחא דרוחא וכמו מי שטרוד בעומק חכמה אחת ובא חבירו ומבלבלו בשאלת בדבר מה מענינים קטנים מאד שבהכרח מתצמצם ברגע זו הארת השגתו בדבר החכ' שהי' טרוד בה מפני שמסיח דעתו ברגע זו מאותו העומק בהכרח לפי שמצמצם א\"ע לשמוע מה ששואלו חבירו כו' וא\"כ מיד שהלך חבירו ממנו שהוא שב אל עומק השגתו כמבראשונה נק' נייחא דרוחא ג\"כ לפי שבא אור השכל אל עצמות כחו ושובת ונח מצמצומו א\"ע לשמוע דבר בטל כו' וכך הוא ענין צמצום החכ' מפני צמצום עצמו באיזה מלאכה גשמי' בציור וכתיבה כנ\"ל וד\"ל.\n<b>ונמצא</b> מובן מזה עכ\"פ שבחי' השביתה מן הציור והכתיבה וכיוצא הוא גורם מנוחת כח השכל שיעמוד במעמדו הראשון ולא יתעלם ויתצמצם עוד",[["1367","50","<b>ואחר כל הנ\"ל</b>: להבא לקמן — ראה גם ד\"ה זכור ושמור בס' מאמרי אדהאמ\"צ תקע\"ז ע' קכג."],["1368","51","<b>דזכור לדכורא ושמור לנוק'</b>: זח\"ב צב, א."],["1369","52","<b>וקראת לשבת עונג</b>: ישעי' נח, יג."],["1370","53","<b>כלתה נפשי</b>: תהלים פד, ג."],["1371","54","<b>כו'). . במ\"א)</b>: כ\"ה בהכת\"י. וחסר התחלת מוסגר."],["1372","55","<b>והוא הנק' נייחא דרוחא</b>: ראה זח\"א ע, א."]]],[2101000226,"והוא הנק' בחי' ההעלאה מלמטה למעלה כי השביתה הגשמי' מן הציור ודאי הוא בחי' העלאה דהיינו שחוזר צמצום כח התנועה וצמצום כח המחשבה אל בחי' כח עצמותם ממש וממילא עי\"ז חוזר ג\"כ ועולה בחי' אותו כח המצומצם של השכל מה שמצמצם ע\"י בעבור זה (כמו שמצמצם עומקו בהשגה כדי לשמוע שאלת חבירו כנ\"ל) אל כח עצמותו ממש וממילא ינוח כח השכל ויעמוד בעמדו הראשון כמו שתנוח המח' ותעמוד בעצמות כחה כששובת ונח מן הציור וכיוצא וע\"כ נק' כ\"ז בשם בחי' ההעלאה מלמטה למעלה הנק' בחי' א\"ח למקורו כך כח השכל חוזר אל מקורו ועצמו וגם כח המח' כו' וד\"ל.\n<b>והנמשל</b> מכ\"ז יובן למשכיל למעלה בבחי' שרש שבת דמעלי שבתא כמ\"ש ויכל אלקים כו' כנ\"ל דהיינו שבחי' צמצום כח הפועל דשם האלקי' דמל' דאצי' בבי\"ע חוזר ועולה אל בחי' עצמותה כי הנה בחי' חכמה דמל' דאצי' שמהווה הכל מאין ליש הוא רק כדמיון צמצום מחשבת אדם בציור וכתיבה וכה\"ג לגבי עצם מהות אור חכ' דמל' (שבתוכה מלובש חכמה דז\"א שבתוכה מלובש חכמה דאור אבא עד בחי' חכ' דא\"ס ממש כו') וכאשר אמר ויכל אלקים כו' היינו שביתת מלאכה זו שהצמצום חזר אל עצמות חכמתו להיות במעמדו הראשון כנ\"ל והוא הנק' בחי' אור חוזר למקורו דהיינו שבחי' חכמתו עצמי' המאציל חזר לעצמותו מפני שנתעלה מצמצומו א\"ע למטה בי' מאמרות דאצי' ודבריאה כו' ונק' נייחא דרוחא החכמה וכמ\"ש כי בו שבת וינפש וע\"ד משלי' הנ\"ל וד\"ל. וזהו ענין שמור לנוק' שהוא בחי' ליל שבת מפני שהוא בחי' ההעלאה מלמטה למעלה כנ\"ל וע\"כ או' מזמור לדוד כו' ובקידוש או' ויכולו ויכל אלקי' כו וישבות כו'. אך בשבת דיממא הוא בחי' ההמשכה מלמעלה למטה והוא בחי' זכור לדכורא כמ\"ש בקידוש היום זכור את יום השבת כו' וכנ\"ל.\n<b>וביאור</b> זה הנה יובן ג\"כ ע\"ד הנ\"ל במשל מלאכה גשמי' בציור וכתיבה כו' דהנה אנו רואים בחוש שלאחר שגמר אדם איזה מלאכה כמו ציור או כתיבה ובנין וכה\"ג הגם שמסתלק צמצום שכלו ומחשבתו ובאין אל עצמותם כנ\"ל הנה מיד אחר ההעלאה הזאת חוזר ונעשה בחי' ירידה והמשכה מעצמות חכמתו לדבר המלאכה ההיא כי הרי מתחיל להסתכל בחכמתו הטיב הדק בכל פרטי מעשהו שעשה אם טובה היא. עד\"מ אומן חרש חכם שהגם שתחלת פעולתו ודאי הייתה עפ\"י שכלו ולימודו בציור מלאכת האומנות מ\"מ פעולתו נעשי' צמצום עצמות כח חכמתו כנ\"ל אך לאחר שגמר מלאכת הציור ומתבונן בה אם טובה ויפה היא הרי צריך להעמיק בה בכל עצמו' תבונתו שהיא הרבה יותר מצמצום הארתה בפעולת מלאכתו שאינה אלא עפ\"י לימודו בחכמת האומנות בלבד אבל בחי' ההסתכלות וההתבוננו' בדקדוק המלאכה לאחר שנגמרה שאז כבר עלה בצמצום שכלו בעצמותה הנה היא בכל כח שכלו העצמי שנק' בחי' כח היולי להשכיל בכל חכ' כו' וד\"ל. ונמצא הרי אחר בחי' אור החוזר הנ\"ל נעשה בחי' או\"י להוריד ולעיין במלאכה ולהעמיק בה בעצמות שכלו. ואמנם בחי' חזרת המשכה זאת אינו נק' צמצום כח השכל כמו בשעת פעולת המלאכה כנ\"ל מאחר שאינו עושה כלום רק"],[2101000227,"שמשכיל ומתבונן באיכות פרטי המלאכה בלבד והרי כח השכל עומד במעמדו בלתי צמצום א\"ע לכלל א\"ע בפעולה פרטיות כנ\"ל רק בחי' ירידה קצת יש לכח השכל והוא מה שמעיין בו בכל חלקי פרטי המלאכה שצריך להעלות כל חלקיה בפרט בשכלו וגם חכמת המלאכה כולה כלא חשיבי לגבי עצם כח שכלו אך מ\"מ אין זה צמצום כח שכלו ממש מאחר שכל כח שכלו פנוי לעיין בה כו' וד\"ל. ונמצא דהגם שעיון זה במלאכה בכח שכלו הוא רק חלק מכל כחה מ\"מ אינו נק' צמצום עצמותו ממש רק בחי' ירידה והמשכה נקראת כמו כל ירידה והמשכה שאין ההמשכה רק חלק קטן נבדל מגדול כו' וד\"ל.\n<b>והדוגמא</b> מכ\"ז יובן למעלה ג\"כ בבחי' שבת דיממא שהוא בחי' ההמשכה מלמעלה למטה דהיינו לאחר שהי' ההעלאה בליל שבת כנ\"ל בפי' ויכל אלקים כו' וישבות כו' אח\"כ ביום השבת התבונן המאציל בכל אשר עשה וברא והאציל כו' והנה טוב מאד כו' והרי בחי' התבוננו' זאת באה מכח עצמו' חכמת המאציל לאחר שעומד בעצמותו אחר השביתה מי' מאמרות כנ\"ל ואין זה נק' בחי' צמצום כח חכמתו במה שמתבונן בלבד אך מ\"מ בחי' ירידה נחשבת לגבי עצם כח חכמתו ית' וכמובן ממשל הנ\"ל ואעפ\"י שנק' ירידה מ\"מ נק' בחי' המשכה מלמעלה למטה כנ\"ל וז\"ש ביום השבת וקראת לשבת עונג בבחי' ירידת ההמשכה מעצמות עונג חכמתו וז\"ש זכור את יום השבת כו' והוא ג\"כ מ\"ש ויברך אלקים את יום הז' לאחר שאמר וישבות כו' וד\"ל (אך בחי' ההעלאה מכל אשר עשה עד שהוטב בעיניו ג\"כ ביום ולא בלילה ול\"ד להעלא' צמצום המלאכה דליל שבת כו' וכמ\"ש במ\"א שהוא בחי' העלאת היופי של המלאכה שהיא בחי' העונג כו' משא\"כ בהעלא' נייחא דרוחא הנ\"ל) וע\"כ יש שיר ומזמור גם ביום השבת כמו אסדר לסעודת' כו' כי העלא' זו עם המשכתה נעשה הכל ביום כו' וד\"ל). וזהו זכור ושמור בדיבור א' נאמרו דבשעת מ\"ת הי' בחי' ההעלאה דשמור ובחי' ההמשכה דזכור כנ\"ל בדיבור א'.\n<b>ויובן</b><sup data-n=\"1373\">56</sup> זה בהקדם ענין עוה\"ב שהוא מעלה יתירה הרבה ממעלת הג\"ע העליון דעכשיו וכמ\"ש<sup data-n=\"1374\">57</sup> בפירש\"י<sup data-n=\"1375\">58</sup> וברמב\"ן בשער הגמול כי בזמן תחה\"מ ועוה\"ב יהי' עיקר השכר והגמול. והנה בתחה\"מ ועוה\"ב שאמרו דכל<sup data-n=\"1376\">59</sup> ישראל יש להם חלק לעוה\"ב אפי' פושעי ישראל לפי שכל מקיים איזה מצוה יש לו חלק לעוה\"ב ואפי' פושעי ישראל יש להם חלק לעוה\"ב לפי<sup data-n=\"1377\">60</sup> שמלאים מצות כרימון כו' מלבד אותן מה שמנו חכמים בפרטות שלא יקומו בתחה\"מ ואין להם חלק לעוה\"ב והן מעט מזעיר וזה לכאורה כפלא יחשב מאחר שהעוה\"ב במעלה גדולה מג\"ע כנ\"ל למה לא יזכו",[["1373","56","<b>ויובן זה בהקדם ענין עוה\"ב</b>: בהבא להלן ראה בארוכה תשובות וביאורים מכ\"ק אדמו\"ר זי\"ע סי' ח'."],["1374","57","<b>וכמ\"ש בפירש\"י</b>: ראה בארוכה תשובות וביאורים שם הע' א."],["1375","58","<b>בפירש\"י</b>: בכת\"י ב וכת\"י ג: במפרשים. וכ\"ה בתו\"א יתרו עג, ב."],["1376","59","<b>דכל ישראל יש להם חלק לעוה\"ב</b>: סנהדרין צ, א."],["1377","60","<b>לפי שמלאים מצות כרימון</b>: עירובין יט, א."]]],[2101000228,"בג\"ע רק הצדיקים המופלגים וכמ\"ש<sup data-n=\"1378\">61</sup> על לוי אכתי לוי מאברא כו' ולא<sup data-n=\"1379\">62</sup> יש רק י\"ח אלפים שורות כו', וכמ\"ש<sup data-n=\"1380\">63</sup> סביב שמנה עשר אלף כו' וכמבואר בדרז\"ל, ולעוה\"ב כל ישראל יש להם חלק. אך הנה ההפרש בין ג\"ע לעוה\"ב הוא במה שבג\"ע הנשמות בלבד נהנין מזיו האלקי בלתי מלובשים בגופי' חומריי' אבל בעוה\"ב יהנו גם הגופי' מזיו אור האלקי כי אז יהי' הנשמות מלובשים בגופים כמו עכשיו והיינו ענין תחה\"מ שגוף גשמי יקום ויחי' מחיי' החיים בחי' אא\"ס ממש כמ\"ש במתים שהחי' יחזקאל מארבע<sup data-n=\"1381\">64</sup> הרוחות בואי הרוח ופחי בעצמות האלה כו' וזה הדבר אינו מובן לכאורה דהלא ק\"ו הוא אם במדריגת זיו האלקי שבג\"ע לא יוכלו הגופים לקבל העונג האלקי הזה העליון האיך יוכלו הגופים לקבל מדריגת זיו האלקי שיאיר בתחה\"מ ועוה\"ב שלמעלה ממדריגת ג\"ע כנ\"ל שתענוג האלקי שבעוה\"ב הרבה יותר מתענוג הנשמות בג\"ע (ומ\"ש<sup data-n=\"1382\">65</sup> באחר מוטב לדייני' ביסורי גיהנום וליתי לעלמא דאתי אע\"פ שבודאי עשה מצות אפשר שהי' מאותן שאין להם חלק לעוה\"ב כו'). אך הענין הוא דמטעם זה אדרבא היא הנותנת לומר דבעוה\"ב יוכלו גם הגופים לקבל לפי שמעלתו גבוה יותר להיות ידוע שכל הגבוה גבוה יותר יותר יוכל להשפיל א\"ע והוא מטעם שלגבי מדריגת אא\"ס שנק' בחי' מקיף וסוכ\"ע שוין רוחניי' וגשמיו' נשמו' וגופי' וגם הגופי' יוכלו לקבל כמו הנשמות משום דקמי' ממש כחשכה כאורה כו' כמשל העיגול שאין בו מעלה ומטה כו' וידוע דעוה\"ב שרשו מבחי' כתר שבחכ' והוא מ\"ש ביו\"ד<sup data-n=\"1383\">66</sup> נברא העוה\"ב ביו\"ד דחכ' שנמשך מאור הכתר והוא מ\"ש עין<sup data-n=\"1384\">67</sup> לא ראתה כו' לפי שהנשמו' שבג\"ע דעכשיו אינם רואים ומשיגים בג\"ע התחתון רק בבחי' בינה שבמל' או בבינה שבבינה בג\"ע העליון (והוא הנק' גן לעדן אבל עדן עצמו עין לא ראתה כו') והיינו ההפרש בין עצם התענוג שבחכ' לבחי' גילוי התענוג שבבינה כידוע ומבואר במ\"א שזהו כמשל התגלות התענוג שבא בהשגת איזה שכל וסברא שאין לזה ערך לעצמות התענוג שמתלבש בנקודת חכ' ולמעלה היינו בחי' עונג העליון שמלובש במעשה<sup data-n=\"1385\">68</sup> המצות שנקראין תר\"ך עמודי אור שבכתר (דהיינו [י\"ג] חיוורתי דע\"י בחי' הלבנונית שמשם נמשך תרי\"ג ארחין כו' וד\"ל). וזהו שאמרו דכל ישראל יש להם חלק לעוה\"ב אפי' פושעי ישראל לפי שמלאים מצות וע\"י המצות נעשה למעלה בחי' כתר שהוא בחי' מקיף עטרה על המוחין שבראש ששם רוחניות וגשמיות שוין וע\"כ גם הגופים יוכלו לקבל כנ\"ל (וכמ\"כ בתחה\"מ שיקומו הכל חוץ מאותן שמנו חכמים בפרט כנ\"ל משום שנאמר כי<sup data-n=\"1386\">69</sup> טל אורות טליך שהוא",[["1378","61","<b>וכמ\"ש על לוי אכתי לוי מאברא</b>: ברכות יח, ב."],["1379","62","<b>ולא יש רק י\"ח אלפים שורות</b>: ראה סוכה מה, ב."],["1380","63","<b>וכמ\"ש סביב שמונה עשר אלף</b>: יחזקאל מח, לה."],["1381","64","<b>מארבע הרוחות באי הרוח</b>: ראה יחזקאל לז, ט."],["1382","65","<b>ומ\"ש באחר מוטב לדייני'</b>: חגיגה טו, ב. וראה ג\"כ תו\"א הנסמן לעיל בריש המאמר (יתרו עג, ב). לקו\"ת בשלח א, ד. ויקרא (הוספות) נב, ב. דרמ\"צ א, ב. ובכ\"מ."],["1383","66","<b>ביו\"ד נברא העוה\"ב</b>: מנחות כט, ב. ירושלמי חגיגה פ\"ב ה\"א. זח\"א ד, א. ובכ\"מ. וראה אגה\"ק ס\"ה."],["1384","67","<b>עין לא ראתה</b>: ישעי' סד, ג."],["1385","68","<b>במעשה המצות שנק' תר\"ך עמודי אור</b>: ראה אגה\"ק סכ\"ט. פרדס ש\"ח פ\"ג."],["1386","69","<b>כי טל אורות טליך שהוא בחי' טלא דבדולחא</b>: ישעי' כו, יט. וראה זח\"ג קכח, ב. קלה, ב."]]],[2101000229,"בחי' טלא דבדולחא כו' דהיינו ג\"כ בחי' ירידת והתלבשות האור מבחי' עונג העליון הנ\"ל שלמעלה מחו\"ב ששם הכל שוין כו'). והטעם שנק' כתר עד\"מ הכתר הנעשה מאבנים טובות הגשמיים ונותנין על הראש לתפארת כך ממצות שנעשין בבחי' דצ\"ח דנוגה הגשמיי' אך להיותם מבחי' רפ\"ח ניצוצין דתוהו ולאחר הבירור הם מאירים עד\"מ האבן כשמבהיק אור שהוא דבר פלא ונאה להיות על הראש כו' כך המצות נעשין בחי' כתר למעלה על בחי' המוחין העליונים וכמ\"ש מט\"ט<sup data-n=\"1387\">70</sup> יושב וקושר כתרים לקונו כו' ממעשה המצות של ישראל ולזה הטעם מובן שרש ענין אריכות הגלות הזה כי לעתיד בתחה\"מ ועוה\"ב יתגלה בחי' הארת אור הכתר העליון כנ\"ל וכדי שיבא לידי גילוי צריך להיות קיום כל המצות בכל נפש מישראל בפ\"מ כדי שיתגלה בכללות ולא בפרטות ובלתי ישראל לא יוכל להיות גילוי אור הכתר בכללות כי הרי הן קומה שלימה שנק' אדם כידוע וגם מטעם המצות שא\"א שיומשך אור הכתר על ידן רק ע\"י ישראל דוקא כי להם ניתן הכח הזה בקיום המצות ולא לזולתם כנ\"ל בענין קבלת התורה שמי שאינו מבנ\"י או אשה וקטן שפטורי' אינם ממשיכי' כלום כשעושין מצות כידוע וד\"ל.\n<b>ובכ\"ז</b> כבר מתורץ הקושי' הנ\"ל למה לא יזכו בג\"ע רק הנשמות של הצדיקים כו' כי בג\"ע אין ההארה רק מבחי' ממכ\"ע שנק' א\"פ שנמשך מחכ' לבינה מאין ליש וכמ\"ש להנחיל<sup data-n=\"1388\">71</sup> אוהבי יש ע\"כ אינן יכולין לקבל רק הנשמות שנהנין מזיו האלקי בג\"ע והוא אינו אלא קבלת שכר לפי שעה בלבד עד שיתגלה בחי' הכתר שנק' סוכ\"ע בזמן תחה\"מ ועה\"ב שהיא עיקר השכר והגמול כנ\"ל ואז הכל יכולים לקבל מטעם הנ\"ל דכל שמעלתו גבוה יורד למטה יותר כו' וד\"ל.\n<b>ובכ\"ז</b> יובן ג\"כ מארז\"ל דבשעה<sup data-n=\"1389\">72</sup> שאמרו ישראל נעשה ונשמע ירדו מלאכים עליונים וקשרו ב' כתרים לכאו\"א א' כנגד נעשה והב' כנגד נשמע רק שבחטא העגל נטלו מהם אותם ב' הכתרים וכמ\"ש ויתנצלו<sup data-n=\"1390\">73</sup> בנ\"י את עדיים מהר חורב כו'. וביאור הדברים מובן עפ\"י הנ\"ל דמן קבלת מעשה מצות נעשה למעלה בחי' כתר ועטרה כו' וע\"כ גם ישראל שהן בדוגמת כנ\"י דלעילא שהוא בחי' המל' נמשך עליהם ג\"כ בחי' כתר על כאו\"א בשעה שקיבלו עליהם המצות ואמרו נעשה ונשמע וזהו הנק' עדיים כמשל העטרה מאבני' טובות שנק' עדי וכמ\"ש ותבואי<sup data-n=\"1391\">74</sup> בעדי עדיים כו' והוא הנק' קישוטי כלה כו' וד\"ל. אך מה שנמשך עליהם ב' כתרי' א' כנגד נעשה והב' כנגד נשמע הענין הוא לפי שידוע שיש ב' מדריגות או\"י ואו\"ח בחי' או\"ח הוא העולה מלמטה למעלה ואו\"י הוא היורד מלמעלה למטה וכמ\"כ יש ב' מיני כתרים הא' הנעשה מבחי' או\"ח מצד בחי' העלאת מ\"נ כמו מבחי' ביטול היש",[["1387","70","<b>מט\"ט יושב וקושר כתרים לקונו</b>: זח\"א לז, ב. וראה הערת כ\"ק אדמו\"ר זי\"ע בסה\"מ תש\"ח ע' 202."],["1388","71","<b>להנחיל אוהבי יש</b>: משלי ח, כא."],["1389","72","<b>דבשעה שאמרו ישראל נעשה ונשמע</b>: שבת פח, א."],["1390","73","<b>ויתנצלו בנ\"י את עדים</b>: שמות לג, ו."],["1391","74","<b>ותבואי בעדי עדיים</b>: יחזקאל טז, ז."]]],[2101000230,"של המלאכים כמ\"ש<sup data-n=\"1392\">75</sup> בזוהר ע\"פ גבורי כח עושי דברו כו' או כמו בענין הכתר שנעשה מתפלות ישראל וכן המלאכים כתר יתנו כו' והב' הכתר הנעשה ע\"י בחי' או\"י שנמשך ויורד מלמעלה למטה מעצמות כמו בשבועות שנתגלה וירד אור הכתר וכמ\"ש וירד<sup data-n=\"1393\">76</sup> ה' כו' וידבר אלקים כו' אנוכי כו' שהוא בחי' הכתר וגם כאן הרי כשאמרו ונשמע ה\"ז בחי' ההעלאה וביטול המציאות מכל וכל כמו מי שמסכים דעתו ורצונו לשמוע כל מה שיצוינו זולתו הרי מבטל כל חושיו וכל מחשבותיו רק לשמוע ונכלל בזה ביטול פנימי ביטול כל רצונותיו מכל וכל כי מאחר שהוחלט אצלו לציית לכל אשר יגזור עליו הרי כבר בהכרח ביטל כל רצונותיו לנגד רצון המצוה להיות מוכן לעבודתו גם שיהי' נגד רצונו וזהו פי' ונשמע לקיים רצונו ולא שמיעה באוזן בלבד ונמצא בבחי' שמיעה זאת הוא בחי' העלאת כל פנימי' הנפש כאו\"א מישראל באמרן ונשמע למעלה לגבי בחי' רצה\"ע שישמעו כמ\"ש בטל<sup data-n=\"1394\">77</sup> רצונך מפני רצונו כו' וכך נתבטלו כל רצונם לרצה\"ע והוא הנק' בחי' או\"ח ונעשה עי\"ז בחי' כתר אחד וע\"י שאמרו נעשה שהוא בחי' ירידת ההמשכה למטה דהיינו קיום זה הרצה\"ע להביאו במעשה ממש אחר שיקבלוהו בשמיעה עי\"ז נמשך אור הכתר בבחי' או\"י מלמעלה למטה כו' והן<sup data-n=\"1395\">78</sup> הנה ב' הכתרים. אך הן הקדימו נעשה לנשמע כלומר נעשה ונמשיך למטה בחי' רצה\"ע אשר נשמע אותו בבחי' העלאה כו' נמצא בחי' או\"י קדם לבחי' או\"ח וז\"ש הקב\"ה מי גילה רז זה לבני שהקדימו נעשה לנשמע כו' לפי שלא הי' יורד או\"י רק לפי ערך העלאה דאו\"ח אם היו מקדימי' שמיעה לעשי' אבל הם הקדימו עשי' לשמיעה כדי שיומשך רצון מלמעלה מבחי' ההשתלשלו' והוא מבחי' רצה\"פ שאינו בא אלא מעצמו שלא יגיענו העלאת מ\"נ כלל (וכמ\"ש במ\"א וד\"ל).\n<b>ואחר</b> כל הנ\"ל יובן מ\"ש דבשעת מ\"ת דוקא זכור ושמור בדיבור א' נאמרו לפי שע\"י קבלת המצות דבשעת מ\"ת הראה להם מעין ודוגמת העוה\"ב ותחה\"מ דלעתיד כי לעתיד הרי יתגלה אור הכתר הנק' סובב הכללי ע\"י גמר קיום כל המצות בפ\"מ כנ\"ל בפי' כל ישראל יש להם חלק ובשעת מ\"ת קיבלו ע\"ע ע\"כ וירד ה' על הר סיני ואמר אנוכי שהוא גילוי אור הכתר ג\"כ כנ\"ל. והנה כל וי\"ו אלפי שנה דהוי עלמא יש בחי' עליות וירידות הנק' העלאות והמשכות כמו בכל ימות החול נעשה בחי' העלאה בליל שבת כנ\"ל שנק' שמור לנוק' וביום השבת נמשך בחי' המשכה שנק' זכור לדכורא כנ\"ל באורך וכמ\"כ יש יו\"ט ור\"ח וכן כל יום ויום יש עליות העולמות והמשכות כו' בפרט ובכל שנה בכלל ומשמיטה לשמיטה עד ימוהמ\"ש כידוע אך<sup data-n=\"1396\">79</sup> באלף הז' שאז זמן תחה\"מ ועוה\"ב נק' יום שכולו שבת כלומר שאין בו ענין העלאה והמשכה אלא כולו שבת ומנוחה ונק' מנוחה לחיי העולמי' פי' בחי' מנוחה העצמי' שלמעלה מבחי' השתלשלות בקו\"ח כו' ששם אין עליות וירידות",[["1392","75","<b>כמ\"ש בזוהר ע\"פ גבורי כח עושי דברו</b>: זח\"ג קצ, ב."],["1393","76","<b>וירד ה' כו' וידבר אלקים</b>: שמות יט, כ."],["1394","77","<b>בטל רצונך מפני רצונו</b>: אבות פ\"ב מ\"ד."],["1395","78","<b>והן. . הכתרים</b>: בכת\"י ב ליתא תיבות אלו."],["1396","79","<b>אך באלף הז'. . נק' יום שכולו שבת</b>: משנה סוף מס' תמיד. וראה ג\"כ יהל אור ע' תרכז, תשכ."]]],[2101000231,"כלל שאין שם המנוחה כמו כי<sup data-n=\"1397\">80</sup> בו שבת מבחי' מלאכה שהייתה בתחלה כו' כי לאחר תשלום כל הבירורי' לא יהי' בחי' העלאה כלל וממילא לא תהי' בחי' המשכה וא\"כ הרי יהי' שמה<sup data-n=\"1398\">81</sup> העלאה והמשכה כו' והיינו מפני שאז יתגלה בחי' סובב הכללי שלמעלה מבחי' הקו כו' שאין בו מעלה ומטה כלל כנ\"ל בשרש ענין המצות וד\"ל. וזהו שהראה להם הקב\"ה בשעת מ\"ת מה שיהי' לעתיד באמרו להם זכור ושמור שהוא בחי' ההעלאה וההמשכה בדיבור א' מה שאין הפה יכול לדבר ואין האזן יכולה לשמוע פי' פה הוא בחי' המל' כמ\"ש<sup data-n=\"1399\">82</sup> בס\"י וקבען בפה כו' ואזן<sup data-n=\"1400\">83</sup> הוא בבחי' בינה כידוע ושניהם הן בבחי' עליות וירידות וא\"א שיהי' בהן זכור ושמור דכר ונוק' כא' ממש אך ביו\"ד שנמשך מן הכתר שהוא שרש העוה\"ב כנ\"ל שם יכול להיות זכור ושמור בדיבור א' ממש כי שם שוין בחי' רוחניות וגשמיות וכן משפיע ומקבל יחד כו' וכדוגמא זאת ג\"כ נמשך להם ב' כתרים א' מבחי' או\"י והב' מבחי' או\"ח כנגד נעשה ונשמע ומפני שהקדימו נעשה לנשמע כנ\"ל הטעם הרי נכללו כא' וכן העלאה והמשכה דזכור ושמור וכללו כא' בדיבור א' דנקודת חכמה שבו הארת הכתר כו' מה שאין הפה יכול לדבר אותם כא' שהרי המל' אינה עולה ויורדת כא' וכן באזן דבינה שהוא בחי' שמיעה דנק' או\"ח אינה יכולה לשמוע כא' רק בבחי' הכתר שם נאמרו כא' כו' וד\"ל.\n<b>ומעתה</b> יש לבאר שרש ענין רכב<sup data-n=\"1401\">84</sup> אלקים רבותים אלפי שנאן כו' ותחלה יש לבאר שרש אדנ\"י ב\"ם כו' ברפ\"ה כו' דהנה ידוע בספרי המדקדקים שכל דגש מורה ענין ההתחלה דוקא אך כאן לא שייך בחי' התחלה בתיבת בם דקאי על המרכבה דרכב אלקים כו' אלפי שנאן דהיינו פני ארי' ופני שור כו' שהן נמשכו ונתהוו מבחי' מל' דאצי' מאין ליש כידוע והיינו פי' הפשוט דאדנ\"י בם שהוא בחי' מל' דאצי' שנק' בשם אד' להיותו אדון כל המעשי' ונק' כח הפועל בנפעל כידוע וא\"כ האיך יהי' נק' המרכבה שנתהוו משם אד' בשם התחלה וראש לגבי מקור חוצבם שם אד' שהוא בחי' הראש והמקור שלהם כו'. אך הנה מבואר למעלה דהמרכבה הן מעלים לשם אד' השוכן בהם מטעם ששרשם מבחי' התוהו כו' כמו המרכבה שמעלה את הרוכב כנ\"ל וא\"כ הרי בחי' שם אד' נכלל בתוכם וכמ\"ש<sup data-n=\"1402\">85</sup> בזוהר ע\"פ שרפים עומדי' ממעל לו ממעל לשכינתי' כו' לפי שהמרכבה נושאות את הכסא ומאחר שיש ביכולתם להעלותה כו' א\"כ בהכרח שיש בהן בחי' מעלה ומדריגה מצד שרשם גבוה משם אד' ומצד זה נק' הם בחי' ראש לגבי בחי' שם אד' ונמצא דאין כאן בחי' ראש וסוף כלל כי שניהם מתכללי' זב\"ז והראש נעשה סוף והסוף נעשה ראש וע\"כ אין דגש בתיבת בם אלא הוא רפה כו' וד\"ל.",[["1397","80","<b>כי</b>: בכת\"י ב: כמו."],["1398","81","<b>שמה</b>: בכת\"י ב: שוה."],["1399","82","<b>כמ\"ש בס\"י וקבען בפה</b>: פ\"ב מ\"ג."],["1400","83","<b>ואזן הוא בבחי' בינה</b>: ראה זח\"ג קלח, ב. ע\"ח שער אח\"פ פ\"ג. ובכ\"מ."],["1401","84","<b>רכב אלקים רבותים אלפי שנאן</b>: תהלים סח, יח. וראה יהל אור שם."],["1402","85","<b>וכמ\"ש בזוהר ע\"פ שרפים עומדים ממעל לו ממעל לשכינתי'</b>: ישעי' ו, ב. וראה זח\"ג מז, א. עט, ב. זח\"ב קמז, ב. וראה ביאוה\"ז עח, א. ביאוה\"ז להצ\"צ ע' שעו. אוה\"ת נ\"ך ע' קנט ואילך."]]],[2101000232,"<b>ובכ\"ז</b> יובן ג\"כ מה שאנו מוצאים שבכל מקום לא הייתה גילוי שכינה בלא מרכבה וכמ\"ש ויעל<sup data-n=\"1403\">86</sup> אלקי' מעל אברהם וארז\"ל שנסתלקה המרכבה כו' וגם ביעקב נאמר מחנה<sup data-n=\"1404\">87</sup> אלקים זה וכן בשאר כל התגלות שכינה כמו באהל מועד דכתיב במשה וישמע<sup data-n=\"1405\">88</sup> את הקול מבין שני הכרובים שהן בחי' מט\"ט וסנד\"ל כידוע וכן<sup data-n=\"1406\">89</sup> בנבוא' דישעי' ויחזקאל הרי ראו את המרכבה אלא שישעי' ראה בחי' מרכבה דבריאה ויחזקאל ראה בחי' מרכבה דיצי' כידוע וכן כל נביא לפי שרש מקור נבואתו בי\"ס דבי\"ע נתגלה אלי' בחי' מרכבה שבאותו עולם לפי שא\"א להיות גילוי שכינה מבלעדי מרכבה מפני שכלולה [בהם] והן מעלים אותה כנ\"ל וד\"ל.\n<b>ועתה</b> י\"ל שרש ענין רכב אלקים רבותיי' אלפי שנאן כו'. דהנה ארז\"ל שהקב\"ה<sup data-n=\"1407\">90</sup> בלילה מאי קא עביד רוכב על כרוב קל שלו ושט בח\"י אלף עולמות שנאמר רכב אלקי' כו' א\"ת שנאן אלא שאינן (מפני שמספר רבותיי' הן ב' רבוא שהוא מספר כ' אלפים וח\"י אלף הוא מספר החיל שעומדי' סביב כמ\"ש סביב<sup data-n=\"1408\">91</sup> שמנה עשר אלף והרי נחסר ב' אלפי' ממספר כ' אלפים וזהו שאינן שנחסרו ב' אלפים וע\"כ נק' אלפי שנאן וזהו דרך דרש ופי' שנאן הוא כללות המרכבה פני ארי' כו' והיינו ר\"ת דשנא\"ן ש\"ור נ\"שר א\"רי' א\"דם כידוע). וזה המאמר כולו פלאי לכאורה דאיך יתכן ענין הרכיבה למעלה ומהו הכרוב קל שלו ולמה בחי' ח\"י אלף עולמות דוקא.\n<b>אך</b> הנה יש להקדים תחלה בשרש בחי' מט\"ט<sup data-n=\"1409\">92</sup> שנק' עבדו זקן ביתו המושל בכל אשר לו וכמ\"ש בזהר ובסה\"ק ובדרז\"ל ג\"כ ע\"פ נער<sup data-n=\"1410\">93</sup> הייתי גם זקנתי שרו של עולם אמרו ולפעמים נק' נער מט\"ט ולפעמים נק' זקן ביתו כו' כמ\"ש<sup data-n=\"1411\">94</sup> בזהר ע\"פ אנוש כחציר ימיו כו' דהוא בחי' מט\"ט שמתחדש בכל שבוע כו' וכמ\"ש במ\"א. והנה כל הנהגות העולמות בו' יומין דחול שהן בחי' מוחין דקטנות הוא ע\"י בחי' ו\"ק דיצי' שהוא בחי' מט\"ט וסנדל הוא בבחי' ו\"ק דעשי' וז\"ש כי<sup data-n=\"1412\">95</sup> שרית עם אלקים שהוא ע\"ס דבריאה ועם אנשים מט\"ט וסנדל כמ\"ש בכתבי האריז\"ל בכמה דוכתי ובתיבת מט\"ט יש ב' טיתי\"ן והן לנגד ח\"י ברכאן בשחרית עד שמ\"ע שהוא בחי' מט\"ט דיצי' ולאחריהם הן ח\"י ברכאן דצלותא שהוא בבחי' האצי' וזהו ח\"י ח\"י הוא יודוך והטעם שיש בו ב' טתי\"ן ידוע לפי שיש בו בחי' או\"י ובחי' או\"ח וכללותו אינו אלא בחי' מדות דקטנות שהן כלולים מחב\"ד וע\"כ הוא רק ט\"ס ולפעמים הוא בבחי' או\"י ולפעמים הוא בבחי' או\"ח וזהו הטי\"ת הא' בבחי' או\"י מלמעלה למטה והטי\"ת הב'",[["1403","86","<b>ויעל אלקי' מעל אברהם וארז\"ל שנסתלקה המרכבה</b>: בראשית יז, כב. ב\"ר פמ\"ז, ו. וראה תורה שלמה שם."],["1404","87","<b>מחנה אלקים זה</b>: בראשית לב, ג."],["1405","88","<b>וישמע את הקול. . שהן בחי' מט\"ט וסנד\"ל</b>: במדבר ז, פט. זח\"ג רל, ב."],["1406","89","<b>וכן בנבוא' דישעי' ויחזקאל</b>: ישעי' פ\"ו. יחזקאל פ\"א."],["1407","90","<b>שהקב\"ה בלילה מאי קא עביד</b>: ע\"ז ג, ב."],["1408","91","<b>סביב שמונה עשר אלף</b>: יחזקאל מח, לה."],["1409","92","<b>מט\"ט שנק' עבדו זקן ביתו</b>: זח\"א קכו, ב."],["1410","93","<b>נער הייתי גס זקנתי שרו של עולם</b>: תהלים לז, כה. יבמות טז, ב. וראה יהל אור ע' קמב."],["1411","94","<b>כמ\"ש בזוהר ע\"פ אנוש כחציר ימיו</b>: תהלים קג, טו. זח\"ג רטז, ב. ריז, ב."],["1412","95","<b>כי שרית עם אלקים</b>: בראשית לב, כט."]]],[2101000233,"מלמטה למעלה (ומיט\"ט ביו\"ד הוא כשעולה בבחי' בריאה וכמ\"ש במ\"א באריכות) והוא הנק' כרוב קל כי הנה ידוע דשרש ב' הכרובי' שעל הכפורת הן בחי' מט\"ט וסנדל שהן בחי' ו\"ק דיצי' ובחי' ו\"ק דעשי' כנ\"ל ופי' כרוב קל הוא בחי' מט\"ט לבדו שכלול בו בחי' ו\"ק דעשי' וע\"כ נק' בשם כרוב א' ונק' קל לפי שעולה ב\"פ כמספר דשם אד' כי שם אד' עולה מספר ס\"ה וב\"פ ס\"ה עולה ק\"ל והיינו מ\"ש בו הנני<sup data-n=\"1413\">96</sup> שולח מלאכי לפניך השמר בו כו' כי שמי בקרבו כו' ולהיותו בבחי' הקטנות ע\"כ הוזהרו להשמר שלא ימרו בו כי לא ישא לפשעם כו' וכאשר<sup data-n=\"1414\">97</sup> לא נתלבש עדיין בו\"ק דעשי'<sup data-n=\"1415\">98</sup> נק' כרוב קל וזהו פי' מ\"ש הקב\"ה רוכב על כרוב קל שלו פי' הקב\"ה הוא בחי' ו\"ק דבריאה שנק' ז\"א דבריאה שבתוכו מלובש בחי' ז\"א דאצי' ובחי' ו\"ק דיצי' נק' מט\"ט והוא עבדו זקן ביתו המושל בכל אשר לו להנהגות העולמות בימות החול כנ\"ל ובח\"י ברכאן דצלותא עולה בחי' מט\"ט דיצי' בבחי' ו\"ק דבריאה וכשהאדם<sup data-n=\"1416\">99</sup> כורע בברוך וזוקף בשם למטה כך למעלה בחי' אדם דבריאה כורע בברוך וזוקף בשם והיינו בחי' ח\"י חוליות דז\"א דבריאה שעולה בבחי' ו\"ק דאצי' ולזה רמזו במ\"ש שהוא שט בח\"י אלף עולמות פי' ח\"י אלף עולמות הללו היינו בחי' ח\"י אלפים מדריגות שמתחלקים ומקבלי' מבחי' ו\"ק דאצי' מפני שעולה גם הוא ח\"י לפי שבחי' ז\"א דאצי' ג\"כ רק ט\"ס וב' טיתי\"ן א' בבחי' או\"י והב' בבחי' או\"ח כו' וגם להיות כי כל עיקר בחי' אדם הוא רק ט\"ס חב\"ד חג\"ת נה\"י רק כאשר מתכלל כאו\"א מט' הרי טפ\"ט עולה פ\"א וג\"פ פ\"א לנגד הגדלת ג' מיני כלים פנימי ואמצעי וחיצון רת\"ס הרי עולה רמ\"ג וה\"ח המגדילי' עולה רמ\"ח והן רמ\"ח<sup data-n=\"1417\">100</sup> אברים דאדם כמ\"ש בע\"ח וד\"ל.\n<b>ולהבין</b> ביאור כ\"ז הנה יש להקדי' מ\"ש בשני הכרובי' שהי' פניהם<sup data-n=\"1418\">101</sup> איש אל אחיו דוקא דהנה שני הכרובי' הם בחי' מט\"ט וסנדל כו' ומ\"ש פניהם איש אל אחיו היינו בחי' היחוד דמט\"ט וסנדל ולכך היו כדמות דכר ונוק' כו' כידוע. וביאור הענין הנה ידוע דבי\"ע היינו בחי' מדו\"מ והמח' שבהעלם הוא בחי' בריאה והדיבור הוא בבחי' יצירה כו' והנה הגם שהדיבור הוא בבחי' היצירה הנה מ\"מ יש בו יחוד יצי' ועשי' וגם הוא בחי' ממוצע שבו מתחבר בריאה ועשי' וכוללם יחד. דהנה אנו רואים במהות הדיבור שעיקרו אינו אלא בהוצאת הקול בה' מוצאות הפה אחה\"ע מהגרון גיכ\"ק מהחיך כו' ובלא גילוי הקול בה' מוצאות הפה אינו נק' בשם דיבור כלל והראי' ממשז\"ל בכמה דוכתי דהרהור<sup data-n=\"1419\">102</sup> לאו כדיבור דמי עד שיוציא בשפתיו דוקא משום דעקימת<sup data-n=\"1420\">103</sup> שפתיו הוי מעשה וא\"כ הרי בחי' עשי' נכלל בבחי' הדיבור",[["1413","96","<b>הנני שולח מלאכי לפניך</b>: ראה שמות כג, כא ואילך."],["1414","97","<b>וכאשר. . נק' כרוב קל</b>: בכת\"י ב ליתא תיבות אלו."],["1415","98","<b>דעשי'</b>: בכת\"י ג: דיצי' נק' מט\"ט עבדו והוא זקן ביתו המושל בכל אשר לו (והנהגת העולמות) דעשי' נק' כרוב קל שלו."],["1416","99","<b>וכשהאדם כורע בברוך וזוקף בשם</b>: ראה ברכות יב, א."],["1417","100","<b>רמ\"ח אברים דאדם כמ\"ש בע\"ח</b>: שער פרקי הצלם פ\"ו."],["1418","101","<b>פניהם איש אל אחיו</b>: שמות כה, כ. לז, ט."],["1419","102","<b>דהרהור לאו כדבור דמי</b>: ברכות כ, ב."],["1420","103","<b>דעקימת שפתיו הוי מעשה</b>: ב\"מ צ, ב. ובכ\"מ. וראה תניא פל\"ז."]]],[2101000234,"מאחר שאינו נק' בחי' דיבור עד שיהי' בו בחי' עשי' להוציא בשפתיו אותיו' בומ\"ף וגיכ\"ק מהחיך שכ\"ז בחי' עשי' נחשב דודאי כמו שעקימת שפתיו הוי מעשה בפרט לענין אותיות בומ\"ף שיוצאין מן השפתיי' כך כל אותיות דגרון וחיך ולשון שכולן הפה גומר בשפתיים שכללות הדיבור בפה הוא וכמ\"ש מי<sup data-n=\"1421\">104</sup> שם פה לאדם ונק' פי המדבר בכלל ג\"כ כולו בחי' עשי' נחשבת בעקימת שפתי' ואמנם מהות הדיבור עצמו מובדל מבחי' עשי' דה' מוצאות רק שמתלבש בה' מוצאות כידוע שעיקר ענין הדיבור הוא בחי' הבל הלב שיוצא בקול בה' מוצאות שהוא בחי' קול רוחני להוציא מהעלם המחשבה לידי גילוי דהיינו כמו שיש קול גשמי המתגלה בדיבור הגשמי כך יש בחי' קול רוחני שהוא בחי' הבל הלב הרוחני שמוציא העלם המח' שיבא לידי גילוי באותיו' הדבור שהוא בחי' המשכה רוחניות.\n<b>וא\"כ</b> הרי מובן מכ\"ז דהדיבור הוא בחי' ממוצע לחבר בחי' העלם המח' באותיו' הדיבור דהיינו מה שהאדם יכול לדבר מה שחושב במח' בהעלם ונמצא מחבר בחי' בריאה ועשי' שבה' מוצאות כנ\"ל ובגופו של דיבור הנגלה בקול גשמי בו מתייחדי' בחי' יצי' ועשי' דהיינו גילוי הדיבור עצמו עם בחי' העשי' שבעקימת שפתיו בפה כנ\"ל ונמצא הדיבור כולל יצי' ועשי' בעצמו וגם כולל בחי' בריאה ויצי' וזהו בחי' מט\"ט דיצי' שלפעמים עולה בבריאה ומביא משם לידי גילוי בדיבור וגם כולל בעצמו בחי' העשי' והיינו ענין שני הכרובי' שהיו פניהם איש אל אחיו דהיינו מט\"ט וסנדל יצי' ועשי' שמתייחדי' יחד בדיבור כנ\"ל כי העשי' נכלל ביצי' וע\"כ היו כדמות דכר ונוק' שהנוקבא נכלל בדכורא וגם הוא נק' כרוב קל להעלות את האדם דבריאה שהוא בחי' ו\"ק דבריאה בבחי' האצי' וזהו שארז\"ל הקב\"ה שהוא בחי' ז\"א דבריאה והן המדות שמלובשים במח' רוכב על כרוב קל שלו שהוא בחי' הדיבור שנק' מט\"ט עבדו זקן ביתו כו' כנ\"ל וכמו בח\"י ברכאן דצלותא שהדיבור מעלה לבחי' ח\"י חוליות דו\"ק דבריאה באצי' כנ\"ל כך בלילה הקב\"ה רוכב על כרוב קל שהוא בחי' מט\"ט דיצי' ומעלה אותו לבחי' ז\"א דאצי' בח\"י אלף עולמות שלו כנ\"ל ופי' וש\"ט בבחי' עליות דוקא כי בחי' המרכבה נושא לרוכב וכמ\"כ מורידו למטה וכך ביום מורידו לבחי' המדו' דאצי' שיתלבשו בו\"ק דבריאה שהן בבחי' המח' עד שבאין לידי גילוי בדיבור ועשי' בי' מאמרות כמ\"ש כי<sup data-n=\"1422\">105</sup> חסד אל כל היום אך בלילה הוא בחי' הסתלקות הדיבור שנק' כרוב ק\"ל כנ\"ל ועל ידו ש\"ט ועולה בחי' אלף עולמות כו' וד\"ל.\n<b>ובכ\"ז</b> מובן מ\"ש רכב אלקים רבותים אלפי שנאן פי' אלקים הוא בחי' ו\"ק דבריאה ורכב אלקים הוא בחי' מט\"ט דיצי' שנק' כרוב ק\"ל מפני שמספרו בכפליי' משם אד' וע\"כ יש בו התכללו' מספר ב' רבוא כי ע\"ס דבריאה שמתחלקים ליו\"ד וי' למאה ומאה לאלף הרי יו\"ד אלפים ובמרכבה דמט\"ט עולה בכפליי' כ' אלפים וז\"ש ואתא<sup data-n=\"1423\">106</sup> מרבבות קודש ב' רבבות אך שנחסרו ב' אלפים כשעולה למעלה בח\"י אלף",[["1421","104","<b>מי שם פה לאדם</b>: שמות ד, יא."],["1422","105","<b>כי חסד א-ל כל היום</b>: תהלים נב, ג."],["1423","106","<b>ואתא מרבבות קודש</b>: דברים לג, ב."]]],[2101000235,"עולמות דאצי' וז\"ש אלפי שנאן א\"ת שנאן אלא שאינן כנ\"ל לפי שבחי' רכיבה זו הוא בחי' העלאה למעלה כנ\"ל בפי' וש\"ט בח\"י אלף כו' וז\"ש ח\"י ח\"י<sup data-n=\"1424\">107</sup> הוא יודוך דוקא בבחי' הודאה לעלות למעלה הוא ח\"י ח\"י שהן ח\"י ברכות דשחרית שהוא בחי' מט\"ט דיצי' וח\"י ברכות דצלותא שהוא בבחי' עלי' ו\"ק דבריאה שש\"ט בח\"י אלף עולמות דאצי' כשזוקף בשם כנ\"ל וד\"ל.",[["1424","107","<b>ח\"י ח\"י הוא יודוך</b>: ישעי' לח, יט."]]],[2101000236,"<h3>ואולם חי אני</h3>\n<b>שבת מברכין תמוז</b>\n<b>ואולם</b><sup data-n=\"1425\">1</sup> חי אני וימלא כבוד ה'<sup data-n=\"1426\">2</sup> את כל הארץ וכו'. ויש להבין לכאורה במ\"ש וימלא כבוד כו' לשון עתיד דוקא הלא כתיב מלא<sup data-n=\"1427\">3</sup> כה\"כ לשון הווה שכבודו מלא עולם תמיד וכמ\"כ כתיב את השמים ואת<sup data-n=\"1428\">4</sup> הארץ אני מלא כו' ולמה אמר וימלא (וגם בלשון שבועה חי אני וימלא שמשמעו על להבא נשבע שיהי' כן). וכמ\"כ י\"ל במה שאנו אומרים ברוך<sup data-n=\"1429\">5</sup> שם כבוד מלכותו כו' דמשמע ענין ברכה והמשכת מלכותו זאת אנו מבקשים על העתיד, ולכאורה כבר הוא מבורך בשם ומלכות כמ\"ש מלכותך<sup data-n=\"1430\">6</sup> מכ\"ע ואין<sup data-n=\"1431\">7</sup> מלך בלא עם כו'. וגם י\"ל שאלת המלאכים כמ\"ש משרתיו<sup data-n=\"1432\">8</sup> שואלים זל\"ז איה מקום כבודו כו', וזה פלא לכאורה דהלא המה עצמם או' מלא<sup data-n=\"1433\">9</sup> כה\"כ שכל הארץ האירה מכבודו בבחי' ההתגלות מאין ליש בכל העולמות ובכל נברא בפרט ואם לאו לא הי' להם קיום מציאות כלל כידוע, וא\"כ מה זה ששואלים איה מקום כבודו כו'. ועוד ענין א' י\"ל בהיות ידוע מארז\"ל דקודם<sup data-n=\"1434\">10</sup> שנבה\"ע הי' הוא ושמו בלבד כו', דהיינו שלא הי' עדיין בחי' השתלשלות העולמות דאבי\"ע כלל רק הי' הוא ושמו העצמי בלבד (שנק' מל' דא\"ס שלפני הקו כו'), וא\"כ י\"ל קודם שנאצל ונברא כו' מי קראו בשמו להיות לכבוד מאחר שאין עוד מלבדו, ולמה אמר שימלא כבוד ה' לקרות בשמו הגדול הלא אין שינוי לפניו מקודם שנבה\"ע כו' כי ממנו נמצאו הכל, ולא יתכן בחי' הכבוד רק על זולתו הנפרד מאתו כו'.",[["1425","1","<b>ואולם</b>: המאמר נמצא בארוכה בס' מאמרי אדהאמ\"צ במדבר ח\"ג ע' א'עח. א'קנד. וראה בשינויים בס' מאמרי אדה\"ז עה\"ת ח\"ב ע' תרכז. דרמ\"צ קעח, א. אוה\"ת שלח ע' תקי וע' תקכז. סה\"מ תרל\"ד ע' רלט (ובהמ\"מ שם)."],["1426","2","<b>ואולם חי אני וימלא כבוד ה'</b>: במדבר יד, כא."],["1427","3","<b>מלא כה\"כ</b>: ישעי' ו, ג."],["1428","4","<b>את השמים ואת הארץ אני מלא</b>: ירמי' כג, כד."],["1429","5","<b>ברוך שם כבוד מלכותו</b>: פסחים נו, א. נוסח ק\"ש."],["1430","6","<b>מלכותך מכ\"ע</b>: תהלים קמה, יג."],["1431","7","<b>ואין מלך בלא עם</b>: בחיי וישב לח, ל. ר\"פ בלק. ועוד. וראה שעהיחוה\"א פ\"ז."],["1432","8","<b>משרתיו שואלים זל\"ז</b>: תפילת מוסף דשבת."],["1433","9","<b>מלא כה\"כ</b>: ישעי' ו, ג. ברכת יוצר."],["1434","10","<b>דקודם שנברא העולם הי' הוא ושמו בלבד</b>: פדר\"א פ\"ג. וראה סה\"מ באתי לגני ח\"א ע' כד, וע' ר. אוה\"ת יתרו ע' תתלט."]]],[2101000237,"<b>אך</b> הנה כ\"ז יובן בהקדי' מ\"ש כי<sup data-n=\"1435\">11</sup> לא מחשבותי מחשבותיכם כו', פי' לא כמו ענין מחשבת ב\"ו שאין מחשבתו פועלת איזה התהוות חיות דבר מה גם כשיחשוב על דבר מה כמה שעות לא יוכל להוסיף אור וחיות בדבר ההוא מלבד שיש<sup data-n=\"1436\">12</sup> מציאות לאותו הדבר בלתי מחשבתו. אבל לא כן ידמה בבחי' מחשבתו ית', שהרי כאשר<sup data-n=\"1437\">13</sup> עלה ברצונו הפשוט שנק' מחשבתו הפשוטה שיהי' התהוות עולמות אצי' בריאה <sup data-n=\"1438\">14</sup>כו' מיד נתהווה שרש התהוותן מבחי' המשכה<sup data-n=\"1439\">15</sup> הזאת ובחי' מחשבה פשוטה זאת הנה היא מקור חוצבן עד עולם, דהיינו כשאמר במחשבתו הקדומה בעצמותו אנא אמלוך להיות בחי' התהוות חוץ ממנו כבי' ולהיות מלך על עם כו' מיד נתהווה שרש ההתהוות שלהם במח' זו שחשב אנא אמלוך כו' כמ\"ש<sup data-n=\"1440\">16</sup> בזוהר בראשי' דבמח' אחת הקדומה בעצמות אא\"ס נמשך כל השתלשלות העולמות העליונים כו' אך הנה מבחי' מח' זאת הפשוטה בעצמותו נמשך מקור התהוות עלמין<sup data-n=\"1441\">17</sup> סתימין דלא אתגליין וע\"ז אמרו דבראשי' נמי מאמר הוא<sup data-n=\"1442\">18</sup>, דהיינו אפי' בחי' חכמה ומח' הקדומה נק' מאמר להיות מקור להתהוות עלמין סתימין, רק<sup data-n=\"1443\">19</sup> שנק' מאמר סתום במחשבה הסתומה כו'. ואח\"כ בבחי' דיבור נתהווה מקור התהוות עלמין דאתגליין כמ\"ש כי<sup data-n=\"1444\">20</sup> הוא אמר ויהי כו', והן כמו הי' מאמרות ויאמר<sup data-n=\"1445\">21</sup> אלקים יהי אור וכיוצא. אבל בבחי' המח' של הע\"מ<sup data-n=\"1446\">22</sup> נבראו עלמין סתימין כו' ונק' מאמר סתום, והיינו<sup data-n=\"1447\">23</sup> ענין מ\"ם פתוחה ומ\"ם סתומה כו' כידוע. וזהו לכבודי<sup data-n=\"1448\">24</sup> בראתיו יצרתיו כו', פי' לכבודי אין כבוד אלא מלכות כמ\"ש מלכותך כו', והיינו מה שעלה במה\"ק אנא אמלוך כנ\"ל זהו לכבודי בראתיו (שהוא בחי' מל' דא\"ס שמאיר בבחי' א\"ק שנק' אדם דבריאה ובכלל הוא בחי' המחשבה כידוע דבי\"ע היינו בחי' מח' דיבור ומעשה כו') פי' בראתיו בבחי' המחשבה להיות התהוות עלמין סתימין כנ\"ל, יצרתיו בבחי' הדיבור בהתהוות עלמין דאתגליין כו', ולמטה היינו ג' עולמות בי\"ע, עולם הנשמות שבג\"ע דבריאה ועולם המלאכים שביצי' ועולם העשי' שהוא שרש עוה\"ז השפל כידוע (ובכלל<sup data-n=\"1449\">25</sup> היינו ג' מיני אדם, אדם דבריאה היינו בבחי' מח' הקדומה הנ\"ל, ואדם דיצי' בחי' גילוי אור",[["1435","11","<b>כי לא מחשבותי מחשבותיכם</b>: ישעי' נה, ח. ובהבא להלן ראה ג\"כ לקו\"ת שה\"ש יז, ג. סה\"מ תקס\"ו ע' קט ואילך. ובכ\"מ."],["1436","12","<b>שיש</b>: באוה\"ת שם: כשיש."],["1437","13","<b>כאשר עלה ברצונו הפשוט</b>: ע\"ח ש\"א ענף ב. ובכ\"מ."],["1438","14","<b>עלמות אצילות בריאה</b>: באוה\"ת שם: העולמות או\"כ."],["1439","15","<b>המשכה</b>: בהוצאה ראשונה ליתא תיבת המשכה."],["1440","16","<b>כמ\"ש בזוהר בראשית דבמח' אחת</b>: ראה לקו\"ת שה\"ש ט, ב. זח\"ב כ, א."],["1441","17","<b>עלמין סתימין דלא אתגליין</b>: ראה ת\"ז בהקדמה ד\"ה פתח אליהו. תי' כב (סג, ב). שעהיחוה\"א פי\"א. ובהבא להלן ראה בארוכה תו\"ח שמות ע' שפז, א. ובכ\"מ."],["1442","18","<b>דבראשית נמי מאמר הוא</b>: ר\"ה לב, א."],["1443","19","<b>רק שנק' מאמר סתום</b>: שבת קד, א."],["1444","20","<b>כי הוא אמר ויהי</b>: תהלים לג, ט."],["1445","21","<b>ויאמר אלקים יהי אור</b>: בראשית א, ג."],["1446","22","<b>הע\"מ</b>: באוה\"ת שם: הע\"ס."],["1447","23","<b>והיינו ענין מ\"ם פתוחה ומ\"ם סתומה</b>: ראה בארוכה תו\"ח שמות הנסמן לעיל. וראה ג\"כ עט\"ר סד, ב. אוה\"ת תצא ע' תתקנב."],["1448","24","<b>לכבודי בראתיו יצרתיו כו'</b>: ישעי' מג, ז."],["1449","25","<b>ובכלל היינו ג' מיני אדם</b>: ראה ע\"ח ש\"ג פ\"א. ובכ\"מ."]]],[2101000238,"המאציל להאציל ע\"ס והוא בחי' ע\"י וא\"א הנק' בחי' ממוצע להביא אא\"ס מן ההעלם לגילוי כידוע, ואדם דעשי' הוא בחי' ז\"א דאצי' מקור דבי\"ע שנק' כולם<sup data-n=\"1450\">26</sup> בבחי' עשי' כידוע וז\"ש לכבודי שהוא בחי' אנא אמלוך בראתיו יצרתיו כו'). והנה בחי' מלוכה זו שנק' כבוד שממנו בא עיקר התהוות כל העולמות כמ\"ש לכבודי בראתיו כו' כנ\"ל היינו להיות דוקא בחי' נפרד מעצמות שע\"ז יתכן בחי' המלוכה כידוע דאין מלך בלא עם, משא\"כ על בנים לא יתכן בחי' המלוכה גם כי ירבו מאד אבל ברוב<sup data-n=\"1451\">27</sup> עם הדרת מלך. וא\"כ הרי בהכרח שהוצרך להיות בחי' צמצום האור בעצמות א\"ס שיתכן לומר במח' הפשוטה אנא אמלוך כנ\"ל, וזוהי בחי' ירידה גדולה מעצמותו מאחר שבאמת אין עוד מלבדו ועל מי ימלוך רק שע\"י הצמצום יוכל להיות התהוות בחי' נפרד מן העצמות להיות נק' מלך כו'. ולפ\"ז צריך לעורר ולהמשיך מעצמות א\"ס ב\"ה שירד מעצמותו להיות עולה במח' ורצה\"פ אנא אמלוך כו' ואז יהי' מקור להתהוות העולמות כנ\"ל.\n<b>ולזאת</b> הנה אנו אומרי' ברוך כבוד ה' ממקומו, פי' ברוך לשון המשכה שיומשך ויתברך בחי' כבוד ה' שהוא בחי' המלוכה הנ\"ל כמ\"ש לכבודי בראתיו כו' ממקומו, פי' ממקור חוצבו בעצמות. והענין הוא כי מקור מקום כבוד ה' שהוא בחי' אנא אמלוך הנ\"ל שעלה במח' ורצה\"פ הנה הוא מיוחד וכלול כבר בהעלם בהעצמות אור א\"ס ממש, רק שיצא מן ההעלם לגילוי במחשבה זו כו'. והטעם הוא, כי הרי גם בחי' המחשבה הזאת היא באה מן ההעלם לגילוי ג\"כ, שהרי עד\"מ באדם הנה כח מחשבתו היא כח היולי להיות בכחו לחשוב כל מה שיצטרך אבל אינה עדיין בבחי' גילוי מחשבה ממש, שהרי היא כלולה עדיין בעצמו' הנפש ונק' עצם כח שכלו ומחשבתו ומיוחדת בעצמו' בתכלית. רק כשצריך לחשוב איזה ענין הנה אז נפרדת מן העצמו' ובאה לידי גילוי מן ההעלם העצמי כידוע. וככה יובן למעלה בעצמו' א\"ס ב\"ה שבחי' כח מחשבתו כלולה ומיוחדת בעצמותו ממש כי<sup data-n=\"1452\">28</sup> הוא המדע כו' ונק'<sup data-n=\"1453\">29</sup> עצם כח חכמתו ומחשבתו כו', רק שבא לידי גילוי מח' ורצון פשוט מבחי' העלם עצמות כח מחשבתו המיוחדת כו'. והוא ענין הנ\"ל דכאשר עלה ברצונו ומחשבתו הפשוטה אנא אמלוך וכיוצא ונמצא הרי יש מקור מחצב בהעלם עצמות כח מחשבתו ית' לגילוי מח' זו דאנא אמלוך, ולזה אומרים ברוך כבוד ה' ממקומו ממקור מקומה של בחי' גילוי מח' זו מן ההעלם העצמות (וזהו ג\"כ פי' לכבודי בראתיו כדי שיבא לגילוי מחשבה שנק' בריאה יש מאין הוא לכבודי מפני מקור מלוכה זו שנק' כבוד כמו שהוא בעצמות שנק' מל' דא\"ס וכלשון<sup data-n=\"1454\">30</sup> הגמ' הי' הוא ושמו בלבד כידוע וגם זה נק' בשם מחשבה כלשון הזהר אבל נק' מח' אחת כלומר כללות והוא בחי' מקיף כללי כידוע, משא\"כ מחשבה זו הבאה בגילוי אנא אמלוך",[["1450","26","<b>כולם בבחי' עשי'</b>: באוה\"ת שם: שנק' כלי דבחי' עשי'."],["1451","27","<b>ברוב עם הדרת מלך</b>: משלי יד, כח."],["1452","28","<b>כי הוא המדע</b>: ראה רמב\"ם הל' יסוה\"ת פ\"ב ה\"י. מו\"נ ח\"א פס\"ח. שמונה פרקים פ\"ח. תניא פ\"ב ובליקוט פירושים ומ\"מ שם."],["1453","29","<b>ונק'. . ומחשבתו</b>: באוה\"ת שם: ונק' עצם הכח חכמתו ומחשבה."],["1454","30","<b>וכלשון הגמ'</b>: באוה\"ת שם: ובלשון חז\"ל."]]],[2101000239,"שזה רק פרטית לפי פרטי ההשתלשלו' דאבי\"ע כו' וד\"ל). ובזה<sup data-n=\"1455\">31</sup> יובן מה שאנו אומרים בב\"ש יחיד חי העולמים מלך, ובישתבח מסיימים הברכה מלך יחיד חי העולמים, כי הנה בחי' ירידת מח' זאת דאנא אמלוך מעצמות כח המחשבה הכלולה ומיוחדת בתכלית בעצמו' א\"ס כנ\"ל הוצרך להיו' ע\"י בחי' ריבוי צמצומים מאד שמצמצם א\"ס א\"ע בכמה מיני צמצומים. וזהו רק מפני רב טובו וחסדו כדי להאיר אורו למטה מטה כמ\"ש בע\"ח, וזהו זכר<sup data-n=\"1456\">32</sup> רב טובך יביעו וצדקתך ירננו, פי' צדקתך הוא להחיות רוח שפלים שנק' צדקה למאן דלית לי' מגרמי' כלום, והיינו להיות מקור להתהוות יש מאין מעצמות א\"ס נק' צדקתך כי אינו רק בחי' צדקה וחסד, וזה בא ע\"י שהוא ית' רב טוב וחסד וע\"כ הוא מצמצם א\"ע בכמה מיני צמצומים בשביל<sup data-n=\"1457\">33</sup> זה, וע\"ד שאמר אמרו<sup data-n=\"1458\">34</sup> צדיק כי טוב שהטוב<sup data-n=\"1459\">35</sup> נק' צדיק, כי עיקר ענין ההטבה של איש הטוב הוא במה שיורד מעצמותו להחיות רוח שפלים ומצמצם א\"ע ומשפיל א\"ע בשביל זה כו'. וכך נאמר למעלה שמפני שהוא ית' טוב בעצם ע\"כ יגרום טובו הגדול לצמצם א\"ע מאד כדי שיוכל להיות מקור לעולמות. וז\"ש זכר רב טובך יביעו ע\"כ וצדקתך ירננו להיות בבחי' מלך על עם כמ\"ש מלכותך<sup data-n=\"1460\">36</sup> מלכות כ\"ע, שבזאת<sup data-n=\"1461\">37</sup> הוא מקור אור חיותם מאין ליש כנ\"ל. וזהו יחיד חי העולמי' מלך, פי' שבעצמותו ממש הוא יחיד ומיוחד בתכלית האחה\"פ ואעפ\"י שהוא חי העולמים אין שינוי לפניו מקודם שנברא כו' כמ\"ש אני<sup data-n=\"1462\">38</sup> הוי' לא שניתי, אך להיות עולה במח' הקדומה אנא אמלוך הוא בא בבחי' ירידה וריבוי צמצומים מפני רוב טובו וחסדו כי חפץ חסד הוא כנ\"ל, וזהו כולל בכללות כל השבחים דב\"ש שיחיד חי העולמים נעשה מלך כו' אבל בישתבח מדבר בירידת והמשכת אא\"ס בנאצלים ונבראים כמו שאמר אל מלך גדול ומהולל בתשבחות כו' ששם<sup data-n=\"1463\">39</sup> בחי' מלך דהיינו מחשבה דאנא אמלוך מקור כל הנשמות והמלאכים וכל העולמות, לכך אומר מלך יחיד חי העולמים שכל חי העולמים כלולים בבחי' מלך יחיד דבמח' הפשוטה הנ\"ל וד\"ל.\n<b>והנה</b> בברכת יוצר אור אנו אומרים מה שהמלאכים אומרים ג\"פ קדוש עד שנעשה ה' צבאות מלא כה\"כ. פי' ג' מיני צמצומי' המה בכלל עד שיהי' מכה\"כ מבחי' המלוכה הנ\"ל שנק' כבוד ה' כנ\"ל בפי' ברוך כבוד ה' ממקומו וכך הוא פי' בשכמל\"ו, וזהו ג\"פ קדוש ל' מובדל ומוסתר עד שיבא לידי גילוי בחי' מח' דאנא אמלוך שנק' כבודו. והיינו כדי שיומשך מכח המח' שבהעלם לגילוי כנ\"ל צריך להיות ג' צמצומי' בהעלם העצמו' תחלה והיינו ג\"פ קדוש שבעצמותו עד שנעשה מכה\"כ וד\"ל. ובזה יתורץ ג\"כ הקושי' הנ\"ל מה שהמלאכי' שואלי' איה מקום כבודו, דר\"ל על מקום ושרש הנעלם של בחי' גילוי כבוד זה שבמח' איך הוא נמשך",[["1455","31","<b>ובזה יובן מה שאנו אומרים בברוך שאמר</b>: ראה ג\"כ תו\"א מקץ מ, ג. אוה\"ת ויחי שצה, ב ואילך. ובכ\"מ."],["1456","32","<b>זכר רב טובך יביעו</b>: תהלים קמה, ז."],["1457","33","<b>בשביל זה</b>: באוה\"ת שם: בשכלו."],["1458","34","<b>אמרו צדיק כי טוב</b>: ישעי' ג, י."],["1459","35","<b>שהטוב נק' צדיק</b>: באוה\"ת שם: שהצדיק נק' טוב."],["1460","36","<b>מלכותך מלכות כ\"ע</b>: תהלים קמה, יג."],["1461","37","<b>שבזאת</b>: באוה\"ת שם: שבאמת."],["1462","38","<b>אני ה' לא שניתי</b>: מלאכי ג, ו."],["1463","39","<b>ששם בחי'</b>: באוה\"ת שם: ששם הוא בחי'."]]],[2101000240,"מעצמו' כח מחשבתו הכלולה בעצמותו ית' דלית<sup data-n=\"1464\">40</sup> מח' תפב\"כ ע\"כ שואלי' איה מקום כבודו להיותו למעלה מכל השגה אפי' משכל הנעלם דא\"ק כו'. ובזה יתורץ גם הקושי' השני' בהיות שקודם ההשתלשלו' הי' הוא ושמו מי קראו בשמו כו' התירוץ הוא דמעצמותו נתעורר כי חפץ חסד הוא ואח\"כ<sup data-n=\"1465\">41</sup> תלוי במעשה התחתוני' כמ\"ש בע\"ח (וז\"ש חי אני וימלא כבוד ה' כו' כמו נשבע<sup data-n=\"1466\">42</sup> ה' בנפשו דהיינו שיבא לידי גילוי מן ההעלם עד\"מ האדם שנשבע להביא מחשבתו הנעלמה לידי גילוי וד\"ל).\n<b>אך</b> הנה עדיין י\"ל איך יוכל להיות בחי' המשכה זו דכבוד ה' ממקומו העצמי כנ\"ל ע\"י המלאכים שאומרים קדוש וברוך כו' מאחר דכולא קמי' כלא וכאין בלי ערך כלל לנגדו אפי' לא כערך טפה בים אוקיינוס כידוע. אך הענין הוא דכתיב תתן<sup data-n=\"1467\">43</sup> אמת ליעקב כו' שהוא ע\"י אמת דיעקב דהיינו ע\"י בחי' מס\"נ<sup data-n=\"1468\">44</sup> שלהם באחד כמ\"ש מי לי בשמי<sup data-n=\"1469\">45</sup>ם כו', דפי' מס\"נ הוא מסירת הרצון שנק' נפש כמו אין<sup data-n=\"1470\">46</sup> נפשי אל העם כו' וכך פי' אליך<sup data-n=\"1471\">47</sup> ה' נפשי אשא בחי' מסירת הרצון בלתי לה' לבדו כו', והוא בחי' ביטול היש לאין עד רום המעלות, ועי\"ז רוח אייתי רוח<sup data-n=\"1472\">48</sup> כו' כמ\"ש אם<sup data-n=\"1473\">49</sup> ישים אליו לבו כו' כידוע להמשיך אתדל\"ע ע\"י אתדל\"ת כזו ג\"כ בבחי' ביטול העצמות דהיינו לצמצם א\"ע להיות רוצה במלוכה הנ\"ל ולעלות במחשבתו<sup data-n=\"1474\">50</sup> אנא אמלוך כנ\"ל. וזהו שמפסיקין בין אחד לואהבת בבשכמל\"ו, הגם דמשה<sup data-n=\"1475\">51</sup> לא אמרו אלא יעקב כידוע, ואנשי יריחו היו כורכין את שמע בלי הפסק בשכמל\"ו אבל אין הלכה כמותם מפני שעיקר בחי' המשכת של כבוד ה' אנא אמלוך מעצמות א\"ס הוא באמרו בשכמל\"ו, וזהו<sup data-n=\"1476\">52</sup> ע\"י יעקב דוקא משום שנאמר יעקב<sup data-n=\"1477\">53</sup> חבל נחלתו שהוא חלק ה' ממש כמא' ישראל עלה במח' סתם דהיינו במח' הכללית דהי' הוא ושמו בלבד שלפני הצמצום שמצמצם א\"ע להיות לו רצון ומח' בגילוי אנא אמלוך כנ\"ל, וע\"כ ביכולתם להמשיך משם להיות גילוי ההעלם. וז\"ש שמע ישראל ה' אלקינו ישראל דוקא מטעם זה, ומטעם זה דוקא יעקב אמר בשכמל\"ו (וכמ\"ש<sup data-n=\"1478\">54</sup> בזהר משה מלגיו יעקב מלבר דמשה בבחי' הדעת ויעקב בבחי' הת\"ת ששם מעורר בחי' המלוכה שהוא יחוד ת\"ת ומל').",[["1464","40","<b>דלית מח' תפב\"כ</b>: ת\"ז ד\"ה פתח אליהו. וראה תניא ספ\"ד ואילך."],["1465","41","<b>ואח\"כ תלוי במעשה התחתונים כמ\"ש בע\"ח</b>: ע\"ח ש\"ח בסופו. ובכ\"מ."],["1466","42","<b>נשבע ה' בנפשו</b>: עמוס ו, ח."],["1467","43","<b>תתן אמת ליעקב</b>: מיכה ז, כ. וראה ג\"כ ביאוה\"ז להצ\"צ ע' שיג ואילך. ובכ\"מ."],["1468","44","<b>מס\"נ שלהם באחד</b>: ראה ב\"ח או\"ח סי' ס\"א. פע\"ח שער הק\"ש פי\"ב."],["1469","45","<b>מי לי בשמים</b>: תהלים עג, כה."],["1470","46","<b>אין נפשי אל העם</b>: ירמי' טו, א. וראה לקו\"ש ח\"ב ע' 456 הערה 9."],["1471","47","<b>אליך ה' נפשי אשא</b>: תהלים כה, א."],["1472","48","<b>רוח אייתי רוח</b>: זח\"ב קסב, ב. וראה אוה\"ת בראשית רפו, ב."],["1473","49","<b>אם ישים אליו לבו</b>: איוב לד, יד."],["1474","50","<b>במחשבתו</b>: באוה\"ת שם: במח'."],["1475","51","<b>דמשה לא אמרו אלא יעקב. . אין הלכה כמותם</b>: פסחים נו, א. וראה ג\"כ סה\"מ ”אתהלך לאזניא\" ע' מג. ובכ\"מ."],["1476","52","<b>וזהו ע\"י</b>: באוה\"ת שם: וזהו פי'."],["1477","53","<b>יעקב חבל נחלתו</b>: דברים לב, ט."],["1478","54","<b>וכמ\"ש בזוהר משה מלגיו יעקב מלבר</b>: ת\"ז תי' יג. וראה לקו\"ת פינחס עח, ג. ובכ\"מ."]]],[2101000241,"<b>וזהו</b> תתן אמת ליעקב א'מ'ת'<sup data-n=\"1479\">55</sup> ראש תוך סוף הכולל כל ההשתלשלו' הוא ע\"י יעקב דוקא מטעם הנ\"ל וד\"ל. וכ\"ז ענין פ' ראשונה דק\"ש באמרו ודברת בם לקשר מחשבה ודיבור במחשבה ודיבור העליון להיות גילוי ההעלם במח' הכללי הנ\"ל ע\"י חכמה שבתורה שנק' ראשי' הגילוי כו' אבל בפ' השניה נאמר ואספת דגנך כו' שהוא ע\"י בחי' הבירורי' דרפ\"ח כו' שנפלו בשבירה בבחי' נוגה דבי\"ע ומזה נתהווה כל חלקי דצח\"מ הגשמיי'. ושרש הכל מז' מלכין קדמאין דתוהו שמתו כמ\"ש וימלוך<sup data-n=\"1480\">56</sup> וימת כו' עד שירד למטה מטה מאד עד שנמשך התהוות הבהמות והחיות הגשמיות מבחי' פני שור ופני ארי' שבמרכבה והתהוות העופות מפני נשר והתהוות נפש החיוני' שבאדם מבחי' פני אדם אשר לארבעתן כו'. ובחי' העלאת הבירורי' דתוהו שבדצ\"ח כמו במאכלים ומשקים וחיות ובהמות כו' היינו ע\"י מס\"נ באחד בק\"ש כנ\"ל שאז מתעלה ג\"כ כל חלקי החיות דמאכלים ולבושים וחלקי החי ומדבר שבאדם ששרשן מבחי' אותיות שנפלו מעולם התוהו וכולן עולין ונכללין בשרשן. כי ע\"י מס\"נ באחד נתאספו ונתקבצו כל האותיות ממקומות שנתפזרו למטה ועולין הכל לשרשן הראשון. וזהו פי' ואספת דגנך שיתאסף כל פרטי בחי' אותיות עליונים דתוהו שנפלו למטה בלחם ויין וכל מיני תענוגי עוה\"ז ליכלל ג\"כ באחד. וזהו ג\"כ מ\"ש וימלא כבוד ה' את כל הארץ, פי' את היינו כ\"ב אותיות שנפלו מלמעלה למטה מא' עד תי\"ו שהמה בחי' התוהו, ונק' את כל הארץ. וע\"י בחי' כבוד ה' המתגלה מן ההעלם ע\"י מס\"נ כנ\"ל יתקבצו כל האותיות הללו וימלא בהן ג\"כ גילוי כבוד ה' כנ\"ל. והיינו ענין פ' שניה דואספת דגנך אחר פ' ראשונה במס\"נ דאחד כנ\"ל (ויש כאן ב' מיני העלאות, א' מס\"נ דמחשבה ודיבור כנ\"ל, והב' העלאו' מ\"נ דמאכלי' וכיוצא אליך ה' נפשי אשא שז\"ש ואספת דגנך).\n<b>אך</b> עדיין י\"ל למה אמר תתן אמת ליעקב דוקא ולא לאברהם ולמה חלק לב' דברים אמת ליעקב וחסד לאברהם. אמנם הענין הוא כידוע דהאבות<sup data-n=\"1481\">57</sup> הן המרכבה וכמו המרכבה שנושאת את הרוכב ומורידו למטה כך והחיות שבמרכבה נושאו' את הכסא כו', ולמעלה היינו ע\"י בחי' העלאות המדות דאבות גורמים בחי' ירידת המשכת כבוד ה' מן העלם עצמותו לידי גילוי כנ\"ל. אך הנה אברהם הי' מרכבה לבחי' חסד עליון של המאציל כמ\"ש אברהם<sup data-n=\"1482\">58</sup> אוהבי, שהי' מעורר בחי' אהבה עליונה וחסד עליון מלמעלה למטה ע\"י בחי' רצו\"ש כמ\"ש הלוך<sup data-n=\"1483\">59</sup> ונסוע כו' כידוע. וכך הי'<sup data-n=\"1484\">60</sup> יצחק בחי' מרכבה לבחי' גבורה עליונה כו', שזהו ענין ב'<sup data-n=\"1485\">61</sup> הקוין חח\"נ ובג\"ה כידוע, ונק' שמאל דוחה וימין מקרבת. אך יעקב אמר אלקי<sup data-n=\"1486\">62</sup> אבי אברהם",[["1479","55","<b>א'מ'ת' ראש תוך סוף</b>: ראה ירושלמי סנהדרין פ\"א ה\"א. ב\"ר פפ\"א. דב\"ר פ\"א. ת\"ז תי' סג (צד, ב). וראה ג\"כ לקו\"ת שה\"ש לח, ב."],["1480","56","<b>וימלוך וימת</b>: בראשית לו, לב ואילך."],["1481","57","<b>דהאבות הן המרכבה</b>: ב\"ר פמ\"ז, ו. ובכ\"מ."],["1482","58","<b>אברהם אוהבי</b>: ישעי' מא, ח. וראה ב\"ר פמ\"א, ח. זח\"א מז, ב. ובכ\"מ."],["1483","59","<b>הלוך ונוסע</b>: בראשית יב, ט."],["1484","60","<b>הי' יצחק בחי' מרכבה לבחי' גבורה</b>: ראה זח\"א קיט, ב. זח\"ג שב, א. ובכ\"מ."],["1485","61","<b>ב' הקוין חח\"נ ובג\"ה</b>: ראה זח\"ג קנג, ב. פרדס ש\"ו פ\"א."],["1486","62","<b>אלקי אבי אברהם</b>: בראשית לב, י."]]]]});
